  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val N, A, B, C, D = ni()

    val NN = 2000

    def powMod(x: Int, n: Int, m: Int): Int = {
      def step(x: Long, n: Int, stack: Long): Long = {
        n match {
          case 0 => stack
          case _ => step(x * x % m, n / 2, if (n % 2 == 1) stack * x % m else stack)
        }
      }
      step(x, n, 1).toInt
    }

    val F = Array.ofDim[Long](NN + 1)
    F(0) = 1
    REP(NN) { i =>
      F(i + 1) = F(i) * (i + 1) % MOD
    }
    val I = Array.ofDim[Long](F.length)
    I(NN) = powMod(F(NN).toInt, MOD - 2, MOD)

    // x! = x(x-1)!
    // x!I(x!) ≡ (x-1)!I((x-1)!)
    // I((x-1)!) ≡ I(x!) * x   MODがでかいので(x-1)!はMODと素
    REP_r(NN) { i =>
      I(i) = I(i + 1) * (i + 1) % MOD
    }

    def comb(n: Int, k: Int): Long = {
      if (n < k) 0
      else F(n) * I(n - k) % MOD * I(k) % MOD
    }

    def rev(x: Int) = {
      I(x) * F(x - 1)
    }

    /**
      * nのグループからk回重複ありで選ぶ組み合わせ数
      * n - 1のしきりとkの○で考える
      */
    def H(n: Int, k: Int) = {
      comb(n + k - 1, k)
    }

    val powI = Array.ofDim[Long](N + 1, N + 1)
    REP(N, 1) { x =>
      powI(x)(0) = 1
      REP(N) { k =>
        powI(x)(k + 1) = powI(x)(k) * I(x) % MOD
      }
    }

    val memo = Array.fill[Long](N + 1, N + 1)(-1)
    def f(n: Int, g: Int): Long = {
      if (n == 0) 1
      else if (n < 0 || g == B + 1) 0
      else {
        if (memo(n)(g) == -1) {
          var res = f(n, g + 1)
          val mx = min(D, n / g)
          REP(mx - C + 1, C) { k =>
            val c = F(n) * I(n - k * g) % MOD *
              powI(g)(k) % MOD *
              I(k) % MOD
            res = (res + f(n - k * g, g + 1) * c) % MOD
          }
          memo(n)(g) = res
        }
        memo(n)(g)
      }
    }

    val ans = f(N, A)
    out.println(ans)
  }


