ll pow(ll a, ll b, ll mod) {
  ll ret = 1;
  ll tmp = a;
  while (b) {
    if (b % 2) {
      ret = ret * tmp % mod;
    }
    tmp = tmp * tmp % mod;
    b /= 2;
  }
  return ret;
}

ll inverse(ll a, ll mod) {
  return pow(a, mod - 2, mod);
}

const ll MOD = 1000000007;

