  ll N, A, B, C, D; cin >> N >> A >> B >> C >> D;
  vvi dp(N + 1, vi(N + 1));

  vvi P(N + 1, vi(N + 1));
  for (ll i = 0; i <= N; i++) {
    ll k = 1;
    for (ll j = 0; j <= N; j++) {
      P[i][j] = k;
      k = k * (i - j) % MOD;
    }
  }

  for (ll i = 0; i <= N; i++) dp[A - 1][0] = 1;
  for (ll i = A; i <= B; i++) {
    for (ll j = 0; j <= N; j++) {
      for (ll k = 0; j - k * i >= 0; k++) {
