          dp[i][j] += dp[i - 1][j - k * i] * P[N - j + k * i][k * i] % MOD * inverse(pow(P[i][i], k, MOD), MOD) % MOD * inverse(P[k][k], MOD) % MOD;
          dp[i][j] %= MOD;
        }
      }
    }
  }
  cout << dp[B][N] << endl;
}

