struct Mod {
  vector<ll> fact;
  vector<ll> finv;
  Mod() {}
  Mod(int n, int p) {
    fact.resize(n + 1); fact[0] = 1;
    for (int i = 1; i < n + 1; ++i) fact[i] = fact[i - 1] * i % p;
    finv.resize(n + 1);
    for (int i = 0; i < n + 1; ++i) finv[i] = mod_pow(fact[i], p - 2, p);
  }
  int extgcd(int a, int b, int& x, int& y) {
    int d = a;
    if (b) {
      d = extgcd(b, a % b, y, x);
      y -= (a / b) * x;
    } else {
      x = 1, y = 0;
    }
    return d;
  }
  ll mod_pow(ll x, ll n, ll m) {
    if (n == 0) return 1;
    ll res = mod_pow(x * x % m, n / 2, m);
    if (n & 1) res = res * x % m;
    return res;
  }
};

