    }

    for(int i=0;i<A;i++){
        dp[i][0]=1;
    }

    for(int i=A;i<=B;i++){
        for(int j=0;j<=N;j++){
            dp[i][j]=dp[i-1][j];
            for(int k=C;k<=min(D,j/i);k++){
                if(j-k*i<0) continue;
                dp[i][j]+=dp[i-1][j-i*k]*p[N-(j-i*k)]%mod*rui(p[N-j],mod-2)%mod*rui(rui(p[i],k)%mod,mod-2)*rui(p[i],mod-2)%mod;
            }
        }
    }

    cout<<dp[B][N]<<endl;
}

