                ll ce=comb.calc(n-(i-k*j),k*j)*comb.fac[k*j];
                ce%=MOD;
                ce*=comb.finv[k];
                ce%=MOD;
                ce*=modpow(comb.finv[j],k);
                ce%=MOD;
                dp[i]+=dp[i-k*j]*ce;
                dp[i]%=MOD;
            }
        }
    }
