        ll num[D+1];
        num[0] = 1;
        rep2(k, 1, D){
            num[k] = (num[k-1]*comb(i*k, i))%MOD;
            num[k] = (num[k]*inv[k])%MOD;
        }
        //i人のグループをk個使う
        rep2(k, C, D){
            if(i*k > N) break;
            rep2(j, i*k, N){
