	ll nl = left;
	if (left >= A)for (int e=1;e<c;++e)mult = (((mult * C(left,A))%MOD) * I[e])%MOD;
	nl -= A*(c-1);

	for (int e=c;e<=d;++e){
		if (nl<A)break;
		mult = (((mult * C(nl,A))%MOD) * I[e])%MOD;
		nl -= A;
