void solve() {
    first();
    dp[N][A - 1] = fact[N];
    FOR(y, A - 1, B) {
        for (int x = N; x >= 1; x--) {
            for (int i = y + 1; i <= B; i++) {
                if (x - i * C < 0)
                    break;
                for (int f = C; f <= D; f++) {
                    if (x - i * f < 0)
                        break;
                    dp[x - i * f][i] += dp[x][y] * iFac[i].pow(f) * iFac[f];
