ll fast_pow(ll a, ll b)
{
	a %= mod;
	ll ans = 1, res = a;
	while(b) {
		if (b % 2) {
			ans *= res;
			ans %= mod;
		}
		b /= 2;
		res *= res;
		res %= mod;
	}
	return ans;
}

ll choose(int N, int K)
{
	return (fact[N] * ((finv[K] * finv[N - K]) % mod)) % mod;
}

ll choose_extend(int N, int k, int j)
{
	return (fact[N] * ((fast_pow(finv[j], k) * finv[k]) % mod)) % mod;
}

