	ll p = 1;
	FOR(i, c, d + 1) {
		if (rem < mi * i) break;
		p = p * nCr(rem - mi * (i - 1), mi) % MOD;

		res += p * dfs(rem - mi * i, mi + 1) % MOD * inv[i] % MOD;
	}

	return dp[rem][mi] = res % MOD;
}

int main() {
	cin >> n >> a >> b >> c >> d;
	fact_inv(n + 100, MOD);

	fill(dp[0], dp[n + 1], -1);
	cout << dfs(n, a) << endl;

	return 0;
}

