    fact[0] = 1; 
    for(int i = 1; i < N; ++i) 
        fact[i] = mul(fact[i - 1], i); 
    inv[N - 1] = Pow(fact[N - 1], mod - 2); 
    for(int i = N - 2; i >= 0; --i) 
        inv[i] = mul(inv[i + 1], i + 1); 
    for(int i = c; i <= d; ++i) 
        pw[i] = Pow(inv[i], c);
}   


