        else{
            ll now=1;
            for(int i=0; group*i<=num && i<=D; ++i){
                if(i==0 || C<=i){
                    memo[num][group]=(memo[num][group]+(now*solve(num-group*i, group-1))%mod)%mod;
                }
                now=(now*moddiv(COM(num-group*i, group, mod), i+1, mod))%mod;
            }
        }
        se[num][group]=1;
    }
    return memo[num][group];
}


int main() {
	cin >> N >> A >> B >> C >> D;
	COMinit(mod);
	cout << solve(N, B) << endl;
	return 0;
}

