    void clear() {        q = priority_queue<T>();        su = 0;    }
    void operator+=(T v) {        su += v;        q.push(v);    }
    T sum() { return su; }
    T top() { return q.top(); }
    void pop() {        su -= q.top();        q.pop();    }
    T poll() {        T ret = q.top();        su -= ret;        q.pop();        return ret;    }
    ll size() { return q.size(); }
};
