fps mul_sparse(fps& l,fps& r,int msize=-1){    vi inds;    rep(i, r.size()){        if(r[i]){            inds.push_back(i);        }    }    assert(sz(inds));    int n = l.size()+inds.back();    if(msize==-1){        msize = n-1;    }    fps ret(msize+1);    rep(i, l.size()){        for(auto d : inds){            if(i+d> msize)break;            ret[i+d] += l[i] * r[d];        }    }    return ret;}
