fps div_sparse(fps l, fps &r, int msize = -1) {    vi inds;    rep(i, r.size()) { if (r[i]) { inds.push_back(i); }}    assert(sz(inds));    int n = l.size();    if (msize == -1) { msize = n - 1; }    msize = min(msize, n - 1);    fps ret(msize + 1);    rep(i, l.size()) {        if (l[i]) {            assert(i >= inds[0]);            mint dec_k = l[i] / r[inds[0]];            if (i - inds[0] > msize)break;            ret[i - inds[0]] += dec_k;            for (auto d : inds) {                if (i + d - inds[0] >= n)break;                l[i + d - inds[0]] -= dec_k * r[d];            }        }    }    return ret;}
