int64_t mod_pow(int64_t n,int64_t x){//nをx乗
    if(x%2==0){
        if(x==0){
            return 1;
        }else{
            int64_t z=mod_pow(n,x/2);
            return (z*z)%mod;
        }
    }else{
        if(x==1){
            return n;
        }else{
            int64_t z=mod_pow(n,(x-1)/2);
            return (z*((z*n)%mod))%mod;
        }
    }
}

