typedef long long int LL;

const LL mod = 1000000007;

std::vector<std::vector<LL>>comb;
void make_comb(LL size)
{
	comb.resize(size + 1);
	rep(i, comb.size())
	{
		comb[i].resize(size + 1);
		comb[i][0] = 1;
		comb[i][i] = 1;
	}
	for (LL k = 1; k < comb.size(); ++k) for (LL j = 1; j < k; ++j) comb[k][j] = comb[k - 1][j - 1] + comb[k - 1][j];
}

LL N, A, B, C, D;
std::vector<std::vector<LL>>memo;
LL dp(LL i, LL j)
{
	if (i == 0) return 1;
	if (j > B) return 0;
	if (memo[i][j] != -1) return memo[i][j];
	LL res = dp(i, j + 1), add = 1;
	for (LL k = C; k <= D; ++k)
	{
		if (j*k > i) break;
		add *= comb[i - j * (k - C)][j] % mod;
		add %= mod;
		res += (((dp(i - j * k, j + 1)*add) % mod) / k) % mod;
		res %= mod;
	}
	return memo[i][j] = res;
}

