int bp(int x, int d){
	if(!d){
		return 1;
	}
	if(d&1){
		return mul(x, bp(x, d-1));
	}
	int r = bp(x, d/2);
	return mul(r, r);
}

int getC(int k, int n){
	if(k > n){
		return n;
	}
