mint pow(mint m,ll n){
    if(n==0)return 1;
    else if(n%2==0){
        mint x=pow(m,n/2);
        return x*x;
    }else{
        return m*pow(m,n-1);
    }
}
mint rev(mint m){
    return pow(m,MOD-2);
}

