constexpr int64_t pow(int64_t x, int64_t n, int64_t mod) {
    if (n == 0) {
        return 1;
    } else {
        int64_t ret = pow(x, n / 2, mod) % mod;

        return (ret * ret % mod) * ((n & 1) ? x : 1) % mod;
    }
}

