    for (int i = 2; i <= n; ++i) {
        inv[i] = inv[mod % i] * (mod - mod / i) % mod;
    }

    vector<int64_t> fact(n + 1), fact_inv(n + 1);
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    for (int i = 2; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % mod;
