    //=dp[i][j-1] + sigma(for k=C; k<=D&&kj<=i;k++) dp[i-kj][j-1]* (iCj*(i-j)Cj*...*(i-(k-1)j)Cj)/k!
    //k=0 or C<=k<=D
    LL dp[N+1][B+1];
    fill(dp[0],dp[N+1],0);
    REP(i,B+1)dp[0][i]=1;
    Culc culc(N+1,inf);

    REP(i,N+1){
        for(int j=A;j<=B;j++){
            LL sigma =0;
            LL comb=1;
            LL cnt=0;
            for(int k=C;k<=D&&k*j<=i;k++){
                cnt++;
                comb = (comb*culc.combination(i-j*(k-C),j))%inf;
                sigma += (((dp[i-k*j][j-1]*comb)%inf)*culc.inverse(culc.factorial[cnt],inf))%inf;
                sigma %=inf;
