int main() {
	init();
	cin >> n >> a >> b >> c >> d;
	dp[0] = 1;
	for (int i = a; i <= b; ++i) {
		for (int j = 0; j <= n; ++j)
			dp2[j] = dp[j];
		ll bf = 1;
		ll b1 = bfc[i];
		for (int k = 1; k < c; ++k)
			bf = (bf * b1) % MOD;
		for (int k = c; k <= d; ++k) {
			bf = (bf * b1) % MOD;
			ll bk = (bf * bfc[k]) % MOD;
			int cnt = k * i;
			if (cnt > n)
				break;
			for (int j = 0; j + cnt <= n; ++j)
				dp2[j + cnt] = (dp2[j + cnt] + dp[j] * cnk(n - j, cnt) % MOD * fc[cnt] % MOD * bk) % MOD;
		}
		for (int j = 0; j <= n; ++j)
			dp[j] = dp2[j];
	}
	cout << dp[n] << "\n";
	return 0;
}

