ll solve(int s,int t){
    if(dp[s][t]!=-1)return dp[s][t];
    ll ret=0;
    ret+=solve(s,t+1);
    for(int i=c;i<=d;i++){
        if(s<t*i)break;           
        ret+=COM(s,t*i)*fac[t*i]%MOD*modinv(modpow(fac[t],i,MOD),MOD)%MOD*modinv(fac[i],MOD)%MOD*solve(s-t*i,t+1)%MOD;
        ret%=MOD;
    }
    dp[s][t]=ret;
    return ret;
}
