ll mul(ll _a, ll _b) {
  if (_b == 0) return 1LL;
  if (_b == 1) return _a;
  ll ans = mul(_a, _b/2);
  ans *= ans;
  ans %= MOD;
  if (_b&1) ans *= _a;
  return ans % MOD;
}

ll my_div(ll _a, ll _b) {
  return (_a * mul(_b, MOD-2)) % MOD;
}

ll C(ll _n, ll _k) {
  if (_n == _k) return 1;
  return my_div(K[_n], (K[_k] * K[_n-_k]) % MOD);
}

ll get(ll groups, ll mem, ll from) {
  ll ans = 1;
//cout << groups << " " << mem << " " << from << ": ";

  REP(i,groups) {
    ans *= C(from, mem);
    ans %= MOD;
    from -= mem;
  }

//cout << ans << endl;
  return my_div(ans, K[groups]);
}

