    K[i] = K[i-1]*i;
    K[i] %= MOD;
  }

  for (ll i = 1; i <= b; i++) {
    if (i < a) {
      dp[i][0] += dp[i-1][0];
      continue;
    }
    REP(j,n+1) {
      dp[i][j] += dp[i-1][j];
      ll k = c;
      while (k <= d && j + k * i <= n) {
          //cout << k << " " << i << " " << n-j << " " << get(k,i,n-j) << endl;
        dp[i][j+k*i] += dp[i-1][j] * get(k, i, n-j);
        dp[i][j+k*i] %= MOD;
        k++;
      }
    }
//    debug();
  }
  cout << dp[b][n] << endl;
  return 0;
}

