using namespace std;
using I = long long;
const I M = 1e9+7;
vector<I> factorial = {1};
struct ExtendedGCD {I x, y, gcd;};
ExtendedGCD extended_gcd(I m, I n, I x = 1, I xx = 0, I y = 0, I yy = 1) {
  if(!n) return {x, y, m};
  auto nxx = x - m / n * xx;
  auto nyy = y - m / n * yy;
  return extended_gcd(n, m % n, xx, (nxx + M) % M, yy, (nyy + M) % M);
}
I inverse(I n) {
  return extended_gcd(M, n).y;
}
I memo[1001][1001];
I combination(I n, I r) {
  if(memo[n][r]) return memo[n][r];
  return memo[n][r] = (r % n == 0ll ? 1ll : (combination(n - 1, r - 1) + combination(n - 1, r)) % M);
}
int main() {
  I N, A, B, C, D;
  cin >> N >> A >> B >> C >> D;
  while(factorial.size() <= N) factorial.emplace_back(factorial.back() * factorial.size() % M);
  vector<I> dp(N+1);
  dp[0] = 1;
  for(auto i=A; i<=B; ++i) {
    auto dup = dp;
    auto c = 1ll;
    for(auto k=1ll; k<=(C-1); ++k) c = c * combination(i*k, i) % M;
    for(auto j=0ll; j<N; ++j) if(dup[j]) {
      auto d = c;
      for(auto k=C; k<=D && j+i*k<=N; ++k) {
        d = d * combination(i*k, i) % M;
        auto e = d * combination(N-j, i*k) % M;
        e = e * inverse(factorial[k]) % M;
        dp[j+i*k] += dup[j] * e % M;
        dp[j+i*k] %= M;
      }
    }
  }
  cout << dp[N] << endl;
}

