        p*=COM.C(N-j-(i+1)*(k-1),i+1);
        p%=mod;
        if(k>=C){
          dp[i+1][j+(i+1)*k]+=dp[i][j]*p%mod*COM.minvfact(k)%mod;
          dp[i+1][j+(i+1)*k]%=mod;
        }
      }
    }
  }
  cout<<dp[B][N]%mod<<endl;
}

