int pow_mod(int n, int m){
    int ans = 1;

    while(m > 0){
        if(m & 1) ans = (ans * n) % MOD;
        n = (n * n) % MOD;
        m >>= 1;
    }

    return ans;
}


int combi(int n, int r){
    return ((kai[n] * pow_mod(kai[r], MOD-2) % MOD) * pow_mod(kai[n-r], MOD-2)) % MOD;
}

