    int tmp = 1;
    int tt = j;
    int tt2 = 1;
    int cnt = 1;
    for(int num = c;num <= d;num++){
        tt -= i;
        tt2 = (tt2 * cnt) % MOD;
        cnt++;
        if(tt < 0) return memo[i][j] = ans;
        tmp = (tmp * combi(tt+i, i)) % MOD;
        ans = (ans + (dp(i+1, j-num*i) * (tmp*pow_mod(tt2, MOD-2) % MOD)) % MOD) % MOD;
    }

    return memo[i][j] = ans;
}

