        inv[i] = Power(fac[i], P - 2);
    }
    for (int v = 1; v <= 1000; ++v) {
        g[v][0] = 1;
        for (int i = 1; i <= 1000; ++i) g[v][i] = (LL) g[v][i - 1] * inv[v] % P;
    }

    dp[a - 1][0] = 1;
