int binpow (int a, int b)
{
    if (b == 0)
        return 1;
    if (b & 1)
        return a * binpow(a, b - 1) % mod;

    int x = binpow(a, b >> 1);

    return x * x % mod;
}

int CNK(int n, int k)
{
    return fc[n] * Fc[k] % mod * Fc[n - k] % mod;
}
int Cnk (int n, int k, int l)
{
    int ans = 1, cnt = 0, i = n;

    while (cnt < l && i >= k)
    {
        ans *= CNK( i, k );
        ans %= mod;
        i -= k;
        cnt++;
    }
    if (cnt < l)
        return 0;

    return ans * Fc[l] % mod;
}

main ()
{
    cin >> n >> a >> b >> c >> d;

    fc[0] = 1;
    Fc[0] = 1;

    for (int i = 1; i <= n; i++)
        fc[i] = i * fc[i - 1] % mod,
        Fc[i] = binpow( fc[i], mod - 2 );

    dp[0] = 1;
    old[0] = 1;

    for (int i = a; i <= b; i++)
    {
        for (int j = c; j <= d; j++)
        {
            for (int l = n; l >= 0; l--)
            {
                if (l + i * j <= n)
                {
                    dp[l + i * j] += old[l] * Cnk( n - l, i,  j );
                    dp[l + i * j] %= mod;
                }
            }
        }
        for (int l = n; l >= 1; l--)
            old[l] = dp[l];
    }
    cout << dp[n] << endl;
}

