inline ll Pow ( ll bs, int t )
{
	ll rt = 1;
	for ( ; t; t >>= 1, bs = bs * bs % Mod )
		if ( t & 1 )
			rt = rt * bs % Mod;
	return rt;
}

ll c[MAXN][MAXN], dp[MAXN][MAXN];
ll Get ( int x, int y )
{
	ll rt = 1;
	for ( int i = x; i; i -= y )
		rt = rt * c[i - 1][y - 1] % Mod;
	return rt;
}

