      dp[i][j] = dp[i-1][j];
      for(int k=C;k<=min(D,j/i);k++){
        ll c = (((((comb.Comb(N-j+i*k,i*k)*comb.fact[i*k])%MOD)*mod_pow(comb.finv[i],k))%MOD)*comb.finv[k])%MOD;
        dp[i][j] = (dp[i][j]+(c*dp[i-1][j-i*k])%MOD)%MOD;
      }
