int binpow (int a, int b)
{
    if (b == 0)
        return 1;
    if (b & 1)
        return a * binpow(a, b - 1) % mod;

    int x = binpow(a, b >> 1);

    return x * x % mod;
}

int CNK(int n, int k)
{
    int l = (n - k), res = 1;

    for (int i = n; i > max(l, k); i--)
        res *= i,
        res %= mod;

    return res * Fc[ min(l, k) ] % mod;
}
int Cnk (int n, int k, int l)
{
    int ans = 1, cnt = 0, i = n;

    while (cnt < l && i >= k)
    {
        ans *= CNK( i, k );
        ans %= mod;
        i -= k;
        cnt++;
    }
    if (cnt < l)
        return 0;

    return ans * Fc[l] % mod;
}

main ()
