bool next_int_partition_rlex(vector<int>& part) {
    int i;
    for (i = len(part)-1; i >= 0; i--)
        if (part[i] != 1)
            break;
    if (-1 == i)
        return false;
    int distribute = len(part) - i;
    part.resize(i+1);
    part[i]--;
    while (distribute > 0) {
        int b = min(distribute, part[i]);
        distribute -= b;
        part.append(b);
    }
    return true;
}
