LL expmod(LL a, LL b) {
    if (0 == b) return 1LL;
    LL rr = expmod(a, b >> 1);
    rr = (rr * rr) % MOD;
    if (b & 1)
        return (rr * a) % MOD;
    return rr;
}

const int MAXCOMB = 1007;
LL factorial[MAXCOMB];
LL inverse[MAXCOMB];


LL choose(int n, int k) {
    LL rr = (factorial[n] * inverse[n-k]) % MOD;
    return (rr * inverse[k]) % MOD;
}


