        ii (len(p)) {
            if (!(A <= p[i] && p[i] <= B)) {
                suitable = false;
                break;
            }
            ++counts[p[i]];
        }
        fe (it, counts) {
            int c = it->yy;
            if (!(C <= c && c <= D)) {
                suitable = false;
                break;
            }
        }
        if (!suitable)
            continue;

        LL here = 1;
        int remaining = N;
        fe (it, counts) {
            int size = it->xx;
