ll pwr(ll x,ll y){
    ll pw[32]={},w=1;
    pw[0]=x;
    fr(i,31) pw[i+1]=mlt(pw[i],pw[i]);
    fr(i,32){
        w=mlt(w,1+(y%2)*(pw[i]-1));
        y/=2;
    }
    return w;
}

ll inv(ll x){
    return pwr(x,MOD-2);
}

ll fc[200010]={1};
