    long long combination(long long n, long long k) {
        return factorial[n] * (inverse(factorial[k] * factorial[n - k] % p, p)) % p;
    }

};

int main(){

    int N,A,B,C,D;cin>>N>>A>>B>>C>>D;
    LL inf = 1e9+7;

    //dp[i][j]:i人をj人以下のグループで分けるときの組み合わせ
    //dp[i][j] = dp[i][j-1] + iCj * dp[i-j][j-1] + iCj*(i-j)Cj/2 * dp[i-2*j][j-1] + ...
    //=dp[i][j-1] + sigma(for k=C; k<=D&&kj<=i;k++) dp[i-kj][j-1]* (iCj*(i-j)Cj*...*(i-(k-1)j)Cj)/k!
    //k=0 or C<=k<=D
    LL dp[N+1][B+1];
    fill(dp[0],dp[N+1],0);
    REP(i,B+1)dp[0][i]=1;
    Culc culc(N+1,inf);

    REP(i,N+1){
        for(int j=A;j<=B;j++){
            LL sigma =0;
            LL comb=1;
            LL cnt=0;
            for(int k=C;k<=D&&k*j<=i;k++){
                cnt++;
                comb *= culc.combination(i-j*(k-C),j);
                comb %=inf;
                sigma += ((dp[i-k*j][j-1]*comb)%inf)*culc.inverse(culc.factorial[cnt],inf)%inf;
                sigma %=inf;
            }
            dp[i][j]=(dp[i][j-1]+sigma)%inf;
        }
    }

    cout<<dp[N][B]<<endl;


    return 0;
}

