    int K = B - A + 1;

    int fact[N+1];
    fact[0] = 1;
    for (int i = 1; i <= N; i++) {
        fact[i] = i * fact[i-1];
        fact[i] %= MOD;
    }

    Combination comb = Combination(N, MOD);

    int dp[K+1][N+1];
    fill(dp[0], dp[K+1], 0);
    dp[0][0] = 1;

    for (int i = 0; i < K; i++) {
        int human_n = i + A;

        for (int j = 0; j <= N; j++) {
            dp[i+1][j] = dp[i][j];
            for (int group_num = C; group_num <= D; group_num++) {
                if (j - human_n * group_num < 0) break;
                int up = (fact[j] * dp[i][j - human_n * group_num]) % MOD;
                int down = ((powmod(fact[human_n], group_num, MOD) * fact[group_num]) * fact[j - human_n * group_num]) % MOD;
                dp[i+1][j] += (up * powmod(down, MOD - 2, MOD)) % MOD;
                dp[i+1][j] %= MOD;
            }
        }
    }

    cout << dp[K][N] << endl;

    return 0;
}

