    precalc(N);

    vector<vector<int>> dp(B + 2, vector<int>(N + 1, 0));
    dp[A][0] = 1;
    for (int k = A; k <= B; k++) {
        for (int n = 0; n <= N; n++) {
            add(dp[k + 1][n], dp[k][n]);

            int v = 1;
            for (int i = 1; n + i * k <= N && i <= D; i++) {
                v *= nCr(N - n - k * (i - 1), k);
                v %= mod;
                if (i < C) continue;
                add(dp[k + 1][n + i * k], (((dp[k][n] * v) % mod) * rev[i]) % mod);
            }
        }
    }
    cout << dp[B + 1][N] << endl;
    return 0;
}

