const int mod = 1000000000 + 7;



// inverse mod of i%prime = bigmod(i,prime-2)
long long bigmod(long long a, long long n) {
    n %= mod - 1;
    long long res = 1;
    while (n) {
        if (n & 1ll) {
            res = res * a;
            if (res >= mod) {
                res %= mod;
            }
        }
        a = a * a;
        if (a >= mod) {
            a %= mod;
        }
        n >>= 1;
    }
    return res;
}

ll ncr[1001][1001];
