void computeNCR()
{
    fct[0] = fct[1] = 1;
    for(int i = 0; i <= 1000; i++)
    {
        ncr[i][1] = i;
    }
    for(int n = 2; n <= 1000; n++)
    {
        fct[n] = (fct[n - 1] * n) % mod;
        for(int r = 2; r <= n; r++)
        {
            ncr[n][r] = ( ncr[n - 1][r - 1] + ncr[n - 1][r] ) % mod;
        }
    }
}

ll computeNSK(int N, int S, int K)
{
    ll ans = 1;
    for(int i = 0; i < K; i++)
    {
        ans = (ans * ncr[N - i * S][S]) % mod;
    }
    ans = (ans * bigmod(fct[K], mod - 2) ) % mod;

    return ans;
}



