    for(int i = A; i <= B; i++) // group size
    {
        for(int j = N - C * i; j >= 1; j--)
        {
            if(bi[j])
            {
                for(int k = C; k <= D; k++)
                {
                    if(j + i * k > N)
                    {
                        break;
                    }
                    bi[j + i * k] = true;
                    dp[j + i * k] = (dp[j + i * k] + (dp[j] * computeNSK(N - j, i, k)) %mod ) % mod;
                }
            }
        }
        for(int k = C; k <= D; k++)
        {
            if(i * k > N)
            {
                break;
            }
            bi[i * k] = true;
            dp[i * k] = (dp[i * k] + computeNSK(N, i, k)) % mod;
        }
    }

