Num calc(int i,int j){
	if(dp[i][j]>=0)return dp[i][j];
	if(i==0)return dp[i][j] = 1;
	if(j>B)return dp[i][j] = 0;
	Num ans = 0;
	for(int F = C;F<=D;F++){
		int i2 = i-F*j;
		if(i2<0)break;
		ans+=calc(i2,j+1)*binom(i,i2)*fact(F*j)/(pow(fact(j),F)*fact(F));
	}
	ans+=calc(i,j+1);
	return dp[i][j] = ans;
}

