    for(int i = 0; i < MAX_N;i++)for(int j = 0; j < MAX_N;j++) memo[i][j] = -1;
}
ll dfs(ll n,ll a){
    ll &res = memo[n][a];
    if(res != -1) return res;
    if(n == 0) return res = 1;
    if(n < a || a > B) return res = 0;

    res = 0;
    (res += dfs(n,a+1))%=MOD;
    ll F = 1;
    for(ll x = 1; x <= D; x++){
        if(a > n) break;
        (F *= nCr(n,a))%=MOD; (F *= Inv[x])%=MOD; n-=a;
        if(x >= C){ (res += F*dfs(n,a+1))%=MOD; }
    }
    return res;
}
ll solve(){
    ll res = 0;
    cin >> N >> A >> B >> C >> D;
    res = dfs(N,A);
    return res;
}
