    srep (bgroup_count, c, d + 1LL) {
        if (n < b * bgroup_count) break;

        if (rpow < 0LL) rpow = mod_pow(perm[b], bgroup_count, mod);
        else {
            rpow = rpow * perm[b];
            rpow %= mod;
        }
        ll rpow_inv = mod_inv(rpow, mod);

        ll select = perm[n] * rpow_inv;
        select %= mod;
        select *= perm_mod_inv(n - b * bgroup_count);
        select %= mod;

