}

//二項係数の計算(mod MOD上)
inline mint COM(int n, int k){
  if(n<k) return 0;
  if(k<0) return 0;
  return fact[n]/(fact[k]*fact[n-k]);
}

inline mint PER(int n, int k){
  if(n<k) return 0;
  if(k<0) return 0;
  return fact[n]*finv[n-k];
}

