			i64 temp = C(j, i * k) * fac[i * k] % mod * inv(pw(fac[i], k)) % mod * inv(fac[k]) % mod;
			F[i][j] = (F[i][j] + F[i - 1][j - i * k] * temp % mod) % mod;                  
		}
	}

	cout << F[b][n] << endl;
#ifdef RICARDO
	cerr << "\nTime elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << " s.\n";
#endif
}

