const ll MOD = 1000000007;
ll dp(int i, int j)
{
	if (i < 0)return 0;
	if (j == b + 1)
	{
		if (i != 0)return 0;
		return 1;
	}
	if (memo[i][j] >= 0)return memo[i][j];
	ll ret = dp(i, j + 1);
	for (int a = c; a <= d; ++a)
	{
		if (i < 0 || i - j * a < 0 || j < 0)continue;
		mint mult = infact[i] * ~infact[i - j * a];
		mult *= ~m_pow<1000000007>((long long)infact[j], a);
		mult *= ~infact[a];
		ret += dp(i - j * a, j + 1) * (ll)mult;
		ret %= MOD;
	}
	return memo[i][j] = ret;
}

