		binom[i][0] = 1;
		binom[i][i] = 1;
	}
	for (int i = 2; i <= N; i++){
		for (int j = 1; j < i; j++){
			binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % MOD;
		}
	}
	vector<long long> dp(N + 1, 0);
	dp[0] = 1;
	for (int i = A; i <= B; i++){
		for (int j = N; j >= 0; j--){
			long long tmp = dp[j];
			for (int k = 0; k <= D; k++){
				if (j + i * k > N){
					break;
				}
				if (k >= C){
					dp[j + i * k] += tmp * modfactinv(k) % MOD;
					dp[j + i * k] %= MOD;
				}
				tmp *= binom[N - j - i * k][i];
				tmp %= MOD;
			}
		}
	}
	cout << dp[N] << endl;
}

