const LL mod = 1000000007;

std::vector<std::vector<LL>>comb;
void make_comb(LL size)
{
	comb.resize(size + 1);
	rep(i, comb.size())
	{
		comb[i].resize(size + 1);
		comb[i][0] = 1;
		comb[i][i] = 1;
	}
	for (LL k = 1; k < comb.size(); ++k) for (LL j = 1; j < k; ++j) comb[k][j] = (comb[k - 1][j - 1] + comb[k - 1][j]) % mod;
}

LL N, A, B, C, D;
std::vector<std::vector<LL>>memo;
std::vector<LL>fact;
LL dp(LL i, LL j)
{
	if (i == N) return 1;
	if (i + j * C > N) return 0;
	if (j > B) return 0;
	if (memo[i][j] != -1) return memo[i][j];
	LL res = dp(i, j + 1), t = 1;
	for (LL k = 0; k < C - 1; ++k) t = (t*comb[N - i - j * k][j]) % mod;
	for (LL k = C; k <= D; ++k)
	{
		if (i + j * k > N) break;
		t = (t*comb[N - i - j * (k - 1)][j]) % mod;
		res += dp(i + j * k, j + 1)*t / fact[k];
		res %= mod;
	}
	return memo[i][j] = res;
}

