        for(int g = A; g <= B; ++g) {
            for(int i = N - g; i >= 0; --i) if(dp[i].toi()){
                mint x = 1;
                for(int j = 1; i + j*g <= N && j <= D; ++j) {
                    // N-i-(j-1)*g 人から g人選ぶ
