				int temp = N-j;
				int t = 1;
				for(int k=1;k<=D;k++){
					if(temp<i)break;
					t = mod(t * c.combination(temp,i));
					int x = mod(t * c.kaijou_[k]);
					if(k>=C)dp[i+1][j+k*i] = mod(dp[i+1][j+k*i] + mod(x*dp[i][j]));
					temp-=i;
				}
			}
		}
	}

