ll pow2(ll a, ll b) {
  ll res = 1;
  while(b) {
    if(b & 1) res = res * a % mod;
    a = a * a % mod;
    b >>= 1;
  }

  return res;
}

ll get_inv(ll x) {
  return pow2(x, mod-2);
}

ll getP (int n, int m) {
  return fac[n] * get_inv(fac[n-m]) % mod;
}

