const int n_max = 1004;

llong fac[n_max];  /// fac[n] = n!
llong finv[n_max]; /// (fac[n] * finv[n]) % MOD = 1
llong inv[n_max];  /// (n * inv[n]) % MOD = 1

void init() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  FOR (i, 2, n_max) {
    fac[i] = fac[i-1]*i % MOD;
    inv[i] = MOD - inv[MOD%i]*(MOD/i) % MOD;
    finv[i] = finv[i-1]*inv[i] % MOD;
  }
}

llong nCk (int n, int k) {
  if (n < k || k < 0 || n < 0) return 0;
  return fac[n]*finv[k]%MOD*finv[n-k]%MOD;
}


llong beki(llong a,llong x){
    llong res = 1;
    llong tmp = a;
    while(x > 0){
        if(x & 1) res *= tmp; res %= MOD;
        tmp *= tmp;
        tmp %= MOD;
        x >>=1;
    }
    return res;
}

signed main(){
    int n,a,b,c,d;
    cin >> n >> a >>b >> c >> d;
    init();

    int dp[n_max][n_max];
    REP(i,n_max) REP(j,n_max) dp[i][j] = 0;
    int gyakugen[n_max];
    FOR(i,1,n_max) gyakugen[i] = beki(i,MOD-2);

    dp[b][n] = 1;
    REPR(i,b){
        if(i == a-1) break;

        REP(j,n + 1){
            dp[i - 1][j] += dp[i][j];
            dp[i-1][j] %= MOD;
            int tmp = 1;
            FOR(k,1,d+1){
                if(k * i > j) break;
                tmp *= nCk(i * k,i);
                tmp %= MOD;
                tmp *= gyakugen[k];
                tmp %= MOD;
                if(k < c) continue; 
                int hoge = dp[i][j] * tmp;
                hoge %= MOD;
                hoge *= nCk(j,k * i);
                hoge %= MOD;
                dp[i-1][j-k * i] += hoge;
                dp[i-1][j-k * i] %= MOD;
            }
        }
    }
    cout << dp[a-1][0] << endl;


}

