    //G(i,a)はi人のグル×aの作り方
    function<ll(ll,ll)> G = [&](ll i,ll a){
        if(a<=1)return 1LL;
        else if(g[i][a]!=-1)return g[i][a];
        else return g[i][a]=G(i,a-1)%MOD*comb(i*a,i)%MOD*modinv(a,MOD)%MOD;
    };
    vector<vector<ll>> dp(B+1, vector<ll>(N+1, -1));
