    for(int i=A;i<=B;i++){
        for(int j=1;j<=N;j++){
            for(int k=0;k<=D;k++){
                if(j-i*k<0) break;
                if(0<k && k<C) continue;
                ll v = (mult(inv[i],k)*inv[k])%inf;
                ll r = (permutation(N-j+i*k,i*k)*v)%inf;
                (dp[i][j] += (dp[i-1][j-i*k]*r)%inf)%=inf;
            }
        }
    }
    cout << dp[B][N] << endl;
}

