      for(int i = 0; i + x*y <= n; i++) {
        if(dp[i] == 0) continue;
        ll scale = facs[i+x*y];
        scale *= ifacs[x*y];
        scale %= MOD;
        scale *= ifacs[i];
        scale %= MOD;
        scale *= solve(x, y);
        scale %= MOD;
        ndp[i+x*y] += dp[i] * scale;
        ndp[i+x*y] %= MOD;
      }
    }
    for(int i = 0; i <= n; i++) {
      dp[i] += ndp[i];
      dp[i] %= MOD;
    }
  }
  cout << dp[n] << "\n";
}

