int N,A,B,C,D;
ll mo=1000000007;
ll ret;

const int NUM_=400001;
static ll fact[NUM_+1],factr[NUM_+1],inv[NUM_+1];

int okok[1010][1010];
ll memo[1010][1010];

ll modpow(ll a, ll n = mo-2) {
	ll r=1;
	while(n) r=r*((n%2)?a:1)%mo,a=a*a%mo,n>>=1;
	return r;
}

ll combi(ll N_, ll C_) {
	if (fact[0]==0) {
		inv[1]=fact[0]=factr[0]=1;
		for (int i=2;i<=NUM_;++i) inv[i] = inv[mo % i] * (mo - mo / i) % mo;
		for (int i=1;i<=NUM_;++i) fact[i]=fact[i-1]*i%mo, factr[i]=factr[i-1]*inv[i]%mo;
	}
	if(C_<0 || C_>N_) return 0;
	return factr[C_]*fact[N_]%mo*factr[N_-C_]%mo;
}

ll dfs(int a,int l) {
	int i;
	if(okok[a][l]==0) return 0;
	ll& ret=memo[a][l];
	if(memo[a][l]>=0) return memo[a][l]=0;
	ret=0;
	if(l==0) {
		ret = 1;
	}
	else {
		memo[a][l]=0;
		if(a>B) return 0;
		ret += dfs(a+1,l);
		ll v=1;
		for(i=1;i<=D && a<=l;i++) {
			(v *= combi(l,a))%=mo;
			l-=a;
			(v *= inv[i])%=mo;

			if(i>=C && i<=D) {
				ret += v*dfs(a+1,l)%mo;
			}
		}
	}
	ret%=mo;
	return ret;

}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>A>>B>>C>>D;

	MINUS(memo);
	combi(1,1);

	okok[B+1][0]=1;
	for(i=B;i>=A;i--) {
		FOR(y,1001) if(okok[i+1][y]) {
			okok[i][y]=1;
			for(x=C;x<=D && y+x*i<=N;x++) okok[i][y+x*i]=1;
		}
	}
	cout<<dfs(A,N)<<endl;

}


