				if(k*i>j) break; // O(N^2*log(N)) due to harmonic series tight bound O(logN)
				ll val=dp[i-1][j-k*i]*C[n-j+k*i][k*i]%mod*fact[k*i]%mod;
				(val*=fpow(fpow(fact[i],k),mod-2))%=mod;
				(val*=fpow(fact[k],mod-2))%=mod;
				(dp[i][j]+=val)%=mod;
			}
		}
	cout<<dp[b][n]<<'\n';
}

