template<typename T>
T powm(T x, T p, T mod){
    T y=1;
    x=x%mod;
    while (0<p){
        if (p%2==1){
            y=(y*x)%mod;
        }
        x=(x*x)%mod;
        p/=2;
    }
    return y;
}
template<typename T>
T combim(T n, T r, T mod){
    static T memo[1010][1010];
    if (0<memo[n][r]) return memo[n][r]-1;

    T p = 1;
    for (T rr=1;rr<=r;rr++){
        p = (((p*(n-rr+1))%mod)*powm(rr,mod-2,mod))%mod;
        memo[n][rr] = p+1;
    }
    memo[n][r] = p+1;
    return p;
}

