    for (long long n = i * j; n >= i; n -= i) {
        ret = (ret * combi_num.calc(n, i)) % MOD;
    }
    ret = (ret * combi_num.den[j]) % MOD;
    return ret;
}

long long calc_sub_pattern_num2(const long long i, const long long j) {
    long long ret = combi_num.fac[i*j];
    for (int k = 1; k <= j; k++) {
