	function<mint(int, int)> dfs = [&](int i, int m) {
		if(i == b + 1) {
			if(m)
				return (mint)0;
			else
				return (mint)1;
		}
		if(chk[i][m]) return dp[i][m];
		mint res = 0;
		for(int j = 0; j < d + 1;j++) {
			if(j == 1) j = c;
			if(i * j > m) break;
			mint k = dfs(i + 1, m - i * j);
			if(j) {
				k *= commod(m, i * j);
				k *= fac[i * j];
				k /= fac[j];
				k /= modpow(fac[i], j, mod);
			}
			res += k;
		}
		chk[i][m] = 1;
		// debug(i, m, res);
		return dp[i][m] = res;
	};

