class Combination {

public:
    vector<ll> fact;

    Combination(int max_n) {
        //1 ~ n!までの階乗modを求める
        int n = max_n;
        vector<ll> fact(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        this->fact = fact;
    }

    template<typename T>
    //templateをつかってみｔか
    ll pow(T x, int y) {
        if (y == 0) return 1;
        if (y == 1) return x;
        if (y == 2) return (x * x) % MOD;
//        if (y % 2 == 1) return pow(x, y / 2) * pow(x, y / 2) % MOD;
        if (y % 2 == 1) return pow(pow(x, y / 2), 2) * x % MOD;
//        return pow(x, y / 2) * pow(x, y / 2) % MOD;
        return pow(pow(x, y / 2), 2) % MOD;
    }

    ll nCk(int n, int k) {
//        return (fact[n] * pow(fact[n-k],MOD-2) * pow(fact[k],MOD-2)) % MOD;
        return (((fact[n] * pow(fact[n - k], MOD - 2)) % MOD) * pow(fact[k], MOD - 2)) % MOD;
    }

    ll nPk(int n, int k) {
        return (((fact[n] * pow(fact[n - k], MOD - 2)) % MOD)) % MOD;
    }

    ll extgcd(ll a, ll b, ll &x, ll &y) {
        ll d = a;
        if (b != 0) {
            d = extgcd(b, a % b, y, x);
            y -= (a / b) * x;
        } else {
            x = 1;
            y = 0;
        }
        return d;
    }

    ll mod_inverse(ll a, ll m) {
        ll x, y;
        extgcd(a, m, x, y);
        return (m + x % m) % m;
    }
};

Combination comb(1001);
ll npk[1001][1001] = {};
ll mi[1001] = {};
ll pmi[1001][1001] = {};
ll func(int n, int x, int k) {
    ll ret;
    if(npk[n][x*k] == -1){
        ret = npk[n][x*k] = comb.nPk(n, x * k);
    }else{
        ret = npk[n][x*k];
    }
    if(mi[x] == -1){
        mi[x] = comb.mod_inverse(comb.fact[x], MOD);
    }
    ret *= mi[x];
    ret %= MOD;
    if(pmi[k][x] == -1){
        pmi[k][x] = comb.pow(comb.mod_inverse(comb.fact[k], MOD), x);
    }
    ret *= pmi[k][x];
    ret %= MOD;
    return ret;
}

int A, B, C, D;
ll memo[1001][1001] = {};

ll dfs(int n, int k) {
    ll ret = 0;
    if (n == 0) return memo[n][k] = 1;
    if (k == 0) return memo[n][k] = 0;
    if (memo[n][k] != -1) return memo[n][k];
    ret += dfs(n, k - 1);
    ret %= MOD;
    if (k >= A && k <= B) {
        for (int x = C; x <= D; x++) {
            if (n - x * k >= 0) {
                ret += dfs(n - x * k, k - 1) * func(n, x, k) % MOD;
                ret %= MOD;
            } else break;
        }
    }
    return memo[n][k] = ret;

}

