            memo[i][j] = -1;
            npk[i][j] = -1;
            pmi[i][j] = -1;
        }
        mi[i] = -1;
    }

    cin >> N >> A >> B >> C >> D;
    cout << dfs(N, N) << endl;
    return 0;
}

