int binpow (int a, int b)
{
    if (b == 0)
        return 1;
    if (b & 1)
        return a * binpow(a, b - 1) % mod;

    int x = binpow(a, b >> 1);

    return x * x % mod;
}
int Cnk (int n, int k, int l)
{
    if (n < k * l)
        return 0;

    return fc[n] * Fc[k] % mod * binpow(l, mod - 2) % mod * Fc[n - k * l] % mod * Fc[l] % mod;
}
