void exgcd(LL a, LL b, LL &g, LL &x, LL &y) {
    if (!b) x = 1, y = 0, g = a;
    else {
        exgcd(b, a % b, g, y, x);
        y -= x * (a / b);
    }
}

// ax = 1 (mod m), gcd(a, m) = 1
LL mod_inv(LL a, LL m) {
    LL d, x, y;
    exgcd(a, m, d, x, y);
    return d == 1 ? (x % m + m) % m : -1;
}

