            REPF(k,C,D+1) {
                if(j<i*k) break;
                dp[i][j]+=dp[i-1][j-i*k]*fact[N-(j-i*k)]%MOD*fact_inv[N-j]%MOD*fact_inv[k]%MOD*bin_pow_mod(bin_pow_mod(fact[i],k),MOD-2)%MOD;
                dp[i][j]%=MOD;
            }
        }
    }
    cout<<dp[B][N]<<endl;
    return 0;
}

