typedef long long ll;
class FactorialMOD {
  static const int MAX_N = 1010;
  typedef long long MODINT;
public:
  MODINT facTable[MAX_N+10];
  MODINT invTable[MAX_N+10];

  void generate(int n, MODINT p) { // p must be prime number. O(n) O(log2P)
    memset(facTable, 0, sizeof(facTable));
    memset(invTable, 0, sizeof(invTable));
    facTable[0]=1;
    for(int i=1;i<=n;++i) {
      facTable[i] = (facTable[i-1] * i) % p;
    }

    MODINT power = facTable[n];
    MODINT res = 1;
    MODINT index = p-2;

    for(int i=0;(index>>i) != 0;++i) {
      if( ((index >> i) & 1) == 1) {
        res = (res * power) % p;
      }
      power = (power*power) %p;
    }

    invTable[n] = res;
    for(int i=n;i>=1;--i) {
      invTable[i-1] = (invTable[i] * i) % p;
      if((invTable[i] * facTable[i]) %p != 1) printf("Error");
    }

  }
  MODINT factorial(int n) {
    return facTable[n];
  }
  MODINT inverseFactorial(int n) {
    if (n==0) return 1;
    return invTable[n];
  }
  ll combination(int n,int r,ll p) {
    return ((factorial(n) * inverseFactorial(n-r) % p) * inverseFactorial(r) ) % p;
  }
};
int N,A,B,C,D;
ll MOD=1ll * 1000 * 1000*1000+7;
vector<ll> dptable[1010][1010];//rest/groupsize
FactorialMOD factorialMOD;
ll solveDp(int rest, int prev_groupsize,int num_groups) {
  if (dptable[rest][prev_groupsize][num_groups]!=-1) {
    return dptable[rest][prev_groupsize][num_groups];
  }
  if (rest==0) {
    if (num_groups==0|| (num_groups>=C&&num_groups<=D)) {
      return 1ll;
    } else {
      return 0ll;
    }
  }
  ll answer = 0;
  for(int nextsize=max(prev_groupsize,A);nextsize<=min(rest,B);++nextsize) {
    if (nextsize > prev_groupsize) {
      if (num_groups==0||(num_groups>=C && num_groups<=D)) {

      } else {
        continue;
      }
    }
    ll subanswer = factorialMOD.combination(rest,nextsize,MOD);
    int gsize=1;
    if (nextsize==prev_groupsize) {
      gsize=num_groups+1;
    }
    subanswer *= solveDp(rest-nextsize, nextsize,gsize);
    MODDING(subanswer, MOD);
    if (nextsize>prev_groupsize) {
      subanswer *= factorialMOD.inverseFactorial(num_groups);
      MODDING(subanswer, MOD);
    }
    answer += subanswer;
    MODDING(answer, MOD);
  }
  return dptable[rest][prev_groupsize][num_groups]=answer;
}
