ll cache[1010][1010];
// a人以下のグループのみでn人を使う場合の数を求める
ll dfs(ll n, ll a) {
    if (cache[n][a] != -1) return cache[n][a];
    if (n == 0) return 1; // ?
    if (a < A) return 0;
    //printf("n, a = %d, %d\n", n, a);

    ll ans = 0;
    if (a >= A + 1) {
        ans += dfs(n, a - 1);
        ans %= MOD;
    }

    ll val = 1;
    ll remain = n;
    FOR(i, 1, D + 1) {
        ll x = i * a;
        val *= Cb[remain][a];
        val %= MOD;
        val = modDivision(val, i);
        remain -= a;

        if (x > n) break;
        if (i < C) continue;

        ans += val * dfs(n - x, a - 1) % MOD;
        ans %= MOD;
    }

    cache[n][a] = ans;
    //printf("cache[%d][%d] = %d\n", n, a, ans);
    assert(ans >= 0LL);
    return ans;
}

int main(void)
{
    cin.sync_with_stdio(false);
    cin >> N >> A >> B >> C >> D;

    memset(cache, -1, sizeof(cache));

    // テーブルを前計算
    Cb[0][0] = 1;
    FOR(i, 1, N + 1) {
        Cb[i][0] = 1;
        FOR(j, 1, N + 1) {
            Cb[i][j] = (Cb[i - 1][j - 1] + Cb[i - 1][j]) % MOD;
        }
    }
    FOR(i, 1, N + 1) {
        MI[i] = modInverse(i);
    }

    ll ans = dfs(N, B);
    cout << ans << endl;

    return 0;
}

