int solve(int left, int p) {
  if(left == 0) return 1;
  if(a+p > b) return 0;
  if(~dp[left][p]) return dp[left][p];
  int res = solve(left, p+1);
  FORI(i, c, d) {
    if((a+p) * i > left) break;
    int tmp = solve(left - (a+p)*i, p+1);
    smul(tmp, C(left, (a+p)*i));
    smul(tmp, solve2((a+p)*i, a+p));
    sadd(res, tmp);
  }
  return dp[left][p] = res;
}

