ll pow_mod(ll a, ll b, ll m){
    ll ret = 1;
    while (b > 0) {
        if (b & 1) {
            ret = ret * a % m;
        }
        a = a * a % m;
        b >>= 1;
    }
    return ret;
}

ll inv_mod(ll a, ll m){
    return pow_mod(a, m - 2, m);
}

ll calc(ll n, ll a, ll c) {
    ll ret = f[n];
    ret *= inv_mod(f[n - a * c], mod);
    ret %= mod;
    ll p = pow_mod(f[a], c, mod);
    ret *= inv_mod(p, mod);
    ret %= mod;
    return ret;
}

