                    dp[i + 1][n - j * (A + i)] %= mod;
                }
                else break;
            }
        }

    }

    ll ans = 0;
    rep(i, B - A + 2) {
        ans += dp[i][0];
        ans %= mod;
    }
    output(ans);


    return 0;
}

