long long int pow_m1(long long int num){
	long long int pow_num = MOD - 2;
	long long int pow_cur = num;
	long long int ret = 1;
	while(pow_num > 0){
		if(pow_num % 2 == 1){
			ret *= pow_cur;
			ret %= MOD;
		}
		pow_cur *= pow_cur;
		pow_cur %= MOD;
		pow_num /= 2;
	}
	return ret;
}

