        fact[i] %= MOD;
        inv[i] = mypow(fact[i],MOD-2);
    }
    vector<vector<ll>> p(n+1,vector<ll>(n+1));
    for(ll i=1;i<=n;i++){
        p[i][1]=i;
        for(ll j=2;j<=i;j++){
            p[i][j] = p[i][j-1] * (i-j+1);
            p[i][j] %= MOD;
        }
