	for (int e=1;e<c;++e)mult = (((mult * C(left,A))%MOD) * I[e])%MOD;
	nl -= A*(c-1);

	for (int e=c;e<=d;++e){
		if (nl<A)break;
		mult = (((mult * C(nl,A))%MOD) * I[e])%MOD;
		nl -= A;
		// cout<<"Mult "<<left<<' '<<A<<' '<<mult<<'\n';
		ans = (ans + ask(nl, A+1)*mult) %MOD;
	}

	ans = (ans+ask(left,A+1))%MOD;
	// cout<<"Ask "<<left<<' '<<A<<' '<<ans<<'\n';
	return memo[left][A] = ans;
}

