long long int saiki( long long int N, long long int A, long long int B, long long int C, long long int D ) {
	long long int ret = 0;
	if( N == 0 ) {
		return 1;
	}
	if( N < A*C ) {
		return 0;
	}
	if( memo.count( make_pair( N, A ) ) != 0 ) {
		return memo[make_pair( N, A )];
	}
	for( long long int i = A; i <= B; i++ ) {
		for( long long int j = C; j <= D && j*i <= N; j++ ) {
			long long int memox = saiki( N - i*j, i + 1, B, C, D )*cb.cb( N, i*j, 1e9L + 7 );
			long long int xxx = 1;
			for( size_t k = 1; k <= j; k++ ) {
				xxx *= cb.cb( k*i, i, 1e9 + 7 );
				xxx %= (long long int)1e9 + 7;
				xxx *= cb.powmod( k, 1e9 + 5, 1e9 + 7 );
				xxx %= (long long int)1e9 + 7;

			}
			//cout << xxx << endl;
			memox *= xxx;
			ret += memox;
			ret %= (long long int)1e9L + 7;
		}
	}
	return memo[make_pair( N, A )] = ret;
}

