#include <bits/stdc++.h>

using namespace std;

long long MOD=1000000007, Dp[1001][1001], F[1001];

long long Power(long long a, long long k)
{
    long long t=1, R=1, S=a;
    while (k > 0)
    {
        if (k % (2*t) != 0)
        {
            k -= t;
            R *= S;
            R %= MOD;
        }
        S *= S;
        S %= MOD;
        t *= 2;
    }
    return R;
}

int main()
{
    long long N, A, B, C, D, S=0;
    cin >> N >> A >> B >> C >> D;
    for (int i = 0; i <= 1000; i++)
    {
        for (int y = 0; y <= 1000; y++)
        {
            Dp[i][y] = 0;
        }
    }
    Dp[A-1][0] = 1;
    F[1] = 1;
    F[0] = 1;
    for (int i = 2; i <= 1000; i++)
    {
        F[i] = F[i-1] * i;
        F[i] %= MOD;
    }
    for (int i = A; i <= B; i++)
    {
        for (int y = 0; y <= N; y++)
        {
            Dp[i][y] += Dp[i-1][y];
            Dp[i][y] %= MOD;
            for (int u = C; u <= D; u++)
            {
                if (u*i + y > N)
                {
                    break;
                }
                S = Dp[i-1][y];
                S *= F[N-y];
                S %= MOD;
                S *= Power(F[N-y-u*i], MOD-2);
                S %= MOD;
                S *= Power(F[i], MOD-u-1);
                S %= MOD;
                S *= Power(F[u], MOD-2);
                S %= MOD;
                Dp[i][y+u*i] += S;
                Dp[i][y+u*i] %= MOD;
            }
        }
    }
    cout << Dp[B][N];
    return 0;
}

