void solve() {
  memset(dp, 0, sizeof(dp));
  dp[0] = 1;
  for (int k = a; k <= b; ++k) {
    for (int x = n; x >= 0; --x) {
      int cur = dp[x];
      if (!cur) {
        continue;
      }
      for (int cnt = 0; cnt <= d; ++cnt) {
        if (!cur) {
          break;
        }
