LL partf(LL n,LL m) {
	if (dp[n][m] != -1)return dp[n][m];
	if (n == 0)return 1;
	if (n < m)return 0;
	if (m > q)return 0;
	LL ret = 0, cnt = 1;
	ret += partf(n, m + 1);
	for (int i = 1; i < h; i++) {
		if (n - m * i >=m) {
			cnt = (cnt*comb.C(n - m * (i-1), m)) % MOD;
		}
		else return dp[n][m] = 0;
	}
	for (int i = h; i <= w; i++) {
		cnt = (cnt*comb.C(n - m * (i-1), m)) % MOD;
		if (n - m * i >= 0) {
			ret += (((partf(n - i * m, m + 1)*cnt) % MOD)* comb.rfact[i]) % MOD;
			ret %= MOD;
		}
		else break;
	}
	return dp[n][m] = ret;
}
