		fac_inv[n] = (fac_inv[n+1]*(n+1))%MOD;

	for(LL count = 1; count <= N; count++)
		for(LL sz = 1; sz <= N; sz++)
			if(count*sz <= N)
			{
				LL x1 = (fac[sz*count]*fac_inv[count])%MOD;
				cost[count][sz] = (x1*mod_pow(fac_inv[sz],count))%MOD;
			}

	int n; cin >> n;
	cin >> A >> B >> C2 >> D;

	memset(memo,-1,sizeof memo);
	cout<<dp(n,A)<<endl;

	return 0;
}

