	if (calc2dp[a][b] >= 0) return calc2dp[a][b];
	ll res = 1;
	while (a > 0)
	{
		res *= comb[a-1][b-1];
		res %= MOD;
		a -= b;
	}
	return calc2dp[a][b] = res;
}

ll calc(int rem, int p, int group)
{
	ll res = comb[rem][p * group];
	res *= calc2(p * group, p);
	return res % MOD;
}

int solve(int p, int use)
{
	if (dp[p][use] >= 0) return dp[p][use];
	if (p == a - 1)
	{
		return use == 0;
