	ll res = 0;
	res += solve(p - 1, use);
	FOR(i, c, d + 1)
	{
		if (use < p * i) break;
		res += calc(use, p, i) * solve(p - 1, use - p * i) % MOD;
		res %= MOD;
	}
	return dp[p][use] = res;
}

