ll bigmod(ll a, ll b) {
  ll res = 1LL;
  while(b) {
    if(b & 1LL) res = (res * a) % mod;
    b >>= 1LL;
    a = (a * a) % mod;
  }
  return res;
}

ll go(int cur, int sum) {
