//二分累乗法 xのe乗
ll binpow(ll x, ll e) {
  ll a = 1, p = x;
  while(e > 0) {
    if(e%2 == 0) {p = (p*p) % MOD; e /= 2;}
    else {a = (a*p) % MOD; e--;}
  }
  return a % MOD;
}

void pascalTriangle(int n) {
  REP(i, n) {
    comb[i][0] = 1;
    comb[i][i] = 1;
    FOR(j, 1, i) comb[i][j] = (comb[i-1][j] + comb[i-1][j-1]) % MOD;
  }
}

void initFact(int n) {
  fact[0] = fact[1] = 1;
  ifact[1] = 1;
  FOR(i, 2, n) {
    fact[i] = (fact[i-1] * i) % MOD;
    ifact[i] = binpow(fact[i], MOD-2);
  }
}

ll P(ll n, int r) {
  return fact[n]*binpow(fact[n-r], MOD-2)%MOD;
}

