ll pnk(ll n, ll k) {
  ll result = 1, pn = n, now = 0;
  while(k>=1<<now) {
    if (k&1<<now) result = result * pn % MOD;
    pn = pn * pn % MOD;
    now++;
  }
  return result;
}

