ll mod_pow(ll x, ll n) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = (res * x) % mod;
        x = (x * x) % mod;
        n >>= 1;
    }
    return res;
}

ll mod_inverse(ll x) {
    return mod_pow(x, mod-2);
}

const int max_n = 2010;
ll fact[max_n];
ll fact_inv[max_n];
void calc_fact() {
    fact[0] = 1;
    for (ll i = 1; i < max_n; i++)
        fact[i] = (fact[i-1] * i) % mod;
    fact_inv[max_n-1] = mod_inverse(fact[max_n-1]);
    for (ll i = max_n-2; i >= 0; i--)
        fact_inv[i] = (fact_inv[i+1] * (i+1)) % mod;
}
ll mod_comb(ll n, ll k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return (fact[n] * fact_inv[k] % mod) * fact_inv[n-k] % mod;
}

ll calc_comb(int m, int s, int k) {
    ll res = 1;
    for (int i = 0; i < s; i++) {
        res = res * mod_comb(m, k) % mod;
        m -= k;
    }
    res = res * fact_inv[s] % mod;
    return res;
}

ll calc(int m, int k) {
    if (m == 0) return 1;
    if (m < 0 || k > b) return 0;
    if (dp[m][k] < 0) {
        ll res = calc(m, k+1);
        for (int i = c; i <= d && m >= i*k; i++) {
            res = (res + calc_comb(m, i, k) * calc(m-i*k, k+1)) % mod;
        }
        dp[m][k] = res;
    }
    return dp[m][k];
}

ll solve() {
    memset(dp, -1, sizeof(dp));
    calc_fact();
    return calc(n, a);
}

