void build() {
	fact[0] = fact[1] = 1;
	for (int i=2;MAX_N>i;i++) {
		fact[i] = fact[i-1]*i;
		fact[i]%=mod;
	}
	memset(C,0,sizeof(C));
	for (int i=1;MAX_N>i;i++) {
		C[i][1] = i;
	}
	for (int i=2;MAX_N>i;i++) {
		for(int j=2;i>=j;j++) {
			C[i][j] = C[i-1][j] + C[i-1][j-1];
		}
	}
}

