int N , A , B , C , D;
int c[MAX][MAX] , gi[MAX] , ni[MAX] , np[MAX][MAX] , dp[MAX][MAX];
void U(int &now , int val){ now = (now + val) % mod; }
int32_t main(){
    IOS;
    gi[0] = ni[0] = ni[1] = 1;
    REP(i , 1 , MAX) gi[i] = gi[i - 1] * i % mod;
    REP(i , 2 , MAX) ni[i] = ni[mod % i] * (mod - mod / i) % mod;
    REP(i , 2 , MAX) ni[i] = ni[i - 1] * ni[i] % mod;
    REP(i , 1 , MAX) REP(j , 1 , MAX){
        if(j == 1) np[i][j] = ni[i];
        else np[i][j] = np[i][j - 1] * ni[i] % mod;
    }
    REP(i , 0 , MAX) REP(j , 0 , i + 1){
        if(i == j) c[i][j] = 1;
        else c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % mod;
    }

    cin >> N >> A >> B >> C >> D;
    dp[A][N] = 1;
    REP(i , A , B + 1){
        REP(j , 0 , N + 1){
            // DB4(i , j , dp[i][j] , "");
            U(dp[i + 1][j] , dp[i][j]);
            REP(k , C , D + 1){
                if(k * i > j) break;
                else {
                    int all = k * i;
                    int tmp = gi[all] * np[i][k] % mod * ni[k] % mod;
                    U(dp[i + 1][j - all] , dp[i][j] * c[j][all] % mod * tmp % mod);
                }
            }
        }
    }
    cout << dp[B + 1][0] << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long kai(int n, int r) {
  long long ans = 1;
  while (r > 0) { ans *= n; ans %= 1000000007; n--; r--; }
  return ans;
}

long long f(int n, int k, int x) {
  // n人からk人組をx個作る場合の数
  if (n < k * x) return 0;
  long long ans = 1;
  long long on = n;
  for (int i = 0; i < x; i++) {
    ans *= kai(n, k) / kai(k, k);
    n -= k;
  }
  if (on - k * x == k) x++;
  return ans / kai(x, x);
}

void solve(long long N, long long A, long long B, long long C, long long D){
  long long dp[1001][1001] = {0};
  for (int i = 0; i < 1001; i++) {
    dp[i][0] = 1;
  }
  long long ans = 0;
  for (int n = 1; n <= N; n++) {
    for (int k = A; k <= B; k++) {
      long long sum = 0;
      for (int x = 0; x <= D; x++) {
        if (x != 0 && x < C) continue;
        if (n - k * x == k && x + 1 > D) continue;
        if (n - k * x < 0) continue;
        sum += (f(n, k, x) % 1000000007) * (dp[k - 1][n - k * x] % 1000000007) % 1000000007;
      }
      dp[k][n] = sum;
    }
  }
  cout << dp[B][N] << endl;
}

int main(){	
	long long N;
	long long A;
	long long C;
	long long B;
	long long D;
	scanf("%lld",&N);
	scanf("%lld",&A);
	scanf("%lld",&B);
	scanf("%lld",&C);
	scanf("%lld",&D);
	solve(N, A, B, C, D);
	return 0;
}

