  return dp[i][j];
}

LLI comb(int n, int k) {
  if (n < 0) return 0;
  if (n < k) return 0;
  if (memo[n][k]) return memo[n][k];
  if (k == 0 || k == n) return 1;
  return memo[n][k] = (comb(n-1, k-1) + comb(n-1, k)) % MOD;
}

