const int MOD = ten(9) + 7;
const int NCK = 1100;

ll nck[NCK + 1][NCK + 1];
ll fa[NCK + 1];
void calc_nck() {
	FOR(i, NCK) {
		nck[i][0] = nck[i][i] = 1;
		for (int j = 1; j <= i; j++) {
			nck[i + 1][j] = (nck[i][j - 1] + nck[i][j]) % MOD;
		}
	}
	fa[0] = fa[1] = 1;
	FOR(i, NCK - 1) fa[i + 1] = fa[i] * (i + 1) % MOD;
}

int a, b, c, d;
ll memo[1020][1020];
ll dfs(int idx, int rem) {
	if (rem == 0) return 1;
	if (idx > b) return 0;

	auto& ret = memo[idx][rem];
	if (ret != -1) return ret;

	ret = 0;
	ll t1 = dfs(idx + 1, rem);
	(ret += t1) %= MOD;
	ll coff = 1;
	FOR(i, c - 1) {
		ll up = rem - idx * i;
		ll dn = idx;
		if(up >= 0) coff = coff * nck[up][dn] % MOD;
	}
	for (int use = c; use <= d; use++) {
		int nrem = rem - use * idx;
		if (nrem < 0) break;

		ll up = rem - idx * use + idx;
		ll dn = idx;
		coff = coff * nck[up][dn] % MOD;
		ll t2 = dfs(idx + 1, nrem);
		ll xx = mod_inv<int>(fa[use], MOD);
		ll t3 = coff * t2 % MOD * xx % MOD;

		ret += t3;
	}

	return ret %= MOD;
}

int main() {
	calc_nck();
	memset(memo, -1, sizeof(memo));

	int n;
	reader(n);
	reader(a, b, c, d);

	ll ans = dfs(a, n);
	writerLn(ans % MOD);

	return 0;
}

