ll invl(ll a,ll b,ll m){//ap-2乗るを返す
	ll tmp=1;
	while(b){
		if(b&1){
			tmp=(tmp*a)%m;
		}
		a=(a*a)%m;
		b/=2;
	}

	return tmp%m;
}

void init(){
