LL dp[1005][1005];
const int MAX = 1005;
LL fac[MAX], finv[MAX], inv[MAX];

void init() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

LL  ncr(int n, int k) {
	if (n < k)return 0;
	if (n < 0 || k < 0)return 0;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

LL mod_pow(LL a, LL p) {
	LL ret = 1;
	LL tmp = a;
	while (p) {
		if (p & 1)ret = (ret * tmp) % MOD;
		p >>= 1;
		tmp = (tmp * tmp) % MOD;
	}
	return ret;
}

