	FOR(i, a, b + 1) {
		REP(j, n+1) {
			if (dp[i][j] == 0)continue;
			dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD;
			if (j + c * i > n)continue;
			FOR(k, c, d + 1) {
				if (j + k * i > n)break;
				LL tmp = (fac[n - j] * finv[n - j - k * i]) % MOD;
				tmp = (tmp * mod_pow(finv[i], k)) % MOD;
				tmp = (tmp * finv[k]) % MOD;
				dp[i + 1][j + k * i] = (dp[i + 1][j + k * i] + dp[i][j]*tmp) % MOD;
