}

int f(int x, int n) {
  if (dp[x][n] != -1) return dp[x][n];
  if (n == 0) return dp[x][n] = 1;
  if (x < A) return dp[x][n] = 0;
  long long s = 0;
  s += f(x-1, n);
  long long y = 1, yn = n;
  for (int k=C; k<=D; k++) {
    if (n-k*x < 0) break;
    y = (1LL * y * comb[yn][x]) % MOD;
    yn -= x;
    long long b = (1LL * y * factinv[k]) % MOD;
    s = (s + 1LL * b * f(x-1, n-k*x)) % MOD;
  }
  return dp[x][n] = s;
}

