#define MAX_N 1005
const ll MOD = 1e9+7;
ll Inv[MAX_N];
ll fact[MAX_N];
ll factInv[MAX_N];
void Inv_init(){
    Inv[1] = 1;
    for(int i = 2; i < MAX_N; i++) Inv[i] = Inv[MOD%i] * (MOD - MOD/i) % MOD;
}
void fact_init(){
    fact[0] = fact[1] = factInv[0] = factInv[1] = 1;
    for(int i = 2; i < MAX_N; i++){
        fact[i] = (fact[i-1] * i) % MOD; factInv[i] = (factInv[i-1] * Inv[i])%MOD;
    }
}

// a^b % MOD;
ll powmod(ll a,ll b) {ll res=1;a%=MOD; for(;b;b>>=1){if(b&1)res=res*a%MOD;a=a*a%MOD;}return res;}
// 逆元 1/a % MOD
ll inversemod(ll a) { return powmod(a,MOD - 2);}
ll nCr(ll n,ll r) {
    if(n < r) return 0;
    return (fact[n] * (factInv[r] * factInv[n-r] % MOD)) % MOD;
}

void init(){
    Inv_init();
    fact_init();
}

ll N,A,B,C,D;
ll memo[MAX_N][MAX_N]; // memo[n][a] := 残り人数が n で 指定人数が a 以上の時の総数
void init2(){
    for(int i = 0; i < MAX_N;i++)for(int j = 0; j < MAX_N;j++) memo[i][j] = -1;
}
ll dfs(ll n,ll a){
    ll &res = memo[n][a];
    if(res != -1) return res;
    if(n == 0) return res = 1;
    if(n < a || a > B) return res = 0;

    res = 0;
    (res += dfs(n,a+1))%=MOD;
    ll F = 1;
    for(ll x = 1; x <= D; x++){
        if(a > n) break;
        (F *= nCr(n,a))%=MOD; (F *= Inv[x])%=MOD; n-=a;
        if(x >= C){ (res += F*dfs(n,a+1))%=MOD; }
    }
    return res;
}
ll solve(){
    ll res = 0;
    cin >> N >> A >> B >> C >> D;
    res = dfs(N,A);
    return res;
}
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    init();
    init2();
    cout << solve() << endl;
