const int N = 1e3 + 7, mod = 1e9 + 7;

int POW(int a, int b, int mod) {
	a %= mod; int r = 1;
	for(int i = b; i > 0; i >>= 1) {
		if(i & 1) r = (r * a) % mod;
		a = (a * a) % mod;
	}
	return r;
}

int f[N], n, dp[10001][1001];

vector <tuple <int, int, int> > v;

vector <int> nxt;


int g(int lft, int idx) {
	if(idx >= v.size()) {
		return (lft == 0 ? f[n] : 0);
	}
	if(~dp[idx][lft]) {
		return dp[idx][lft];
	}
	int res = g(lft, idx + 1);
	int x, y, z; tie(x, y, z) = v[idx];
	if(x * y <= lft) {
		res += g(lft - x * y, nxt[idx]) * z % mod;
		res %= mod;
	}
	return dp[idx][lft] = res;
}



