	dp[a - 1][n] = 1;
	for (int i = a; i <= b; i++) {
		for (int j = 0; j <= n; j++) {
			dp[i][j] += dp[i - 1][j];
			for (int k = c; k * i <= j && k <= d; k++) {
				long long int tmp = kaizyou[j] * rui(kaizyou[i], mod - k - 1, mod);
				tmp %= mod;
				tmp *= rui(kaizyou[j - i * k], mod - 2, mod);
				tmp %= mod;
				tmp*=rui(kaizyou[k], mod - 2, mod);
				tmp %= mod;
				dp[i][j - i * k] += dp[i - 1][j] * tmp;
