    {
        C[i][0]=C[i][i]=1;
        for(int j=1; j<i; ++j) C[i][j] = (C[i-1][j-1]+C[i-1][j])%mod;
    }

    // fact
    fact[0]=fact[1]=1;
    for(int i=2; i<1001; ++i) fact[i]=(fact[i-1]*i)%mod;

    rep(i,1001) fact_inv[i] = mod_inv(fact[i]);

