    memset(dp,-1,sizeof(dp));
}

ll dfs(int rem, int group)
{
    if(group==b+1) return rem?0:1;
    if(dp[rem][group]>=0) return dp[rem][group];

    ll ret=0;

    // 0人
    (ret+=dfs(rem,group+1))%=mod;

    if(c*group <= rem)
    {
        int tr = rem;
        int i=0;
        ll comb=1;
        while(i<c)
        {
            (comb*=C[tr][group])%=mod;
            tr -= group;
            ++i;
        }

        while(i<=d)
        {
            if(tr<0) break;

            // printf(" i = %d\n", i);
            ll add = (dfs(rem-i*group, group+1)*comb)%mod;
            (add*=fact_inv[i])%=mod;

            (ret+=add)%=mod;

            (comb*=C[tr][group])%=mod;
            tr -= group;
            ++i;
        }
    }

    return dp[rem][group]=ret;
}

