{
    return (ll)a * b % mod;
}

void solve (int n)
{
    int a, b, c, d;
    cin >> a >> b >> c >> d;

    vi dp(n + 1, 0);
    vi ndp(n + 1);
    dp[0] = 1;

    const int B = n + 1;
    vvi C(B, vi(B));
    for (int i = 0; i < B; i++)
    {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++)
        {
            C[i][j] = C[i - 1][j];
            add(C[i][j], C[i - 1][j - 1]);
        }
    }

    vi inv(B, 1);
    for (int i = 2; i < B; i++)
    {
        inv[i] = mod - mult(mod / i, inv[mod % i]);
        assert(mult(inv[i], i) == 1);
    }

    for (int i = a; i <= b; i++)
    {
        fill(ALL(ndp), 0);
        for (int j = 0; j <= n; j++)
        if (dp[j])
        {
            int coef = 1;
            for (int g = 0; g * i + j <= n; g++)
            {
                if (g != 0)
                {
                    coef = mult(coef, C[g * i + j][(g - 1) * i + j]);
                    coef = mult(coef, inv[g]);
                }
                if (g == 0 || (c <= g && g <= d))
                    add(ndp[g * i + j], mult(coef, dp[j]));
            }
        }

        copy(ALL(ndp), dp.begin());
    }

    cout << dp[n] << endl;
}

