            dp[i][j] = dp[i - 1][j];
            for(ll k = c; k <= d && j - i * k >= 0; k++){
                dp[i][j] += ((dp[i - 1][j - i * k] * nPr(n - j + i * k, i * k, MOD) % MOD)
                            * Fermat((POW(fact[i], k, MOD) * fact[k]) % MOD, 1, MOD)) % MOD;
                dp[i][j] %= MOD;
            }
        }
    }
    cout << dp[b][n] << endl;
}

