ll POW(int x, int n){
  ll v=1;
  while(n>1){
    if(n%2==1)v=MULT(v, x);
    x=MULT(x,x);
    n/=2;
  }
  return v;
}

ll INV(int x){
  return POW(x, MOD-2);
}

void FCT(){
  fct[0]=1;
  for (int i=0;i<20010;++i) fct[i+1]=MULT(fct[i],i+1);
}

void INV_FCT(){
  ifct[20010-1]=INV(fct[20010-1]);
  for (int i=20010-1;i>=1;--i) ifct[i-1]=ifct[i]*i;
}

ll comb(int n, int k){
  return MULT(fct[n], MULT(ifct[k], ifct[n-k]));
}

