ll mpow(ll a, ll b) {
	if (b == 0) return 1;
	ll res = mpow(a, b / 2);
	res *= res;
	res %= mod;
	if (b%2LL == 1) {
		res *= a;
		res %= mod;
	}
	return res;
}

ll comb(ll a, ll b) {
	ll res = fact[a];
	res *= inv[b];
	res %= mod;
	res *= inv[a - b];
	return res%mod;
}

int main() {
