	for(LL count = A; count <= B && sz*count <= n; count++)
	{
		LL x1 = C(n,sz*count)*cost[count][sz]%MOD;
		   x1 = (x1*dp(n-sz*count,sz+1))%MOD;
		ans = (ans+x1)%MOD;
	}
	return memo[n][sz] = ans;
}
