ll pow(ll a, ll b, ll mod){
  if (b==0) return 1;
  else if (b%2==0) {
    ll temp=pow(a,b/2,mod);
    return (temp*temp)%mod;
  }
  else {
    return (a*pow(a,b-1,mod))%mod;
  }
}

