  for (int i=0; i<=1000; i++){
    rfactorial[i]=pow(factorial[i],mod-2,mod);
  }
}


ll C(ll n, ll k){
  return (((factorial[n]*rfactorial[k])%mod)*rfactorial[n-k])%mod;
}


