int N, A, B, C, D;

ll f(int i, int j, int x) {
  if (x == 0) return 1;
  if (N - j + i * x < i * x) return 0;
  ll ret = fact[N - j + i * x];
  ret *= mod_inverse(fact[N - j], MOD);
  ret %= MOD;
  ret *= mod_inverse(mod_pow(fact[i], x, MOD), MOD);
  ret %= MOD;
  ret *= mod_inverse(fact[x], MOD);
  ret %= MOD;
  return ret;
}

