void solve ( ) {
    fac[ 0 ] = 1 ;
    for ( int i = 1 ; i <= n ; ++ i ) {
        fac[ i ] = ( fac[ i - 1 ] * i ) % MOD ;
    }
    inv[ n ] = fastpow ( fac[ n ] , MOD - 2 ) ;
    for ( int i = n - 1 ; i >= 0 ; -- i ) {
        inv[ i ] = ( inv[ i + 1 ] * ( i + 1 ) ) % MOD ;
    }

    dp[ mng - 1 ][ n ] = 1 ;
    for ( int i = mng ; i <= mxg ; ++ i ) {
        long long hh = fastpow ( inv[ i ] , lo ) ;
        for ( int j = 0 ; j <= n ; ++ j ) {
