                Dp[i][y] -= MOD;
            }
            for (int u = C; u <= D; u++)
            {
                if (u*i + y > N)
                {
                    break;
                }
                S = Dp[i-1][y];
                S *= F[N-y];
                S %= MOD;
                S *= Power((F[N-y-u*i]*F[u])%MOD, MOD-2);
                S %= MOD;
                S *= Power(F[i], MOD-u-1);
                S %= MOD;
                //S *= Power(F[u], MOD-2);
                //S %= MOD;
                Dp[i][y+u*i] += S;
                if (Dp[i][y+u*i] > MOD)
                {
                    Dp[i][y+u*i] -= MOD;
                }
            }
        }
    }
    cout << Dp[B][N];
