  fac[0] = facinv[0] = 1;
  for(int i = 1; i <= N; i++){
    fac[i] = 1LL * fac[i - 1] * i % MOD;
    facinv[i] = 1LL * facinv[i - 1] * inv[i] % MOD;
  }

  for(int i = 0; i <= N; i++){
    for(int j = 0; j <= N; j++) dp[i][j] = -1;
  }

  printf("%d\n", dfs(B, N));
  return 0;
}

