//拡張ユークリッドの互除法
int extgcd(int a, int b, int& x, int& y) {
    int d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

// mod逆元
int mod_inverse(int a, int m) {
    int x, y;
    extgcd(a, m, x, y);
    return (m + x % m) % m;
}

//繰り返し二乗法
int mod_pow(int x, int n, int m) {
    if (n == 0)
        return 1;
    int res = mod_pow(x * x % m, n / 2, m);
    if (n & 1)
        res = res * x % m;
    return res;
}

int DP(int n, int a) {
    if (dp[n][a] != -1) {
        return dp[n][a];
    }
    if (n == 0) {
        return dp[n][a] = 1;
    }
    if (a > B) {
        return dp[n][a] = 0;
    }
    dp[n][a] = DP(n, a + 1);
    int div = 1;
    for (int i = C; i <= D && n >= a * i; i++) {
        (div *= fact_inv[a]) %= mod;
        int pattern =
            fact[n] * fact_inv[n - a * i] % mod * div % mod * fact_inv[i] % mod;
        (dp[n][a] += DP(n - a * i, a + 1) * pattern % mod) %= mod;
    }
    return dp[n][a];
}

