ll rec(int v, int rem) {

	if (rem == 0) return 1;
	if (v > b) return 0;
	ll & res = memo[v][rem];

	if (~res) return res;
	res = rec(v + 1, rem);
	res %= INF;
	ll vr = 1;
	ll pt = 1;
	for (ll i = 1; i < c; i++)
	{
		vr *= table[rem - (v * (i - 1))][v];
