const int SET_FACT_MAX = 1010;
mint fact[SET_FACT_MAX];
mint revFact[SET_FACT_MAX];

void setFact() {
	const int N = SET_FACT_MAX;
	fact[0] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = fact[i - 1] * i;
	}
	revFact[N - 1] = fact[N - 1] ^ (mod - 2);
	for (int i = N - 2; i >= 0; i--) {
		revFact[i] = revFact[i + 1] * (i + 1);
	}
}

mint nPr(int n, int r) { return n >= r ? fact[n] * revFact[n - r] : 0; }
mint nCr(int n, int r) { return nPr(n, r) * revFact[r]; }

mint solve() {
	setFact();
	int n = ri(), a = ri(), b = ri(), c = ri(), d = ri();
	out(n,a,b,c,d);
	vvm dp(b+1, vm(n+1));
	dp[a-1][0] = 1;

	rep(i, a, b+1) {
		rep(j, n+1) {
			dp[i][j] += dp[i-1][j];
			mint fi = revFact[i] ^ (c-1);
			rep(k, c, d+1) {
				if (j < i*k) break;
				fi *= revFact[i];
				dp[i][j] += dp[i-1][j-i*k] * nPr(n-(j-i*k), i*k) * revFact[k] * fi;
			}
		}
	}
	mint ans = dp[b][n];
	return ans;
}

void Main() {
	cout << solve() << endl;
}
