const ll mod = 1000000007;
const ll INF = mod * mod;

ll modinv[1010];

ll pow(ll x, ll r) {
	if (r == 0)return 1LL;
	if (r == 1LL)return x;
	ll temp = pow(x, r / 2LL);
	temp = temp * temp%mod;
	temp=temp*((r % 2LL) ? x : 1LL) % mod;
	return temp;
}
void get_modinv() {
	ll t = 1LL;
	for (ll i = 1LL; i <= 1000LL; i++) {
		t *= i;
		t %= mod;
	}
	modinv[1000] = pow(t, mod - 2);
	for (ll i = 1LL; i <= 1000LL; i++) {
		modinv[1000 - i] = modinv[1000 - i + 1] * (1000 - i + 1) % mod;
	}
}

ll Perm(ll peaple, ll gsize, ll num) {
	ll ret = 1LL;
	for (ll i = gsize * num-1; i >= 0; i--) {
		ret *= (peaple - i);
		ret %= mod;
	}
	ret *= pow(modinv[gsize], num);
	ret%= mod;
	ret *= modinv[num];
	ret %= mod;
	return ret;
}


int main() {
	int n, sizel, sizer, numl, numr;
	cin >> n >> sizel >> sizer >> numl >> numr;

	/* get mod inverse */
	get_modinv();

	ll dp[1000] = {};
	dp[0] = 1;
	for (ll i = sizel; i <= sizer; i++) {
		for (ll j = n; j >= 0; j--) {
			for (ll k = numl; k <= numr; k++) {
				if (i*k > j)break;
				if (dp[j - k * i] == 0)continue;
				dp[j] += dp[j - k * i] * Perm(n - j+i*k, i, k);
				dp[j] %= mod;
			}
		}
	}
	cout << dp[n] << endl;

	return 0;
}

