ll inv[N_MAX];
ll fac[N_MAX];
ll finv[N_MAX];
ll finv_pow[N_MAX][N_MAX];
ll dp[N_MAX][N_MAX];

void init(){
    inv[1] = 1;
    fac[0] = 1;
    fac[1] = 1;
    finv[0] = 1;
    finv[1] = 1;

    for(int i = 2; i < N_MAX; i++){
        fac[i] = (fac[i-1]*i)%P;
        inv[i] = ((-(P/i)*inv[P%i])%P+P)%P;
        finv[i] = (finv[i-1]*inv[i])%P;
    }

    for(int i = 0; i < N_MAX; i++){
        finv_pow[i][0] = 1;
    }

    for(int i = 0; i < N_MAX; i++){
        for(int j = 1; j < N_MAX; j++){
            finv_pow[i][j] = (finv_pow[i][j-1]*finv[i])%P;
        }
    }
    //init dp
    for(int i = 0; i < N_MAX; i++){
        dp[i][0] = 1;
    }
}

