int frac[MAX_N];
void init_frac(int N) {
  frac[0] = 1;
  for (int i = 1; i <= N; i++) {
    frac[i] = mod(frac[i-1] * i);
  }
}

int powM(int x, int n) {
  int res = 1;
  while (n > 0) {
    if ((n & 1) == 1) {
      res = mod(res * x);
    }
    x = mod(x * x);
    n >>= 1;
  }
  return res;
}

int inverse(int x) {
  return powM(x, MOD-2);
}

int perm(int n, int r) {
  if (n < 0 || n-r < 0) {
    return 0;
  }
  return mod(frac[n] * inverse(frac[n-r]));
}


