const LL mod = 1e9 + 7;
LL fermat(LL x, int y) {
	if (y == 0)return 1;
	if (y == 1)return x;
	LL F = fermat(x, y / 2);
	F *= F;
	F %= mod;
	if (y % 2)return (F*x) % mod;
	if (!(y % 2))return F;
}


int main() {
