    Cb[0][0] = 1;
    FOR(i, 1, N + 1) {
        Cb[i][0] = 1;
        for (int j = 1; j <= N; ++j) Cb[i][j] = (Cb[i - 1][j - 1] + Cb[i - 1][j]) % MOD;
    }
    FOR(i, 1, N + 1) {
        MI[i] = modInverse(i);
    }

    ll ans = dfs(N, B);
    cout << ans << endl;

    return 0;
}

