    long long inv(long long x) { return fast_pow(x, mod - 2); }
    void init_fact(){
        f[0] = 1LL;
        for(int i = 1 ; i < maxn ; ++i)
            f[i] = mul(i, f[i - 1]);
    }
    long long fact(int x){
        assert(x >= 0 && x < maxn);
        if(!f[0]) init_fact();
        return f[x];
    };
}math;

int solve(int i, int sz){
    if(i == n) return math.fact(n);
    if(sz > b) return 0;
    int &ret = dp[i][sz];
    if(~ret) return ret;
    ret = solve(i, sz + 1);
    if(i + c * sz > n) return ret;
    int j = i + c * sz, ng = c;
    int p = inv_pw[sz][c];
    while(j <= n && ng <= d){
        ret = math.add(ret, math.mul(inv_pw[ng][1], math.mul(p, solve(j, sz + 1))));
        p = math.mul(p, inv_pw[sz][1]);
        ng++;
        j += sz;
    }
    return ret;
}

