long long f(int n, int k) {
  if (memo[n][k] != -1) return memo[n][k];

  long long m = 0;
  for (int i=k+1; i<=B; i++) {
    if (i*C > n) break;
    for (int c=C; c<=D; c++) {
      if (i*c > n) break;
      int t = n;
      long long s = fact_inv[c];
      for (int j=0; j<c; j++) {
        s = (s * tr[t][i]) % MOD;
        t -= i;
      }
      m += (s * f(n-i*c, i)) % MOD;
      m %= MOD;
    }
  }
  return memo[n][k] = m;
}

