#define MINT (mint)

//mod MOD上での階乗
mint fact[N_MAX];
void init(){
  fact[0] = fact[1] = MINT 1;
  for(int i = 2; i < N_MAX; i++){
    fact[i] = fact[i-1] * i;
  }
}

//mod MOD上での逆元
inline mint inv(mint n){
  return MINT 1/n;
}

//二項係数の計算(mod MOD上)
inline mint COM(int n, int k){
  if(n<k) return 0;
  if(k<0) return 0;
  return fact[n]/(fact[k]*fact[n-k]);
}

inline mint PER(int n, int k){
  if(n<k) return 0;
  if(k<0) return 0;
  return fact[n]/fact[n-k];
}

