const int md = (int) 1e9 + 7;

inline int add(int a, int b) {
  a += b;
  if (a >= md) a -= md;
  return a;
}

inline int sub(int a, int b) {
  a -= b;
  if (a < 0) a += md;
  return a;
}

inline int mul(int a, int b) {
  return (int) ((long long) a * b % md);
}

inline int power(int a, long long b) {
  int res = 1;
  while (b > 0) {
    if (b & 1) {
      res = mul(res, a);
    }
    a = mul(a, a);
    b >>= 1;
  }
  return res;
}

inline int inv(int a) {
  a %= md;
  if (a < 0) a += md;
  int b = md, u = 0, v = 1;
  while (a) {
    int t = b / a;
    b -= t * a; swap(a, b);
    u -= t * v; swap(u, v);
  }
  assert(b == 1);
  if (u < 0) u += md;
  return u;
}

int main() {
  const int N = 1010;
  vector<int> fac(N), finv(N);
  fac[0] = finv[0] = 1;
  for (int i = 1; i < N; i++) {
    fac[i] = mul(fac[i - 1], i);
    finv[i] = inv(fac[i]);
  }

  int n, a, b, c, d;
  cin >> n >> a >> b >> c >> d;

  vector<int> dp(n + 1);
  dp[0] = 1;

  for (int i = a; i <= b; i++) {
    vector<int> new_dp = dp;
    for (int j = 0; j <= n; j++) {
      for (int k = c; k <= d; k++) {
        if (j - k * i < 0) break;
        int div = mul(power(finv[i], k), finv[k]);
        new_dp[j] = add(new_dp[j], mul(div, dp[j - k * i]));
      }
    }
    swap(dp, new_dp);
  }

  cout << mul(dp[n], fac[n]) << '\n';
  return 0;
}

