ll invl(ll a,ll b,ll m){//ap-2乗るを返す
	ll tmp=1;
	while(b){
		if(b&1){
			tmp=(tmp*a)%m;
		}
		a=(a*a)%m;
		b/=2;
	}

	return tmp%m;
}

void init(){
	F[0]=1;
	IF[0]=1;

	for(int i=1;i<=MAX_N;i++){
		F[i]=(F[i-1]*i)%M;
		IF[i]=invl(F[i],M-2,M)%M;//逆元を、フェルマーの小定理を利用して求める
	}
}

ll C(int n,int r){

	if(n<0||r<0||r>n)return (ll)0;
	if(r>n/2)r=n-r;

	//cout<<F[n]<<" "<<IF[r]<<" "<<IF[n-r]<<endl;
	ll ret=F[n]*IF[r]%M*IF[n-r]%M;
	return ret;
}

ll dfs(int p,int now){//now人ってる
	//cout<<p<<" "<<now<<endl;


	if(now==n)return dp[p][now]=1;	
	if(dp[p][now]!=-1)return dp[p][now];
	if(now>n||p>b)return dp[p][now]=0;

	ll ret=0;
		ret+=dfs(p+1,now);
		ret%=M;
		ll x=1,nin=n-now;

		for(int i=c;i<=d;i++){
			if(now+p*i<=n){
				ll tmp=dfs(p+1,now+p*i)%M;

				x=(x*C(nin,p))%M;
				nin-=p;
				tmp=(x*tmp)%M;
				tmp=(tmp*IF[i-c+1])%M;
				ret+=tmp;
				ret%=M;
			}
		}
		return dp[p][now]=ret%M;
}


