const int N = 1005;
int dp[N][N];
int ncr[N][N];
int par[N][N]; // par[i][j] -> partiton i into groups of j
int fact[N], ifact[N];

void solve(){
	fact[0] = 1;
	fr(i, 1, N - 1) {
		fact[i] = (fact[i - 1] * i) % mod;
	}
	ifact[N - 1] = pwr(fact[N - 1], mod - 2, mod);
	for(int i = N - 2; i >= 0; i--) {
		ifact[i] = (ifact[i + 1] * (i + 1)) % mod;
	}
	assert(ifact[0] == 1);
	int n, a, b, c, d;
	cin >> n >> a >> b >> c >> d;
	fr(i, 0, n) {
		ncr[i][0] = 1;
		fr(j, 1, i) {
			ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % mod;
		}
	}
	fr(j, 1, n) {
		par[0][j] = 1;
		for(int i = j; i <= n; i += j) {
			par[i][j] = par[i - j][j] * ncr[i][j];
			par[i][j] %= mod;
		}
	}
	dp[a - 1][0] = 1;
	fr(i, a - 1, b - 1) {
		fr(j, 0, n) {
			fr(k, c, d) {
				if(j + k * (i + 1) > n) break;
				int n_ways = ncr[n - j][k * (i + 1)];
				n_ways = (n_ways * par[k * (i + 1)][i + 1]) % mod;
				n_ways = (n_ways * ifact[k]) % mod;
				dp[i + 1][j + k * (i + 1)] += dp[i][j] * n_ways;
				dp[i + 1][j + k * (i + 1)] %= mod;
			}
			dp[i + 1][j] += dp[i][j];
			if(dp[i + 1][j] >= mod) 
				dp[i + 1][j] -= mod;
		}
	}
	cout << dp[b][n];
}

