template<class T>
struct ModInt {
    T x;
    ModInt(T x = 0) :x(x% mod) {}
    ModInt& operator+=(const ModInt a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    ModInt& operator-=(const ModInt a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    ModInt& operator*=(const ModInt a) {
        (x *= a.x) %= mod;
        return *this;
    }
    ModInt operator+(const ModInt a) const {
        ModInt res(*this);
        return res += a;
    }
    ModInt operator-(const ModInt a) const {
        ModInt res(*this);
        return res -= a;
    }
    ModInt operator*(const ModInt a) const {
        ModInt res(*this);
        return res *= a;
    }
    ModInt pow(T t) const {
        if (!t) return 1;
        ModInt a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }
    ModInt inv() const {
        return pow(mod - 2);
    }
    ModInt& operator/=(const ModInt a) {
        return (*this) *= a.inv();
    }
    ModInt operator/(const ModInt a) const {
        ModInt res(*this);
        return res /= a;
    }
};
using mint = ModInt<long long>;

class Comb
{
public:
    Comb() :fac(0), finv(0) {}
    Comb(int n) :fac(n + 1), finv(n + 1)
    {
        fac[0] = 1;
        for (int i = 1; i <= n; ++i) fac[i] = fac[i - 1] * i;
        finv[n] = fac[n].inv();
        for (int i = n; i >= 1; --i) finv[i - 1] = finv[i] * i;
    }

    void resize(int size) { *this = { size }; }

    mint C(int n, int k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k]);
    }
    mint P(int n, int k) {
        if (k < 0) return 0;
        return C(n, k) * fac[k];
    }
    // n!
    mint Fac(int n) {
        if (n < 0) return 0;
        return fac[n];
    }
    // 1/(n!)
    mint InvFac(int n) {
        if (n < 0) return 0;
        return finv[n];
    }

private:
    std::vector<mint> fac;
    std::vector<mint> finv;
};

int n, a, b, c, d;
Comb com;
mint dp[1005][1005];
void solve() {
    cin >> n >> a >> b >> c >> d;

    com.resize(n);
    dp[a][n] = 1;
    loop(i, a, b + 1) {
        mint res = com.InvFac(i).pow((ll)c - 1);
        rep(j, n + 1) {
            dp[i + 1][j] += dp[i][j];
            mint res2 = res;
            loop(k, c, d + 1) {
                if (i * k > j) break;
                dp[i + 1][j - i * k] += dp[i][j] * com.P(j, k * i) * com.InvFac(k) * (res2 *= com.InvFac(i));
            }
        }
    }

    cout << dp[b + 1][0].x << endn;

}

