      rev *= latte.rfact[i];
      revs[k] = rev * latte.rfact[k];
    }

    for(int j = 0; j <= N; j++) {
      for(int k = 1; k <= D; k++) {
        if(C <= k && k <= D && j - k * i >= 0) {
          dp[j - k * i] += dp[j] * revs[k];
        }
      }
    }
  }
