ModInt<> solve() {
  dp.assign(n + 1, vector<ModInt<>>(n + 1, 0));
  dp[a - 1][0] = 1;
  for (int i = a; i <= b; ++i) {
    for (int j = 0; j <= n; ++j) {
      dp[i][j] += dp[i - 1][j];
      for (int k = c; k <= d && j - k * i >= 0; ++k)
        dp[i][j] += dp[i - 1][j - k * i] * com.rfact(i).pow(k) * com.rfact(k);
    }
  }
  return dp[b][n] * com.fact(n);
}

