int mod_inv(int x, int m) {
    long long a = 1, b = 0, c = 0, d = 1, p = x, q = m;
    while (q != 0) {
        long long c0 = c, d0 = d, r = p / q;
        c = (a - c * r) % m;
        d = (b - d * r) % x;
        a = c0; b = d0;
        int t = p - r * q; p = q; q = t;
    }
    return (a + m) % m;
}

int mod_pow(int x, int e, int m) {
    long long ans = 1, p = x % m;
    while (e > 0) {
        if (e % 2 != 0) ans = (ans * p) % m;
        p = (p * p) % m;
        e >>= 1;
    }
    return ans;
}

