        finv[i] = mod_inv(fact[i], M);
    }
    long long dp[1001][1000] = {};
    dp[0][a] = 1;
    for (int m = c*a; m <= min(n, d*a); m += a)
        dp[m][a] = (long long)fact[m] * finv[m/a] % M * mod_pow(finv[a], m/a, M) % M;
    for (int k = a+1; k <= b; k++) {
