            for (int t = m - c*k; t >= max(0, m - d*k); t -= k) {
                dp[m][k] += dp[t][k-1] * fact[m] % M * finv[t] % M * finv[(m-t)/k] % M * mod_pow(finv[k], (m-t)/k, M) % M;
            }
            dp[m][k] %= M;
        }
