	dC[s][t]=1;
	for(int ms=s-t+1,ns=1;ns<=t;ms++,ns++){
		dC[s][t]*=ms;
		dC[s][t]/=ns;
		dC[s][t]%=1000000007;
	}
	return dC[s][t];
}
ll calcComb2(int s,int t){
	if(dC2[s][t]>0)return dC2[s][t];
	ll res=1;
