long long Cinv(long long x, long long y, const long long modl = mod){
	long long n = 1 ,r = 1;
	for(int i = 0; i < y; i++){
		n = n*(i+1)%modl;
		r = r*(x-i)%modl;
	}
	return r*inverse(n,modl)%modl;
}

long long Cdp(int m, int n, long long modd = mod)
{
	n = max(n,m-n);
	int h = m-n;
	int w = n;
	vector<vector<long long>> dp(h+1,vector<long long>(w+1,1));
	for(int i = 0; i < h; ++i) {
		for(int j = 0; j < w; ++j) {
			dp[i+1][j+1] = (dp[i+1][j]+dp[i][j+1])%modd;
		}
	}
	return dp[h][w];
}

LL modfac(int n){
	LL res = 1;
	FOR(i,1,n+1){
		res *= i;
		res %= mod;
	}
	return res;
}

