void precalc() {
	fact[0] = 1;

	for(int i = 1; i < MAX_N; ++i) {
		fact[i] = mult(i, fact[i - 1]);
	}

	for(int i = 0; i < MAX_N; ++i) {
		inv_fact[i] = divide(1, fact[i]);
	}

	for(int i = 0; i < MAX_N; ++i) {
		for(int j = 0; j < MAX_N; ++j) {
			P[i][j] = divide(1, binpow(fact[i], j));
		}
	}
