const long long mod = 1e9 + 7;

long long modpow(long long a, long long b) {
	if (b == 0) return 1;
	return modpow(a * a % mod, b / 2) * (b & 1 ? a : 1) % mod;
}

long long modinv(long long a) {
	return modpow(a, mod - 2);
}
vector<long long> fact, inv_fact;

void init_fact(int n) {
	fact.resize(n);
	fact[0]= 1;
	for (int i = 1; i < n; i++) {
		fact[i] = i * fact[i - 1] % mod;
	}
	inv_fact.resize(n);
	inv_fact[n - 1] = modinv(fact[n - 1]);
	for (int i = n - 2; i >= 0; i--) {
		inv_fact[i] = (i + 1) * inv_fact[i + 1] % mod;
	}
}

long long nPr(int n, int r) {
	if (n < r || n < 0 || r < 0) return 0;
	return fact[n] * inv_fact[n - r] % mod;
}

long long nCr(int n, int r) {
	if (n < r || n < 0 || r < 0) return 0;
	return fact[n] * inv_fact[r] % mod * inv_fact[n - r] % mod;
}

long long nHr(int n, int r) {
	if (n == 0 && r == 0) return 1;
	return nCr(n + r - 1, r);
}

LL N, A, B, C, D;

LL ans = 0LL;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);


	init_fact(3003);

	cin >> N >> A >> B >> C >> D;
	VVL dp(B + 2, VL(N + 1, 0));
	FOR(i, 0, B + 2)dp[i][0] = 1;

	// dp[i][j] := i人未満のグループを作ったときに、これまでj人を割り振ったときの組み合わせ数
	// dp[i][j] -> dp[i+1][j]
	// dp[i][j] -> dp[i+1][j + i*k]
	FOR(i, A, B + 1) {
		FOR(j, 0, N + 1) {
			if (!dp[i][j])continue;
			if (j) { //a人は割り振らない
				dp[i + 1][j] += dp[i][j];
				dp[i + 1][j] %= mod;
			}
			LL x = 1;
			FOR(k, 1, D + 1) {
				if (j + k*i > N)break;
				x *= (nCr(N - j - (i)*(k - 1), i) * modinv(k)) % mod;
				x %= mod;
				if (C <= k && k <= D) {
					dp[i + 1][j + k*i] += (dp[i][j] * x) % mod;
					dp[i + 1][j + k*i] %= mod;
				}
			}
		}
	}
	ans = dp[B + 1][N];
	cout << ans << "\n";

	return 0;
}

