ll mod_pow(ll x, ll n, ll mod) {
	if (n == 0) return 1;
	ll res = mod_pow(x * x % mod, n / 2, mod);
	if (n & 1) res = res * x % mod;
	return res;
}

void fact_inv(int n, ll mod) {
	fact.resize(n + 1);
	inv.resize(n + 1);

	fact[0] = 1;
	FOR(i, 1, n + 1) fact[i] = fact[i - 1] * i % mod;
	inv[n] = mod_pow(fact[n], mod - 2, mod);
	for (int i = n; i > 0; i--) inv[i - 1] = inv[i] * i % mod;
}

void nCr(ll n, ll r) {
	REP(i, n + 1) {
		REP(j, i + 1) {
			if (j == 0 || j == i) ncr[i][j] = 1;
			else ncr[i][j] = (ncr[i - 1][j - 1] + ncr[i - 1][j]) % MOD;
		}
	}
}

ll dfs(int rem, int mi) {
	if (rem == 0) return 1;

	if (~dp[rem][mi]) return dp[rem][mi];

	ll res = 0;
	FOR(i, mi + 1, b + 1) {
		if (rem < c * i) break;
		ll p = 1;

		FOR(j, c, d + 1) {
			if (rem < i * j) break;
			assert(rem - i * (j - 1) >= i);
			p = p * ncr[rem - i * (j - 1)][i] % MOD;
			(res += p * dfs(rem - i * j, i) % MOD * inv[j]) %= MOD;
		}
	}

	return dp[rem][mi] = res;
}

