ll choose(int n, int r) {
  if (n < 0 || r < 0 || n < r) return 0;
  return fact[n] * fact_inv[n-r] % MOD * fact_inv[r] % MOD;
}

ll mod_pow(ll a, ll b, ll p) {
  ll res = 1;
  while (b > 0) {
    if (b & 1) res = (res * a) % p;
    a = (a * a) % p;
    b >>= 1;
  }
  return res;
}

ll f(int m, int k) {
  ll res = fact[m*k];
  (res *= mod_pow(fact_inv[m], k, MOD)) %= MOD;
  (res *= fact_inv[k]) %= MOD;
  return res;
}

ll A, B, C, D;
ll dp[MAX_N][MAX_N];

ll rec(int n, int m) {
  if (n < 0) return 0;
  if (m == 0 && n == 0) return 1;
  if (m == 0 && n > 0) return 0;
  if (dp[n][m] != -1) return dp[n][m];
  ll res = rec(n, m-1);
  if (A <= m && m <= B) {
    for (int k = C; k <= D; k++) {
      if (n - k*m < 0) break;
      ll cur = rec(n - k*m, m-1);
      (cur *= choose(n, k*m)) %= MOD;
      (cur *= f(m, k)) %= MOD;
      res += cur;
    }
  }
  res %= MOD;
  return dp[n][m] = res;
}

