int ifact[N];
void pre(){
    memset(pascal , 0 , sizeof(pascal));
    for(int i = 0 ; i < N ; ++i){
        pascal[i][0] = 1;
        for(int j = 1 ; j <= i ; ++j){
            pascal[i][j] = add(pascal[i - 1][j - 1] , pascal[i - 1][j]);
        }
    }
    fact[0] = 1;
    ifact[0] = 1;
    for(int i = 1 ; i < N ; ++i){
        fact[i] = mult(fact[i - 1] , i);
        ifact[i] = mult(ifact[i - 1] , power(i , mod - 2));
    }
}
