    for(int sz = 1 ; sz <= b ; ++sz){
        put[sz][1] = 1;
        for(int i = 2 ; i <= d && sz * i <= n ; ++i){
            put[sz][i] = (1LL * pascal[sz * i][sz] * put[sz][i - 1]) % mod;
        }
        for(int i = 1 ; i <= d ; ++i){
            put[sz][i] = mult(put[sz][i] , ifact[i]);
        }
