                    res += (1LL * ((1LL * pascal[people][i * sz] * dp[!(sz & 1)][people - i * sz]) % mod) * put[sz][i]) % mod;
                }
                else{
                    break;
                }
            }
            dp[sz & 1][people] = res % mod;
        }
