long long inv(long long a, long long b) {
  long long b0 = b, t, q;
  long long x0 = 0, x1 = 1;
  if (b == 1) return 1;
  while (a > 1) {
    q = a / b;
    t = b, b = a % b, a = t;
    t = x0, x0 = x1 - q * x0, x1 = t;
  }
  if (x1 < 0) x1 += b0;
  return x1;
}

long long fact(int n) {
  long long x = 1;
  for (int i=2; i<=n; i++) {
    x = (x*n) % MOD;
  }
  return x;
}

long long f(int n, int k) {
  if (memo[n][k] != -1) return memo[n][k];

  long long m = 0;
  for (int i=k+1; i<=B; i++) {
    if (i*C > n) break;
    for (int c=C; c<=D; c++) {
      if (i*c > n) break;
      int t = n;
      long long s = fact_inv[c];
      for (int j=0; j<c; j++) {
        s = (s * tr[t][i]) % MOD;
        t -= i;
      }
      s = (s * f(n-i*c, i)) % MOD;
      m = (m + s) % MOD;
    }
  }
  return memo[n][k] = m;
}

int main() {
  cin >> N >> A >> B >> C >> D;
  for (int i=0; i<=N+1; i++) {
    for (int j=0; j<=N+1; j++) {
      memo[i][j] = -1;
    }
  }
  for (int i=0; i<=N; i++) memo[0][i] = 1;
  for (int i=0; i<=N; i++) {
    fact_inv[i] = inv(fact(i), MOD);
  }

  tr[0][0] = 1;
  for (int i=1; i<=N; i++) {
    tr[i][0] = 1;
    for (int j=1; j<=i; j++) {
      tr[i][j] = (tr[i-1][j-1] + tr[i-1][j]) % MOD;
    }
  }

  cout << f(N, A-1) << "\n";
  return 0;
}

