long long DP(long long l,long long r,long long res)
{
	if(res==0)
		return 1;
	if(r<l)
		return 0;
	if(~dp[r][res])
		return dp[r][res];
	dp[r][res]=DP(l,r-1,res);
	long long i,k=min(d,res/r),f=1,t=res,tmp=0;
	if(c>k)
		return 0;
	for(i=1;i<c&&t>=r;i++)
	{
		f=(1LL*f*C[t][r])%hlq;
		t-=r;
	}
	for(i=c;i<=k&&t>=r;i++)
	{
		f=(1LL*f*C[t][r])%hlq;
		t-=r;
		tmp=1LL*DP(l,r-1,t)*f%hlq;
		tmp=1LL*tmp*fac[i]%hlq;
		dp[r][res]=(tmp+dp[r][res])%hlq;
	}
	return dp[r][res];
}
long long pow_mod(long long a,long long x)
{
	long long ans=1;
	while(x)
	{
		if(x&1)
			ans=ans*a%hlq;
		a=a*a%hlq;
		x>>=1;
	}
	return ans;
}
