void solve() {
  int n, a, b, c, d;
  cin >> n >> a >> b >> c >> d;
  auto memo = make_vector(b + 1, n + 1, (mint) 0);
  repc(i, b) repc(j, n) {
    memo[i][j].x = -1;
  }
  auto f = [&](auto f, int i, int r) -> mint {
    if (i == b + 1) {
      if (r == 0) return (mint) 1;
      if (r != 0) return (mint) 0;
    }
    if (memo[i][r].x != -1) {
      return memo[i][r];
    }
    mint ret = 0;
    ret += f(f, i + 1, r);
    repic(k, c, d) {
      if (r < i * k) {
        break;
      }
      mint t = mc.facc[r] / (mc.facc[r - i * k] * exp(mc.facc[i], k) * mc.facc[k]);
      ret += f(f, i + 1, r - i * k) * t;
    }
    return memo[i][r] = ret;
  };
  mint ans = f(f, a, n);
  cout << ans << endl;
}

