ll rev(ll n) {
	ll ret = 1;
	ll exponent = MOD - 2;
	for (ll i = exponent; i; i >>= 1, n = n * n % MOD) {
		if (i & 1) {
			ret = ret * n % MOD;
		}
	}
	return ret;
}

void get_factorial_inverse(int n, int p) {
	fac[0][1] = 1;
	for (int i = 1; i <= n; ++i) {
		fac[i][1] = i * fac[i - 1][1] % p;
		for(int j = 2;j<=n;j++){
            fac[i][j] = fac[i][j-1]*fac[i][1]%p;
		}
	}
	invf[n][1] = rev(fac[n][1]);
	for (int i = n-1; i >= 0; --i) {
		invf[i][1] = invf[i + 1][1] * (i + 1) % p;
		for(int j = 2;j<=n;j++){
            invf[i][j] = invf[i][j-1]*invf[i][1]%p;
		}
	}
}

ll C(ll a,ll b)
{
    return fac[a][1]*rev(fac[b][1])%MOD*rev(fac[a-b][1])%MOD;
}
