void fct(){
  fc[0]=1;
  for (int i=0;i<200009;++i){fc[i+1]=mlt(fc[i], i+1);}
}

void ifct(){
  ifc[200009]=inv(fc[200009]);
  for (int i=200009;i>=1;--i){ifc[i-1]=mlt(ifc[i], i);}
}

ll comb(int n, int k){return mlt(fc[n], mlt(ifc[k], ifc[n-k]));}

int main(){
  int N, A, B, C, D;cin>>N>>A>>B>>C>>D;

