	fact[0] = 1;
	inv[0] = 1;
	inv[1] = 1;
	for (int i = 1; i <= n; i++)
	{
		fact[i] = i;
		if (fact[i - 1]) {
			fact[i] *= fact[i - 1];
			fact[i] %= mod;
			inv[i] = mod_inverse(fact[i], mod);
		}
	}

	dp[a - 1][0] = 1;
