ll modinv[1010];

ll pow(ll x, ll r) {
	if (r == 0)return 1LL;
	if (r == 1LL)return x;
	ll temp = pow(x, r / 2LL);
	temp = temp * temp%mod;
	temp=temp*((r % 2LL) ? x : 1LL) % mod;
	return temp;
}
void get_modinv() {
	ll t = 1LL;
	for (ll i = 1LL; i <= 1000LL; i++) {
		t *= i;
		t %= mod;
	}
	modinv[1000] = pow(t, mod - 2);
	for (ll i = 1LL; i <= 1000LL; i++) {
		modinv[1000 - i] = modinv[1000 - i + 1] * (1000 - i + 1) % mod;
	}
}

ll Perm(ll peaple, ll gsize, ll num) {
	ll ret = 1LL;
	for (ll i = gsize * num-1; i >= 0; i--) {
		ret *= (peaple - i);
		ret %= mod;
	}
	for (int i = 0; i < num; i++) {
		ret *= modinv[gsize];
		ret %= mod;
	}
	ret *= modinv[num];
	ret %= mod;
	return ret;
}


int main() {
	int n, sizel, sizer, numl, numr;
