inline void setFact(int N) {
	fact[0] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = fact[i - 1] * i;
		fact[i] %= mod;
	}
	revFact[N - 1] = powmod(fact[N - 1], mod - 2);
	for (int i = N - 2; i >= 0; i--) {
		revFact[i] = revFact[i + 1] * (i + 1);
		revFact[i] %= mod;
	}
}

inline ll getC(int a, int b) {
    assert(a >= 0 && b >= 0);
	return (((fact[a] * revFact[b]) % mod) * revFact[a - b]) % mod;
}

inline ll revmod(ll x) {
	return powmod(x, mod - 2);
