  for(int i = 0; i < 1010; i++){
    for(int j = 0; j < 1010; j++){
      dp[i][j] = 0;
    }
  }
  dp[0][A-1] = 1;

  for(int i = 0; i <= N; i++){
    for(int j = A; j <= B; j++){
      ll c = 1LL;
      int n = N-i;
      ll x = dp[i][j-1];
      for(int k = 1; k <= min(i/j, D); k++){
        c = mul(c, comb(n+k*j, j));
        if(k < C) continue;

        x = add(x, mul(mul(c, dp[i-j*k][j-1]), invfact[k]));
      }
      dp[i][j] = x;
    }
  }

  cout << dp[N][B] << endl;

  return 0;
}

