ll f(ll n, ll a, ll b)
{
    if (f_cache[n][b] >= 0LL) return f_cache[n][b];
    if (n == 0LL) return 1LL;
    if (n < a) return 0LL;

    ll ret = 0LL;

    debug_printf("---- f1 n=%lld a=%lld b=%lld\n", n, a, b);
    if (a > b) {
        debug_printf("---- end\n");
        return (n ? 0LL : 1LL);
    }

    ret += f(n, a, b - 1LL);

