        if (n < b * bgroup_count) break;

        ll np = perm[n];

        ll rpow = perm[b];
        rpow = mod_pow(rpow, bgroup_count, mod);
        rpow = mod_inv(rpow, mod);

        ll nrpow = mod_inv(perm[n - b * bgroup_count], mod);

        ll select = np * rpow;
        select %= mod;
        select *= nrpow;
        select %= mod;

        select *= mod_inv(perm[bgroup_count], mod);
        select %= mod;

        debug_printf("---- f3 n=%lld a=%lld b=%lld "
                     "bgroup_count=%lld select=%lld\n",
                     n, a, b, bgroup_count, select);

