	for (i = 1; i < 1001; i++) {
		for (j = 0; j < 1001; j++) {
			if (j == 0) comb[i][j] = 1;
			else comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % mod;
		}
	}

	fact[0] = 1;
	factInv[0] = 1;
	for (i = 1; i < 1001; i++) {
		fact[i] = (fact[i - 1] * i) % mod;
		factInv[i] = powmod(fact[i], mod - 2, mod);
	}
	for (i = 0; i < 1001; i++) {
		for (j = 0; j < 1001; j++) {
			powFactInv[i][j] = powmod(factInv[i], j, mod);
		}
	}
}

