int dfs(int n, int m) {
	if (n == 0){ return 1; }
	if (m > b) { return 0; }
	if (dp[n][m] != -1) return dp[n][m];

	int ret = dfs(n, m + 1);
	for (int x = c; x <= d; x++) {
		if (n < m * x) break;
		//n人の中から、m人グループをx個作る
		int way = fact[n] * factInv[n - m * x] % mod * powFactInv[m][x] % mod * factInv[x] % mod;
		int res = dfs(n - m * x, m + 1);
		ret += way * res;
		ret %= mod;
	}
	return dp[n][m] = ret;
}

