ll solve(int i, int rem)
{
	if (dp[i][rem] >= 0) return dp[i][rem];
	int num = a + i;
	if (num > b)
	{
		if (rem == 0) return 1;
		else return 0;
	}
	Mod res = 0;
	res += solve(i + 1, rem);
	FOR(j, c, d + 1)
	{
		int use = num * j;
		if (use > rem) break;
		Mod tmp = 1;
		REP(k, j)
		{
			tmp *= comb<mod>(rem - k * num, num);
		}
		tmp /= fact<mod>(j);
		res += tmp * solve(i + 1, rem - use);
	}
	return dp[i][rem] = int(res);
}

