long long solve(int i , int rem)
{
	if(rem == 0)
		return 1ll ;
	if(rem < 0 || i > rem)
		return 0ll ;
	long long &ret = dp[i][rem] ;
	if(ret != -1)
		return ret ;
	ret = solve(i+1 , rem) ;
	if(i >= a && i <= b)
	{
		for(int j = c ; j <= d ; ++j)
