			long long x = (solve(i+1 , rem - i * j) * comb.choose(rem , i*j)) % mod ;
			x = (x * comb.choose(i*j-1ll , j-1ll)) % mod ;
			ret = (ret + x) % mod ;
		}
	}
    cout<<i<<" "<<rem<<" : "<<ret<<"\n";
	return ret ;
}

