      dp[i][j] = dp[i-1][j];
      if(i < a || i > b) continue;
      for(lli k = c;k <= d;k++){
        if(j-i*k < 0) break;
        lli x = dp[i-1][j-i*k];
        x = (x*factorial(j))%mod;
        x = (x*inverse(factorial(k)))%mod;
        x = (x*inverse(pow(factorial(i),k)))%mod;
        x = (x*inverse(factorial(j-i*k)))%mod;
        dp[i][j] += x;
      }
      dp[i][j] %= mod;
    }
  }
  cout << dp[n][n] << endl;
