/* -------- <templates end> -------- */


struct Combination {
  vector<long long> fac, finv, inv;
  const int mod;

  Combination(int MAX, int mod = MOD) : fac(MAX + 1), finv(MAX + 1), inv(MAX + 1), mod(mod) {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i=2; i<=MAX; ++i) {
      fac[i] = fac[i-1] * i % mod;
      inv[i] = mod - inv[mod%i] * (mod/i) % mod;
      finv[i] = finv[i-1] * inv[i] % mod;
    }
  }

  long long P(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * finv[n-r] % mod;
  }

  long long C(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * (finv[r] * finv[n-r] % mod) % mod;
  }

  long long H(int n, int r) const {
    if (n < 0 || r < 0) return 0;
    return C(n + r - 1, r);
  }
};

void solve() {
  int n, a, b, c, d; cin >> n >> a >> b >> c >> d;

  Combination comb(n);

  Graph<int> dp(b-a+2, vi(n+1, 0));
  dp[0][n] = 1;

  rep(i,b-a+1) {
    int p = b-i;
    repeq(j,n) if (dp[i][j] != 0) {
      (dp[i+1][j] += dp[i][j]) %= MOD;
      ll co = 1;
      int div = 1;
      for (int k=j-p; k>=0; k-=p) {
        co = co * (comb.C(k+p, p) * comb.inv[div] % MOD) % MOD;
        if (div < c) continue;
        (dp[i+1][k] += dp[i][j] * co % MOD) %= MOD;
        if (div == d) break;
        ++div;
      }
    }
  }

  cout << dp[b-a+1][0] << endl;
}


/* -------- <programs end> -------- */


signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
  solve();
  return 0;
}

