const long long N = 1005;

const long long MOD = 1e9 + 7;
long long n, k, fact[N];

long long powMod(long long base, long long exp) {
	if(exp == 0)return 1;
	long long tmp = powMod(base, exp / 2);
	tmp = (1LL * tmp * tmp) % MOD;
	if(exp % 2) tmp = (tmp * base) % MOD;
	return tmp;
}

long long invMod(long long a) {
	return powMod(a, MOD - 2);
}

long long comb(long long n, long long k) {
	return (1LL * fact[n] * invMod((1LL * fact[k] * fact[n - k]) % MOD)) % MOD;
}

long long perm_rep(vector <long long> v) {
	long long sum = 0;
	for(auto i : v) 
		sum += i;
	long long ans = fact[sum];
	for(auto i : v) 
		ans = (1LL * ans * invMod(fact[i])) % MOD;
	// dbg(v);
	// dbg(ans);
	return ans;
}

void pre() {
	fact[0] = 1;
	for(long long i = 1; i < N; i++)
		fact[i] = (1LL * i * fact[i - 1]) % MOD;
}

long long a, b, c, d, dp[N][N], pm[N][N], ii[N], cc[N][N];

int main() {
	ios_base::sync_with_stdio(false);
	pre();
	cin >> n >> a >> b >> c >> d;

	for(long long i = 0; i <= n; i++)
		for(long long j = 0; j <= n; j++) {
			pm[i][j] = invMod(powMod(fact[i], j));
			if(i >= j)
				cc[i][j] = comb(i, j);
		}

	for(long long i = 0; i <= n; i++)
		ii[i] = invMod(fact[i]);

	dp[a - 1][0] = 1;
	for(long long i = a; i <= b; i++) {
		// dbg(i);
		for(long long j = 0;j <= n; j++) {
			dp[i][j] = dp[i - 1][j];
			// dbg(i, j, dp[i][j]);

			for(long long k = c; k <= d && i * k <= j; k++) {
				dp[i][j] += (((dp[i - 1][j - i * k] * cc[n - j + i * k][i * k] % MOD) * fact[i * k]  % MOD ) * pm[i][k] % MOD ) * ii[k] % MOD;
				dp[i][j] %= MOD;
			}
			// dbg(i, j, dp[i][j]);
		}
	}
	cout << dp[b][n];
}

