constexpr ll MOD = 1000000007;
ll power(const ll p,const int n)
{
  if(n==0){return 1;}
  if(n%2==1){power(p,n-1)*p%MOD;}
  else{const ll pp =power(p,n/2);
  return pp*pp%MOD;}
}

int main()
{
  int N,A,B,C,D;
  cin>>N>>A>>B>>C>>D;
  vector<ll> fact(N+1,1);
  vector<ll> inv(N+1,1);
  vector<ll> invfact(N+1,1);
  for(int i =2;i<=N;i++){
    fact[i]=fact[i-1]*i%MOD;
    inv[i]=power(i,MOD-2);
    invfact[i]=invfact[i-1]*inv[i]%MOD;
  }
  auto get =[&](const int i,const int l){
    return (fact[i]*invfact[i-l]%MOD)*invfact[l]%MOD;
  };
  vector<ll> dp(N+1,0);
  dp[0]=1;
  for(int i = A; i <= B; i++){
    auto tmp = dp;
    for(int j = 0; j <=N; j++){
      if(dp[j] == 0){continue;}
      ll mul=1;
      ll di=1;
      for(int k = C;k <= D; k++){
        const ll rest =N-j-k*i;
        if(rest<0){break;}
        (mul*=get(rest,i))%=MOD;
        (di*=inv[k-C+1])%=MOD;
        (tmp[j+k*i]+=mul*di%MOD)%=MOD;
      }
    }
    dp=tmp;
  }
  cout << dp[N]<< endl;
  return 0;
}

