		ll c = i;
		if (0 <= re - gn * c) {
			ll t = moddiv(aPb(re, gn * c), modpow(modfact(gn), c)) * f(gn - 1, re - gn * c);
			t %= MOD;
			t = moddiv(t, modfact(c));
			//printf("<%lld, %lld, %lld> = %lld\n",re, gn, c, t);
			ret = (ret + t) % MOD;
		}
	}
	return dp[gn][re] = ret;
}
