int C(int n,int r){
	if(n<r){
		return 0;
	}
	return mul(mul(fc[n],in[r]),in[n-r]);
}

int calc(int count,int size){
	int ans=1;
	int tot=size*count;
	for(int i=0;i<count;i++){
		ans=mul(ans,C(tot,size));
		tot-=size;
	}
	return mul(ans,in[count]);
}

void solve(){
	int n,a,b,c,d;
	cin>>n>>a>>b>>c>>d;
	dp[0][n]=1;
	for(int i=a;i<=b;i++){
		for(int set=c;set<=d;set++){
			if(set*i>n){
				break;
			}
			int cnst=calc(set,i);
			for(int last=n;last>=set*i;last--){
				add(dp[1][last-set*i],mul(mul(cnst,C(last,set*i)),dp[0][last]));
			}
		}
		for(int j=0;j<=n;j++){
			add(dp[0][j],dp[1][j]);
			dp[1][j]=0;
		}
	}
	cout<<dp[0][0];
}

