        cerr << "productMatrixByVector not implemented." << endl; exit(1); 
    }
    virtual void productDiagByMatrix(const vmint& diag_in) {
        cerr << "productDiagByMatrix not implemented." << endl; exit(1); 
    }

    virtual ~templateMatrixData() {}
