			for(int Fi = 0; j + Fi * i <= n; Fi ++){
				if((Fi == 0) || ((c <= Fi) && (Fi <= d) && (a <= i) && (i <= b)) ){
					wy2 = mul(wy, iv[Fi]);
					dp[i][j + Fi * i] += mul(dp[i - 1][j], wy2);
					dp[i][j + Fi * i] %= Mod;
				}

				wy *= nCr(n - j - (Fi * i), i);
				wy %= Mod;
			}
		}
	}
	cout << dp[b][n];
	return 0;
}

