		dp[0][j] = 1;

	fact[0] = 1;
	for (int i = 1; i <= n; ++i)
	{
		fact[i] = (i * fact[i-1]) % mod;
		factPow[i][0] = 1;

		for (int j = 1; j <= n; ++j)
			factPow[i][j] = (fact[i] * factPow[i][j-1]) % mod;
	}

