				ll num = fact[i];
				ll den = fact[i - k*j];
				den = (den * factPow[j][k]) % mod;
				den = (den * fact[k]) % mod;
				den = fastModExp(den, mod - 2);
				num = (num * den) % mod;

				dp[i][j] = (dp[i][j] + num*dp[i - k*j][j-1]) % mod;
			}
		}
	}

	cout << dp[n][b];
}

ll fastModExp(ll x, ll e)
{
	ll res = 1;
	x %= mod;
	while (e)
	{
		if (e % 2)
			res = (res * x) % mod;

		e /= 2;
		x = (x * x) % mod;
	}

	return res;
}

