struct Combination{
    using mint=ModInt<mod>;
    vector<mint> fact;
    Combination(int n){
        n++;
        fact.resize(n);
        for(int i=0;i<n;i++){
            if(!i){
                fact[i]=1;
            }else{
                fact[i]=fact[i-1]*i;
            }
        }
    }
    mint Fact(int x){
        return fact[x];
    }
    mint Comb(int n,int r){
        return fact[n]/fact[r]/fact[n-r];
    }
};

