map<tuple<int, int, int>, ll> cache2;
ll count2(int n, int group_size, int group_num) {
    if (cache2.count({ n, group_size, group_num })) {
        return cache2[{ n, group_size, group_num }];
    }

    ll ans = 1;
    REP(i, group_num) {
        ans *= choose(n, group_size);
        ans %= MOD;
        n -= group_size;
    }
    FOR(i, 2, group_num + 1) {
        ans = modDivision(ans, i);
    }
    cache2[{ n, group_size, group_num }] = ans;
    return ans;
}


