int solve(int i,int n){
	// A+i,A+i,A+i,......A+i+1,A+i+1,A+i+1,A+i+1.......A+i+k,A+i+k,A+i+k,A+i+k........B,B,B,B,B,B,B
	if( n < 0  || i + A > B )return 0;
	if( n == 0 ){
		bug2(i,n);
		return 1;
	}
	int &ans = dp[i][n];
	if( ans != -1 )return ans;
	ans = 0;
	ans = solve(i+1,n);
	for(int tot_grp = C ; tot_grp <= D  && tot_grp * (A+i) <= n; tot_grp++ ){
		int took = tot_grp * ( A + i );
		ans += solve(i+1,n-tot_grp * ( A + i )) * fact[ n ] % mod * facti[ took ] % mod * facti[ n - took ] % mod * fact[ took ] % mod * factpowi[A+i][tot_grp] %mod * facti[tot_grp] % mod;
		ans %= mod;
		bug2(tot_grp,facti[tot_grp]);
	}
	return ans;
}

