  memset(dp, 0, sizeof dp);
  inv[0] = fact[0] = 1;
  for (int i = 1; i <= n; ++i) {
    fact[i] = i * fact[i - 1];
    inv[i] = 1 / fact[i];
  }

  auto ncr = [&](int nn, int rr) {
    return fact[nn] * inv[nn - rr] * inv[rr];
  };

  auto groups = [&](int nn, int g) {
    return fact[nn] * mexp(inv[g], nn/g) * inv[nn/g];
  }; 

