      for (int used = n; used >= 0; --used) {
        if (j + used <= n) {
          dp[j + used][i] += dp[used][i - 1] * ncr(n - used, j) * groups(j, i);  
        }
      }         
    }

  } 

  cout << dp[n][b] << '\n';
