  long long dp[n+1][n+1] = {};//y人をk人以下のグループに分ける
  REP(k,n+1){
    REP(x,n+1){
      if(k == 0){
        if(x == 0){
          f[k][x] = 1;
        }
        continue;
      }
      if(n - k*x < 0)continue;
      long long temp = 1;
      for(int i = 0; i<x; i++){
        temp *= comb(n-i*k, k);
        temp = mod(temp);
      }
    }
  }
  REP(y,n+1){
    REP(k,n+1){
      if(k < a || b < k)continue;
      if((0 < x && x < c) || d < k)continue;
      if(y == 0){
        dp[y][k] = 1;
        continue;
      }
      long long x = y/k;
      for(long long i = 0; i<=x; i++){
        dp[y][k] += mod(f[k][i]*dp[y-k*i][k-1]);
        dp[y][k] = mod(dp[y][k]);
      }
    }
  }
  long long ans = dp[n][n];
  cout<<ans<<endl;
  return 0;
}

