mint dp[maxn][maxn];

int main() {
    ll n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;
    combination nck(n);
    dp[0][0] = 1;

    for (ll i = 0; i <= n; i++) {
        for (ll j = 0; j <= b - a + 1; j++) {
            ll num = a + j;
            // F_{num} == 0
            dp[i][j + 1] += dp[i][j];

            // C <= F_{num} <= D
            for (ll k = c; k <= d; k++) {
                ll all = i + num * k;
                if (all > n) break;
                mint divide = nck.fact[num * k] * modpow(nck.ifact[num].x, k);
                mint disregard = nck.ifact[k];
                dp[all][j + 1] += dp[i][j] * nck(n - i, num * k) * divide * disregard;
            }
        }
    }
    cout << dp[n][b - a + 1].x << endl;
}

