}
// 組み合わせ nCr を求める (modあり)
ll combination_mod(ll n, ll r, ll mod) {
    if(r > n-r) r = n-r;
    if(r == 0) return 1;
    ll a = 1;
    rep(i, 0, r) a = a * ((n-i) % mod) % mod;
    ll b = mod_pow(fact_mod(r, mod), mod-2, mod);
    return (a % mod) * (b % mod) % mod;
}
int N,A,B,C,D;
int main(){
	cin>>N>>A>>B>>C>>D;
	//%MOD下での階乗
	ll ex[SIZE]={1,0};
	for(int i=1;i<SIZE;i++){
		ex[i]=ex[i-1]*i%MOD;
	}
	//%MOD下での階乗の逆数
	ll inv[SIZE]={1,0};
	for(int i=1;i<SIZE;i++){
		inv[i]=mod_pow(i,MOD-2,MOD);
	}
	for(int i=1;i<SIZE;i++){
		inv[i]=inv[i-1]*inv[i]%MOD;
	}
	//モジュラ逆元
	ll gyaku[SIZE]={1,0};
	//コンビネーション
	ll comb[SIZE][SIZE]={};
	for(int i=0;i<SIZE;i++)
		for(int j=0;j<=i;j++)
			comb[i][j]=ex[i]*inv[i-j]%MOD*inv[j]%MOD;
	for(int i=1;i<SIZE;i++)
		gyaku[i]=mod_pow(i,MOD-2,MOD);
	//DP[j][i]=j人をi人以下のグループに分けるときの分け方
	ll DP[SIZE][SIZE]={};
	for(int i=0;i<=N;i++)
		DP[i][0]=1;
	for(int i=A;i<=B;i++){
		for(int j=0;j<=N;j++){
			//DP[i][j]が0のときは、無意味なので飛ばす
			if(DP[i][j]==0)
				continue;
			//k==0のとき、func()==1;
			//j==0のときは足さない（1なので）
			if(j!=0){
				DP[i+1][j]+=DP[i][j];
				DP[i+1][j]%=MOD;
			}
			//Fをつくる
			ll F=1;
			//(N-j)Ci*(N-j-i)Ci*...*(N-j-(C-1)i)Ci
			for(int k=0;k<C;k++){
				F*=comb[N-j-k*i][i];
				F%=MOD;
				F*=gyaku[k+1];
				F%=MOD;
			}
			for(int k=1;k<=D;k++){
				//N以上に遷移する必要はない
				if(j+i*k>N)
					break;
				if(C<=k){
					DP[i+1][j+i*k]+=DP[i][j]*F%MOD;
					DP[i+1][j+i*k]%=MOD;
					F*=comb[N-j-k*i][i];
					F%=MOD;
					F*=gyaku[k+1];
					F%=MOD;
				}
			}
		}
	}
	cout<<DP[B+1][N]<<endl;
	return 0;
}

