mint factorial(int x){
    if(x<=1)return 1;
    static vector<mint> dp(1e4);
    static vector<bool> used(1e4);
    mint &it = dp[x];
    if(used[x])return it;
    used[x] = true;
    return it = factorial(x-1) * x;
}

mint factorial_inv(int x){
    static vector<mint> dp(1e4);
    static vector<bool> used(1e4);
    if(used[x])return dp[x];
    used[x] = true;
    return dp[x] = factorial(x).inv();
}

