	}
}

ll C(int n,int r){

	if(n<0||r<0||r>n)return (ll)0;
	if(r>n/2)r=n-r;

	//cout<<F[n]<<" "<<IF[r]<<" "<<IF[n-r]<<endl;
	ll ret=F[n]*IF[r]%M*IF[n-r]%M;
	return ret;
}

