lli po(lli ii, lli j){
	lli t[32], ret = 1; t[0] = ii%MOD;
	rep(i, 31) t[i+1] = (t[i]*t[i])%MOD;
	rep(i, 31) if((j>>i)&1) ret = (ret*t[i])%MOD;
	if(ret < 0) cout << ii << " " << j << endl;
	return ret;
}

void rev(void){
	vector<lli> w(n+1);
	rep(i, n+1) w[i] = po(k[i], MOD-2);
	rep(i, n+1) rep(l, n+1) o[l][i] = (po(k[l], MOD-1-i)*w[i])%MOD;
	return;
}

