const int MAXN = 1024;
int binom[MAXN][MAXN];
int fact[MAXN], ifact[MAXN];
int N, A, B, C, D;
ll memo[MAXN][MAXN];
ll dp(int n, int k){
    ll &res = memo[n][k];
    if (res != -1) return res;
    if (k > B) return res = (n == 0);
    res = dp(n, k + 1);
    ll den = 1;
    for (int i = C; i <= D; i++){
        int tk = i * k;
        if (tk > n) break;
        if (i == C){
            for (int iter = 0; iter < C-1; iter++)
                den = den * ifact[k] % MOD;
        }
        den = den * ifact[k] % MOD;
        ll cur = (ll)binom[n][tk] * fact[tk] % MOD * den % MOD;
        cur = cur * dp(n - tk, k + 1) % MOD * ifact[i] % MOD;
        res += cur;
    }
    res %= MOD;
    //cout << n << ' ' << k << " = " << res << endl;
    return res;
}

