    }

    for (int i = 0; i < MAXN; i++)
        binom[i][0] = binom[i][i] = 1;
    for (int i = 2; i < MAXN; i++){
        for (int j = 1; j < i; j++){
            binom[i][j] = (binom[i-1][j] + binom[i-1][j-1]) % MOD;
        }
    }
    cin >> N >> A >> B >> C >> D;
    memset(memo, -1, sizeof memo);
    int res = dp(N, A);
