    for(int j = 0; j < 1010; j++){
      dp[i][j] = 0;
    }
  }
  dp[A-1][0] = 1;

  for(int j = A; j <= B; j++){
    for(int i = 0; i <= N; i++){
      ll c = 1LL;
      int n = N-i;
      ll x = dp[j-1][i];
      for(int k = 1; k <= min(i/j, D); k++){
        c = mul(c, comb(n+k*j, j));
        if(k < C) continue;

        x = add(x, mul(mul(c, dp[j-1][i-j*k]), invfact[k]));
      }
      dp[j][i] = x;
    }
  }

  cout << dp[B][N] << endl;

