}

ll mul(ll x, ll y){
    return (x%MOD)*(y%MOD)%MOD;
}

ll powll(ll x, ll y){
    ll res = 1LL;
    while(y){
        if (y & 1LL)
            res *= x;
        res %= MOD;
        x = (x*x) % MOD;
        y >>= 1LL;
    }
    return res;
}

ll divll(ll x, ll y){
    return (x * powll(y,MOD-2)) % MOD;
}

ll nPr(ll n, ll r){
    ll res = 1LL;
    FOR(i,1,r){
        res = (res * ((n-i+1) % MOD)) % MOD;
    }
    return res;
}

ll nCr(ll n, ll r){
    ll res = nPr(n,r);
    FOR(i,1,r){
        res = (res * powll(i,MOD-2)) % MOD;
    }
    return res;
}

