	if (p % 2 == 0) {
		int sub = qexp(b, p/2, m);
		return ((long long)sub * sub) % m;
	} else {
		long long sub = qexp(b, p/2, m);
		sub *= sub;
		sub %= m;
		sub *= b;
		return sub % m;
	}
}

int mod_inv(int x) {
	return qexp(x, MOD - 2, MOD);
}

int choose(int n, int k) {
	if (k < 0) return 0;
	if (k > n) return 0;
	long long ans = f[n];
	ans *= mod_inv(f[k]);
	ans %= MOD;
	ans *= mod_inv(f[n - k]);
	ans %= MOD;
	return ans;
}

