int f(int j, int i,  int k) {
  // j_P_i*k / (i!)^k / k!

  int ret = 0;
  ret += fact[j] / fact[j - i*k];
  ret /= pow(fact[i], k);
  ret /= fact[k];

  return ret;
}

// g人以下のグループで p人を分ける
int rec(int g, int p) {



  if( p == 0 and g == 0 ) return 1;
  if( g == 0 ) return 0;

  int ret = 0;
  ret += rec(g-1, p);

  if( A <= g and g <= B ) {
    for(int k = C; k <= D; k++) {
      if( g*k <= p ) {
        ret += f(p, g, k) *  rec(g - 1, p - g*k );
      }
    }
  }

  cout << g << ", " << p << " : "<< ret << "\n";

  return ret;


}


