		t-=r;
	}
	for(i=c;i<=k;i++)
	{
		f=(1LL*f*C[t][r])%hlq;
		t-=r;
		tmp=1LL*DP(l,r-1,t)*f%hlq*fac[i]%hlq;
		dp[r][res]=(tmp+dp[r][res])%hlq;
	}
	if(dp[r][res]==-1)
		return dp[r][res]=0;
	return dp[r][res];
}
