using i64 = long long;
const i64 MOD = 1e9 + 7;
i64 comb[1010][1010];
void setComb(const int n = 1010) {
    comb[0][0] = 1;
    for(int i : in(1, n)) {
        comb[i][0] = 1;
        for(int j : in(1, i + 1))
          comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
    }
}
template<typename T>
T mod_pow(T x, T n, const T mod) {
    T res = 1;
    for(; n > 0; n >>= 1) {
        if(n & 1) res = res * x % mod;
        x = x * x % mod;
    }
    return res;
}

template <typename T>
T mod_inv(T x, T mod) {
    return mod_pow(x, mod - 2, mod);
}
int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;
    setComb();
    vector<i64> dp(n + 1, 0LL);
    auto dp_ = dp;
    dp[0] = 1LL;
    for(int i : in(a, b + 1)) {
        dp_ = dp;
        for(int j : in(n + 1)) {
            if(dp[j] == 0) continue;
            int rest = n - j, val = 0;
            i64 tcom = 1LL;
            for(int k : in(d)) {
                if(rest < i) break;
                (tcom *= comb[rest][i]) %= MOD;
                (tcom *= mod_inv((i64)(k + 1), MOD)) %= MOD;
                rest -= i;
                val += i;
                if(k < c - 1) continue;
                (dp_[j + val] += dp[j] * tcom) %= MOD;
            }
        }
        dp = dp_;
