                    (t *= pre[k]) %= MOD;
                    // kCij * (ij)! / (i!)^j / j!
                    // k! / (k-ij)! j! (i!)^j
                    (t *= fact[k]) %= MOD;
                    (t *= ifact[k-i*j]) %= MOD;
                    (t *= ifact[j]) %= MOD;
                    (t *= powm(ifact[i], j)) %= MOD;

                    (dp[k - i*j] += t) %= MOD;
                }
        }
            }
    }
