ll inv(int n, int m){
  int _n = n % m;
  int _m = m;
  int div, mod;
  int l[2] = {1, 0};
  int r[2] = {0, 1};
  int _[2];
  ll ret;
  bool b = true;
  while (_n > 1){
    b = ! b;
    div = _m / _n;
    mod = _m % _n;
    if ( mod < 0){
      div -= 1;
      mod += _n;
    }
    _m = _n;
    _n = mod;
    l[0] += div*r[0];
    l[1] += div*r[1];
    _[0] = r[0];
    _[1] = r[1];
    r[0] = l[0];
    r[1] = l[1];
    l[0] = _[0];
    l[1] = _[1];
  }
  ret = r[1];
  if(!b)ret *= -1;
  ret %= m;
  if(ret < 0)ret += m;
  return ret;
}
