}

ll pow_mod(ll num, ll pow) {
    ll prod = 1;
    num %= M;
    while (pow > 0) {
        if (pow & 1) prod = prod * num % M;
        num = num * num % M;
        pow >>= 1;
    }
    return prod;
}

int main() {
