    for (ll i = 2; i < 1005; i++) {
        fac[i] = fac[i - 1] * i % M; // n!
        inv[i] = inv[M % i] * (M - M / i) % M; // n^-1
        fiv[i] = fiv[i - 1] * inv[i] % M; // (n!)^-1
    }

    dp[0][A-1] = 1;
    for (int i = 0; i <= N; i++) {
        for (int j = A-1; j < B; j++) {
            (dp[i][j + 1] += dp[i][j]) %= M;

            for (int k = C; k <= D; k++) {
                // dp[i][j] -> i人をj人以下のグループに
