long long kaimemo[1000][1000] = {0};

long long kai(int n, int r) {
  if (n < 0 || r < 0) return 1;
  if (kaimemo[n][r] != 0) return kaimemo[n][r];
  if (r == 0) return 1;
  kaimemo[n][r] = n * kai(n-1, r-1) % 1000000007;
  return kaimemo[n][r];
}

long long f(int n, int k, int x) {
  // n人からk人組をx個作る場合の数
  if (n < k * x) return 0;
  long long ans = 1;
  long long on = n;
  for (int i = 0; i < x; i++) {
    ans *= kai(n, k) / kai(k, k);
    ans %= 1000000007;
    n -= k;
  }
  if (on - k * x == k) x++;
  return ans / kai(x, x);
}

void solve(long long N, long long A, long long B, long long C, long long D){
  long long dp[1001][1001] = {0};
  for (int i = 0; i < 1001; i++) {
    dp[i][0] = 1;
  }
  long long ans = 0;
  for (int n = 1; n <= N; n++) {
    for (int k = A; k <= B; k++) {
      long long sum = 0;
      for (int x = 0; x <= D; x++) {
        if (x != 0 && x < C) continue;
        if (n - k * x == k && x + 1 > D) continue;
        if (n - k * x < 0) continue;
        sum += (f(n, k, x) % 1000000007) * (dp[k - 1][n - k * x] % 1000000007) % 1000000007;
      }
      dp[k][n] = sum;
    }
  }
  cout << dp[B][N] << endl;
}

int main(){	
	long long N;
