	long long C;
	long long B;
	long long D;
	scanf("%lld",&N);
	scanf("%lld",&A);
	scanf("%lld",&B);
	scanf("%lld",&C);
	scanf("%lld",&D);
	solve(N, A, B, C, D);
	return 0;
}

