	long long int tmp = 1;
	for(int i = 1; i <= c - 1; i++){
		if((i - 1) * k > n) return result[n][k];
		tmp *= (comb[n - (i - 1) * k][k] * powrev[i]) % mod;
		tmp %= mod;
	}
	for(int i = c; i <= d; i++){
		if(k * i > n) break;
		tmp *= (comb[n - (i - 1) * k][k] * powrev[i]) % mod;
		tmp %= mod;
		result[n][k] += (tmp * solve(n - k * i, k - 1)) % mod;
		result[n][k] %= mod;
	}
