            * nCk(N-(j-k*i), k*i) % MOD // 残りのN-(j-k*i)人のうちk*i人を選出する。
            * fac[k*i] % MOD // そのk*i人を順番に並べる
            * pow(finv[i], k) % MOD // i人ずつ、k人のグループごとにする。
            * finv[k]) %= MOD; // グループの順番は関係ない
      }
    }
  }

  cout << dp[B][N] << endl;
}

