//整数a,bに対し、ax + by = gcd(a,b) を満たす整数x,y,gcd(a,b) を計算する
ull extgcd(ull a, ull b, ull& x, ull& y) {
  ull d = a;
  if (b != 0) {
    d = extgcd(b, a%b, y, x);
    y -= (a/b) * x;
  } else {
    x = 1; y = 0;
  }
  return d;
}

//ax ≡ gcd(a,m) (mod m) を満たすxを計算する。
ull mod_inverse(ull a, ull m) {
  ull x, y;
  extgcd(a, m, x, y);
  return (m + x%m) % m;
}

void calc_fact(int n) {
  fact[0] = 1;
  for (int i = 1; i <= n; ++i) {
    fact[i] = (fact[i-1]*i)%MOD;
  }
}

void calc_inv_fact(int n) {
  for (int i = 0; i <= n; ++i) {
    inv_fact[i] = mod_inverse(fact[i], MOD);
  }
}


//x^nをmodのもとで計算する
ll mod_pow(ll x, ll n, ll mod) {
  if (n == 0) return 1;
  ll res = mod_pow((x*x) % mod, n/2, mod);
  if (n & 1) res = (res*x) % mod;
  return res;
}

void calc_inv_fact_pow(int n) {
  for (int k = 0; k <= n; ++k) {
    for (int x = 0; x <= n; ++x) {
      inv_fact_pow[k][x] = mod_inverse(mod_pow(fact[k], x, MOD), MOD);
    }
  }
}


