#include<bits/stdc++.h>

const int N = 1010;
const int moder = 1e9 + 7;

int fac[N], inv[N], dp[N][N], n, a, b, c, d;
std::map <std::pair <int, int>, int> Hash;

int power_mod(int a, int index){
	int ret = 1;
	while (index){
		if (index & 1){
			ret = 1ll * ret * a % moder;
		}
		a = 1ll * a * a % moder;
		index >>= 1;
	}
	return ret;
}

int solve(int n, int now){
	if (now == b + 1){
		return !n;
	}
	if (Hash.count({n, now})){
		return Hash[{n, now}];
	}
	int ans = solve(n, now + 1);
	for (int i = c; i <= d; ++ i){
		int x = n - i * now;
		if (x < 0){
			break;
		}
		ans = (ans + 1ll * fac[n] * inv[x] % moder * power_mod(inv[now], i) % moder * inv[i] % moder * solve(x, now + 1)) % moder;
	}
	return Hash[{n, now}] = ans;
}

int main(){
	fac[0] = inv[0] = 1;
	for (int i = 1; i < N; ++ i){
		fac[i] = 1ll * fac[i - 1] * i % moder;
		inv[i] = power_mod(fac[i], moder - 2);
	}
	scanf("%d%d%d%d%d", &n, &a, &b, &c, &d);
	printf("%d\n", solve(n, a));
	return 0;
}

