#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef vector<ll> vll;
typedef vector<int> vi;
const ll MOD=1e9+7;

ll fct[20010];
ll ifct[20010];

ll MULT(int x, int y){
  return (x*y)%MOD;
}

ll POW(int x, int n){
  ll v=1;
  while(n>0){
    if(n%2==1)v=MULT(v, x);
    x=MULT(x,x);
    n/=2;
  }
  return v;
}

ll INV(int x){
  return POW(x, MOD-2);
}

void FCT(){
  fct[0]=1;
  for (int i=0;i<20010;++i) fct[i+1]=MULT(fct[i],i+1);
}

void INV_FCT(){
  ifct[20010-1]=INV(fct[20010-1]);
  for (int i=20010-1;i>=1;--i) ifct[i-1]=ifct[i]*i;
}

ll comb(int n, int k){
  return MULT(fct[n], MULT(ifct[k], ifct[n-k]));
}

int main(){
  int N, A, B, C, D;cin>>N>>A>>B>>C>>D;
  ll dp[1010][1010];memset(dp, 0, sizeof(dp));
  FCT;INV_FCT;

  dp[A-1][0]=1;
  for(ll i=A;i<=B;++i){
      for (int j=0;j<N+1;++j){
          (dp[i][j]+=dp[i-1][j])%=MOD;
          ll f=1;
          if(C!=1){
            for (int k=0;k<C-1;++k) f=MULT(f,comb(j-k*i,i));
          }
          for(ll k=C;k<=D;++k){
              if(j+i*k>N) break;
              f=MULT(f,comb(j+k*i,i));
              (dp[i][j]+=MULT(dp[i-1][j-i*k],MULT(f,ifct[k])))%=MOD;
          }
      }
  }

  cout<<dp[B][N]<<endl;
}

