LL MOD = 1000000007;
LL ncr[1003][1003];
LL ifact[1003];

LL bigmod(LL a, LL n) {
	if (n == 0) return 1;
	LL x = bigmod(a, n / 2);
	x *= x;
	x %= MOD;
	if (n & 1) x = (x * a) % MOD;
	return x;
}

int DP(int n, int sz) {
	if (n == 0) return 1;
	if (sz > b) return 0;
	int &ret = dp[n][sz];

	if (ret != -1) return ret;

	ret = 0;
	ret = DP(n, sz + 1);
	if (sz * c > n) return ret;

	LL now = 1;
	for (int i = 1; i < c; i++) {
		now = (now * ncr[n - sz * (i - 1)][sz]) % MOD;
	}
	for (int i = c; i <= d; i++) {
		if (sz * i > n) break;
		now = (now * ncr[n - sz * (i - 1)][sz]) % MOD;
		LL z = (DP(n - sz * i, sz + 1) * now) % MOD;
		z = (z * ifact[i]) % MOD;
		ret += z;
		ret %= 1000000007;
	}
	return ret;
}

