	int cur = x * y;
	ll res = Comb(m,cur,fact,fact_inv);
	while(cur){
		res = res * Comb(cur,x,fact,fact_inv) % MOD;
		cur -= x;
	}
	return res * fact_inv[y] % MOD;
}

