int dfs(int n, int m) {
	if (n < 0) { return 0; }
	if (n == 0){ return 1; }
	if (dp[n][m] != -1) return dp[n][m];

	int ret = 0;
	for (int x = m; x <= b; x++) {
		if (n < x * c) break;
		for (int y = c; y <= d; y++) {
			if (n < x * y) break;
			//if (n > x * y && n - x * y < (x + 1) * c) break;
			//n人の中から、x人グループをy個作る
			int way = fact[n] * factInv[n - x * y] % mod * powFactInv[x][y] % mod * factInv[y] % mod;
			int res = dfs(n - x * y, x + 1);
			ret += way * res;
			ret %= mod;
		}
	}
	return dp[n][m] = ret;
}

