				ll q = dp[l] * fact[n - l] % mod;
				q = q * recfact[n - j] % mod;
				q = q * mod_pow(recfact[i], k, mod) % mod;
				q = q * recfact[k] % mod;
				dp2[j] = (dp2[j] + q) % mod;
			}
		}
		dp = dp2;
	}
	cout << dp[n] << endl;
	return 0;
}

