int main() {
    GetInv(); GetFactorial();
    int n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;
    memset(dp, 0, sizeof(dp));
    dp[0][a-1] = 1;
    for (int j = a; j <= b; j++) {
        for (int i = 0; i <= n; i++) {
            // dp[i][j]
            long long mul = 1;
            for (int k = 0; k <= n; k++) {
                if (k == 0) {
                    dp[i][j] = (dp[i][j] + dp[i][j-1]) % mod;
                }
                if (k >= c && k <= d) {
                    long long tmp = mul * inv_factorial[k] % mod;
                    dp[i+j*k][j] += tmp * dp[i][j-1] % mod;
                    dp[i+j*k][j] %= mod;
                }
                if (k == d) break;
                if (n-i-j*k < j) break;
                mul = mul * combination(n-i-j*k, j) % mod;
            }
        }
    }
    cout << dp[n][b] << endl;
    return 0;
}

