long long binpow(long long x, long long p) {
  long long res = 1;
  while (p) {
    if (p & 1) {
      res = (res * x) % mod;
      p--;
    } else {
      x = (x * x) % mod;
      p /= 2;
    }
  }
  return res % mod;
}

long long inv(long long x) {
  return binpow(x, mod - 2) % mod;
}

long long getC(int n, int k) {
  long long res = 1ll * f[n] * inv(f[n - k]) % mod;
  res = 1ll * res * inv(f[k]) % mod;
