	cin >> N >> A >> B >> C >> D;
	C_init(N + 50);

	dp[A][N] = 1;

	for(int i = A; i <= B; i++) {
		rep(n, 0, N + 1) {
			if(!dp[i][n]) continue;
			for(int j = C; j <= D; j++) {
				if(n - i * j >= 0) {
					// debug(i, n, j,n - i * j );
					ADD(dp[i + 1][n - i * j], 
							dp[i][n] * C_(n, i * j) % mod * fac[i * j] % mod * invf(mod_pow(fac[i], j)) % mod * fiv[j] % mod);
