  prepare();
  int N,A,B,C,D; cin>>N>>A>>B>>C>>D;
  dp[A][0]=1;
  for(int i=A;i<=B;i++) for(int j=0;j<=N;j++) if(dp[i][j]!=0){
    (dp[i+1][j]+=dp[i][j])%=MOD;
    ll tmp=1LL;
    int num=N-j;
    for(int k=1;j+k*i<=N&&k<=D;k++){
      (tmp*=comb(num,i))%=MOD;
      num-=i;
      if(k>=C) (dp[i+1][j+k*i]+=tmp*dp[i][j]%MOD*ifact[k]%MOD)%=MOD;
    }
  }
  cout<<dp[B+1][N]<<endl;
  return 0;
}

