inline int modpow(int base, int exp, int modulo)
{
  base %= modulo;  int result = 1;
  while (exp > 0LL) {
    if (exp & 1LL) result = (result * base) % modulo;
    base = (base * base) % modulo; exp >>= 1;
  }
  return result % modulo;
}
int grp(int gsz, int ng)
{
    int ret = fact[gsz*ng];
    ret *= ipw[gsz][ng];
    ret %= MOD;
    ret *= ifact[ng];
    return ret % MOD;
}
