//                cout << i - 1 << " " << j - e * i << endl;
                int64_t coef = mul(mul(dp[i - 1][j - e * i], C(j, j - e * i)), cur_pw);
                coef = mul(coef, inv[e]);
                coef = mul(coef, fac[e * i]);
                dp[i][j] = add(dp[i][j], coef);
                cur_pw = mul(cur_pw, inv[i]);
            }
            dp[i][j] = add(dp[i][j], dp[i - 1][j]);
//            cout << i - 1 << " " << j << endl;
//            cout << i << " " << j << " " << dp[i][j] << endl;
        }
    }
    cout << dp[b][n];
}

