    for(int i = 0; i <= 1000; i++){
        pow_x_k_inv[i][0] = 1;
        pow_x_k_inv[0][i] = 1;
    }
    for(int x = 0; x <= 1000; x++){
        for(int k = 1; k <= 1000; k++){
            pow_x_k_inv[x][k] = pow_x_k_inv[x][k-1] * pow_n_inv[x];
            pow_x_k_inv[x][k] %= mod;
        }
    }

}


