ll dfs(ll num, ll g) {
    if (dp[num][g] >= 0) return dp[num][g];
    if (g > B) return 0;

    dp[num][g] = dfs(num, g + 1);
    FOR(i, C, D) {
        if (num >= g * i) {
            ll pat = fact[num] * mypow(invfact[g], i) % MOD * invfact[num - g * i] % MOD * invfact[i] % MOD;
            dp[num][g] += pat * dfs(num - g * i, g + 1) % MOD;
            dp[num][g] %= MOD;
        } else {
            break;
        }
    }

    // cout << mp(num, g) << " : " << dp[num][g] << endl;
