ll ncr(ll N, ll R) {
	if(N < 0 || N < R) return 0;
	if(N == R || R == 0) return 1;
	if(X[N][R]) return X[N][R];
	return X[N][R] = (ncr(N-1, R-1) + ncr(N-1, R)) % MOD;
}

