ll ppow(ll a) {
	ll b=MOD-2;
	ll res = 1;
	while (b) {
		if (b & 1)res = (res*a) % MOD;
		a = (a*a) % MOD;
		b >>= 1;
	}
	return res;
}
ll comb(ll a, ll b) {
	return (((fact[a] * ppow(fact[a - b])) % MOD)*ppow(fact[b])) % MOD;
}
