        val*=finv[N-j*A];
        val%=MOD;
        val*=finv_pow[A][j];
        val%=MOD;
        val*=finv[j];
        val%=MOD;
        dp[A][j*A]+=val;
        dp[A][j*A]%=MOD;
    }
    for(i=A+1; i<=B; i++){
        for(j=A; j<=N; j++){
            dp[i][j]+=dp[i-1][j];
            dp[i][j]%=MOD;
            for(k=C; (k<=D)&&(j-i*k>=0); k++){
                val=dp[i-1][j-i*k];
                val*=fac[N-(j-i*k)];
                val%=MOD;
                val*=finv[N-j];
                val%=MOD;
                val*=finv_pow[i][k];
                val%=MOD;
                val*=finv[k];
                val%=MOD;
                dp[i][j]+=val;
                dp[i][j]%=MOD;
            }
        }
    }

    //output
