ll mod_pow(ll x, ll p, ll M) {
	ll a = 1;
	while (p) {
		if (p % 2)
			a = a*x%M;
		x = x*x%M;
		p /= 2;
	}
	return a;
}

ll mod_inverse(ll a, ll m) {
	return mod_pow(a, m - 2, m);
}

ll calc() {
	ll ret = 1;
	ll n2 = n;
	for (int i = a; i <= b; i++) {
		ll ret2 = 1;
		for (int j = 0; j < f[i]; j++) {
			ret2 = (ret2 * C[n2][i]) % MOD;
			n2 -= i;
		}
		ret2 = (ret2 * mod_inverse(fact[f[i]], MOD)) % MOD;
		ret = (ret*ret2) % MOD;
	}
	return ret;
}

void solve(int now) {
	if (now == b) {
		ll cnt = 0;
		for (int i = a; i < b; i++) {
			cnt += i*f[i];
		}
		if ((n - cnt) % b != 0) {
			return;
		}
		f[b] = (n - cnt) / b;
		if ((f[b] >= c && f[b] <= d) || f[b]==0) {
			ans = (ans + calc()) % MOD;
		}
		return;
	}
	for (int i = 0; i <= d; (i==0)?i=c:i++) {
		f[now] = i;
		solve(now + 1);
	}
}

int main() {
	ll i, j;
	cin >> n >> a >> b >> c >> d;

	C[0][0] = 1;
	for (i = 1; i <= n; i++) {
		for (j = 0; j <= i; j++) {
			if (j == 0 || j == i) {
				C[i][j] = 1;
			}
			else {
				C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
			}
		}
	}
	fact[0] = 1;
	for (i = 1; i <= n; i++) {
		fact[i] = i*fact[i - 1];
	}

	solve(a);
	cout << ans << endl;
}

