typedef long long LL;
LL mod_pow(LL base, LL exp)
{
	if(exp==0) return 1;
	if(exp&1) return (base*mod_pow(base,exp-1))%MOD;
	else return mod_pow((base*base)%MOD,exp/2);
}
LL inv(LL n){ return mod_pow(n,MOD-2); }
LL fac[N+1];
LL fac_inv[N+1];
LL C(LL n, LL k)
{
	if(k < 0 || k > n) return 0;
	LL num = fac[n];
	LL den = (fac_inv[k]*fac_inv[n-k])%MOD;
	return (num*den)%MOD;
}
LL cost[N+1][N+1];
LL memo[N+1][N+1];
LL A, B, D;
LL dp(LL n, LL sz)
{
	if(n==0) return 1;
	if(memo[n][sz]!=-1) return memo[n][sz];
	if(n < 0 || sz > D) return 0;

	LL ans = dp(n,sz+1);
	for(LL count = A; count <= B && sz*count <= n; count++)
		ans += (C(n,sz*count)*cost[count][sz]%MOD)*dp(n-sz*count,sz+1), ans %= MOD;
	return memo[n][sz] = ans;
}
