ll C[MAX][MAX], dstr[MAX][MAX], dp[MAX][MAX];
int main() {
	cin >> n >> a >> b >> c >> d;
	C[1][0] = C[1][1] = 1;
	for(int i = 2; i <= n; i++) {
		C[i][0] = C[i][i] = 1;
		for(int j = 1; j < i; j++) C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
	}
	for(int i = 1; i <= n; i++) {
		dstr[i][1] = 1;
		for(int j = 2; i*j <= n; j++)
			dstr[i][j] = dstr[i][j-1] * C[i*j][i] % MOD * modPow(j, MOD - 2) % MOD;
	}
