using namespace std;

constexpr int mod = 1000000007;

// modをとった和を返す
inline
int modplus(int a, int b){return (a + b) % mod;}

// modをとった差を返す
inline
int modminus(int a, int b){return (mod + a - b) % mod;}

// modをとった積を返す
inline
int multiple(int a, int b){return (static_cast<long long>(a) * b) % mod;}

// 階乗数n!を最初に計算して、呼ばれた時に返す
class Factorial {
    std::vector<int> table;
public:
    Factorial(int max) : table(max) // max:テーブルのサイズ
    {
        table[0] = 1;
        for (int i = 1; i < max; ++i){
            table[i] = multiple(table[i - 1], i + 1);
        }
    }

    int operator () (int n)
    {
        if (n < 0) return 0;
        if (n == 0) return 1;
        return table[n - 1];
    }
};


// 階上数n!の逆数（逆元）を最初に計算して、呼ばれた時に返す
class FactorialInverse {
    std::vector<int> table;
    Factorial& fact;
public:
    FactorialInverse(int max, Factorial fact) : table(max), fact(fact) // max:テーブルのサイズ
    {
        int digit  = 0;
        {
            int temp = mod - 2;
            while (temp > 0){
                temp >>= 1;
                ++digit;
            }
        }
        int origin = fact(max);
        std::vector<int> powerorigin2(digit);
        powerorigin2[0] = origin;
        for (int i = 1; i < digit; ++i){
            powerorigin2[i] = multiple(powerorigin2[i - 1], powerorigin2[i - 1]);
        }
        {
            int table_max = 1;
            int temp = mod - 2;
            for (int i = 0; temp > 0; ++i, temp >>= 1){
                if (!(temp & 1)) continue;
                table_max = multiple(table_max, powerorigin2[i]);
            }
            table[max - 1] = table_max; // origin^(mod - 2)
        }
        for (int i = max - 2; i >= 0; --i){
            table[i] = multiple(table[i + 1], i + 2);
        }
    }

    int operator () (int n)
    {
        if (n < 0) return 0;
        if (n == 0) return 1;
        return table[n - 1];
    }
};

int main()
{
    int N, A, B, C, D;
    scanf("%d %d %d %d %d\n", &N, &A, &B, &C, &D);

    Factorial fact(N);
    FactorialInverse factinv(N, fact);

    int result = 0;
    function<void(int, int, int)> search = [&](int num, int group, int rest){
        // printf("%d %d %d\n", num, group, rest);
        if (rest < 0) return;
        if (rest == 0){
            // printf("%d\n", num);
            result = modplus(result, num);
            return;
        }
        if (group > B) return;
        search(num, group + 1, rest);
        int inv = 1;
        for (int i = 0; i < C; ++i) inv = multiple(inv, factinv(group));
        int restrest = rest - group * C;
        for (int i = C; restrest >= 0 && i <= D; ++i){
            // printf("%d: %d\n", group, i);
            search(multiple(multiple(num, inv), factinv(i)), group + 1, restrest);
            inv = multiple(inv, factinv(group));
            restrest -= group;
        }
    };
    search(fact(N), A, N);
    printf("%d\n", result);
}

