void split(ll n, ll g, ll h)
{
    ll ans = 1;
    ll i = n, j = g;
    for (int i = 0; i < g; i++)
    {
        ans = (ans * cnk[n][h]) % MOD;
        n -= h;
    }
    //cout << i << " " << j << " : " << ans << endl;
    Psplit[i][j] = ans;
    return;
}

signed main()
{
    ios_base::sync_with_stdio(false);
