    for (int i = 1; i <= 1000; i++)
    {
        fact[i] = (fact[i - 1] * i) % MOD;
        rev[i] = inq(fact[i], MOD - 2, MOD);
    }
    cin >> n >> a >> b >> c >> d;
    for (int i = 0; i <= n; i++)
    {
        cnk[i][0] = cnk[i][i] = 1;
    }
    for (int i = 1; i <= n; i++)
        for (int j = 1; j < i; j++)
            cnk[i][j] = (cnk[i - 1][j - 1] + cnk[i - 1][j]) % MOD;
    for (int gs = a; gs <= b; gs++)
