ll quickpow(ll a,ll b)
{
	ll ret=1;
	for(;b;b>>=1,a=a*a%MOD)
		if(b&1) ret=ret*a%MOD;
	return ret;
}
ll P(ll a,ll b)
{return fac[a]*inv[a-b]%MOD;}

int main()
{
	fac[0]=1;
	for(int i=1;i<=MAXN;i++)
		fac[i]=fac[i-1]*i%MOD;
	inv[MAXN]=quickpow(fac[MAXN],MOD-2);
	for(int i=MAXN-1;i>=0;i--)
		inv[i]=inv[i+1]*(i+1)%MOD;

	scanf("%d%d%d%d%d",&n,&A,&B,&C,&D);
	dp[A-1][0]=1;
	for(int i=A;i<=B;i++)
	{
