			dp[i][j]=dp[i-1][j];
		for(int j=0;j<=n;j++)
			for(int k=C,cur=inv[i];j+k*i<=n&&k<=D;k++,cur=cur*inv[i]%MOD)
				if(dp[i-1][j]) (dp[i][j+k*i]+=dp[i-1][j]*P(n-j,k*i)%MOD*cur%MOD*inv[k]%MOD)%=MOD;
	}
	printf("%lld",dp[B][n]);
