	dp[0][0] = 1;

	for(int i=0;i<=N;i++){
		for(int j=0;j<=N;j++){
			dp[i+1][j] = mod(dp[i][j]+dp[i+1][j]);
			if(i>=A&&i<=B){
				int temp = N-j-(C-1)*i;
				int t = 1;
				for(int k=C;k<=D;k++){
					if(temp<i)break;
					t = mod(t * c.combination(temp,i));
					int x = mod(t * c.kaijou_[k-C+1]);
					dp[i+1][j+k*i] = mod(dp[i+1][j+k*i] + mod(x*dp[i][j]));
					temp-=i;
				}
			}
		}
	}

	cout<<dp.back().back()<<endl;

    return 0;
}

