                dp[i+1][j-i*k]=(dp[i+1][j-i*k]+dp[i][j]*fac[j]%MOD*finv[j-i*k]%MOD*powfinv[i][k]%MOD*finv[k]%MOD)%MOD;
            }
        }
    }
    cout << dp[B+1][0] << endl;
}

