Combination comb(2001, MOD);

//i人をj人のグループだけを使って分ける方法の数
ll f(ll i, ll j) {
    ll k = i / j;

    return comb.fact(i) * MODpow(MODpow(comb.fact(j), k), MOD - 2) % MOD * MODpow(comb.fact(k), MOD - 2) % MOD;
}

//i人をj人以下のグループだけを使って場合分けする数
ll solve(ll i, ll j) {
    if (i == 0) {
        return 1;
    }
    if (i < 0) {
        return 0;
    }
    if (j == A - 1) {
        return 0;
    }

    if (memo[i][j] != -1) {
        return memo[i][j];
    }

    //j人ちょうどのグループをk個とする
    ll result = solve(i, j - 1);
    for (ll k = C; k <= D; k++) {
        if (j * k > i) {
            break;
        }

        ll tmp = solve(i - j * k, j - 1);

        //i人からj * k人選ぶ方法
        (tmp *= comb(i, j * k)) %= MOD;

        //j * k人をk個のグループに分ける方法
        (tmp *= f(j * k, j)) %= MOD;

        (result += tmp) %= MOD;
    }

    return memo[i][j] = (result % MOD);
}

