		t-=r;
		tmp=1LL*DP(l,r-1,t)*f%hlq;
		tmp=1LL*tmp*fac[i]%hlq;
		dp[r][res]=(tmp+dp[r][res])%hlq;
	}
	return dp[r][res];
}
