            nck[i][j] = nck[i-1][j-1] + nck[i-1][j];
            nck[i][j] %= MOD;
        }
    }
    cin >> n >> a >> b >> c >> d;
    a--;
    for(int i = 1; i <= b-a; i++)
    {
        for(int j = 1; j <= n; j++)
        {
           // cout << i << " | " << j << endl;
            dp[i][j]=dp[i-1][j];
            for(int k = c; k <= d; k++)
            {
                if(k*(a+i) > j) break;
                int lst = j - (a+i)*k;
                int curr = dp[i-1][lst] * nck[n-lst][(a+i)*k];
                curr %= MOD;
                curr *= grp(a+i, k);
                curr%=MOD;
              //  cout << k << " - " << curr << endl;
                dp[i][j] += curr;
                dp[i][j] %= MOD;
            }
          //  cout << dp[i][j] << " ";
        }
        //cout << endl;
    }
    cout << dp[b-a][n];
}

