                }
                int tmp = factM(n-j+i*k) * comb.t[n-j] % MOD * powM(comb.t[i], k) % MOD * comb.t[k] % MOD;
                dp[i][j] = (dp[i][j] + dp[i-1][j-i*k] * tmp % MOD) % MOD;
            }
        }
    }
    cout << dp[b][n] << endl;

