using namespace std;

const long long MAX = 1001;
const long long MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (long long i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

long long COM(long long n, long long k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long finv_pow[MAX][MAX];
long long dp[MAX][MAX];

int main() {
    COMinit();

    //input
    long long N,A,B,C,D;
    cin >> N >> A >> B >> C >> D;

    //calc
    long long i,j,k,l;
    for(i=1; i<MAX; i++){
        finv_pow[i][1]=finv[i];
    }
    for(i=1; i<MAX; i++){
        for(j=2; j<MAX; j++){
            finv_pow[i][j]=(finv_pow[i][j-1]*finv[i])%MOD;
        }
    }
    for(i=0; i<MAX; i++){
        for(j=0; j<MAX; j++){
            dp[i][j]=0;
        }
    }
    for(i=0; i<MAX; i++){
        dp[i][0]=1;
    }
    long long val;
    for(j=1; j*A<=N; j++){
        val=fac[N];
        val*=finv[N-j*A];
        val%=MOD;
        val*=finv_pow[A][j];
        val%=MOD;
        val*=finv[j];
        val%=MOD;
        dp[A][j*A]+=val;
        dp[A][j*A]%=MOD;
    }
    for(i=A+1; i<=B; i++){
        for(j=A; j<=N; j++){
            dp[i][j]+=dp[i-1][j];
            dp[i][j]%=MOD;
            for(k=C; (k<=D)&&(j-i*k>=0); k++){
                val=dp[i-1][j-i*k];
                val*=fac[N-(j-i*k)];
                val%=MOD;
                val*=finv[N-j];
                val%=MOD;
                val*=finv_pow[i][k];
                val%=MOD;
                val*=finv[k];
                val%=MOD;
                dp[i][j]+=val;
                dp[i][j]%=MOD;
            }
        }
    }

    //output
    cout << dp[B][N] << endl;
    return 0;
}

