// ax + by = gcd(a, b)を満たすx, yを求める。
// 戻り値はgcd(a, b)
ll extGCD(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;  // gcd。普通のユークリッド。
    }
    ll d = extGCD(b, a % b, y, x);
    y -= a/b * x;
    return d;
}

