int N, A, B, C, D;

int64 rec(int sum, int last)
{
  if(sum == N) return (1);
  if(last > B) return (0);

  int ret = rec(sum, last + 1);
  for(int i = C; i <= D; i++) {
    if(sum + i * last > N) continue;

    int64 people = fact[i * last];
    for(int j = 0; j < i; j++) (people *= rfact[j]) %= mod;
    (people *= rfact[last]) %= mod;

    (ret += rec(sum + i * last, last + 1) * people) %= mod;
  }
  return (ret);
}

