  }
  for (int i = 0; i <= n; i++) {
    finv[i][0] = 1;
    finv[i][1] = inv(f[i]);
    for (int j = 2; j <= n; j++) {
      finv[i][j] = mul(finv[i][j - 1], finv[i][1]);
    }
  }
  memset(dp, 0, sizeof(dp));
  dp[n][n] = 1;
  for (int i = n; i > 0; i--) {
