ll extgcd(ll a, ll b, ll& x, ll& y) {
  ll d = a;
  if (b != 0) {
    d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  } else {
    x = 1; y = 0;
  }
  return d;
}

ll inv(ll a, ll m) {
  ll x, y;
  extgcd(a, m, x, y);
  return (m + x) % m;
}


int N, A, B, C, D;
ll fac[MAX_N + 1];
ll inv_fac[MAX_N + 1];
ll dp[MAX_N + 1][MAX_N + 1];
ll ans;

int main() {

  int max_k;
  ll tmp, inv_fac_i_pow_k;

  scanf("%d%d%d%d%d", &N, &A, &B, &C, &D);

  fac[0] = 1;
  inv_fac[0] = inv(fac[0], MOD);
  for (int i = 1; i <= N; i++) {
    fac[i] = fac[i - 1] * i;
    fac[i] %= MOD;
    inv_fac[i] = inv(fac[i], MOD);
  }

  memset(dp, 0, sizeof(dp));
  dp[0][0] = 1;
  for (int i = 1; i <= N; i++) {
