const int SET_FACT_MAX = 1010;
mint fact[SET_FACT_MAX];
mint revFact[SET_FACT_MAX];

void setFact() {
	const int N = SET_FACT_MAX;
	fact[0] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = fact[i - 1] * i;
	}
	revFact[N - 1] = fact[N - 1] ^ (mod - 2);
	for (int i = N - 2; i >= 0; i--) {
		revFact[i] = revFact[i + 1] * (i + 1);
	}
}

mint nPr(int n, int r) { return n >= r ? fact[n] * revFact[n - r] : 0; }
mint nCr(int n, int r) { return nPr(n, r) * revFact[r]; }

mint naive(int n, int a, int b, int c, int d) {
	vvm dp(b+1, vm(n+1));
	dp[a-1][0] = 1;
	vm inv(d+1);
	rep(i, 1, d) inv[i] = mint(i).inv();
	rep(i, a, b+1) {
		rep(j, n+1) {
			if (dp[i-1][j].x == 0) continue;
			dp[i][j] += dp[i-1][j];
			mint cnt = dp[i-1][j];
			rep(k, c, d+1) {
				if (j + k*i > n) break;
				cnt *= nCr(n-j-(k-1)*i, i);
				cnt *= inv[k];
				dp[i][j+k*i] += cnt;
			}
		}
	}
	mint ans = dp[b][n];
	return ans;
}

mint solve() {
	setFact();
	int n = ri(), a = ri(), b = ri(), c = ri(), d = ri();
	out(n,a,b,c,d);

	mint nai = naive(n,a,b,c,d);
	out(nai);
	return nai;
}

void Main() {
	cout << solve() << endl;
}
