				for (int x = C; j * x <= i && x <= D; ++x) {
					dp[i][j] += choose(i, j*x) * fact[j*x] % MOD * precomp[j][x] % MOD * dp[i-j*x][j-1];
					dp[i][j] %= MOD;
				}
			}
		}
	}
