				continue;
			//k==0のとき、func()==1;
			//j==0のときは足さない（1なので）
			if(j!=0){
				DP[i+1][j]+=DP[i][j];
				DP[i+1][j]%=MOD;
			}
			//Fをつくる
			ll F=1;
			//(N-j)Ci*(N-j-i)Ci*...*(N-j-(C-1)i)Ci
			for(int k=0;k<C;k++){
				if(N-j-k*i>=0)
