				F%=MOD;
				F*=gyaku[k+1];
				F%=MOD;
			}
			for(int k=1;k<=D;k++){
				//N以上に遷移する必要はない
				if(j+i*k>N)
					break;
				if(C<=k){
					DP[i+1][j+i*k]+=DP[i][j]*F%MOD;
					DP[i+1][j+i*k]%=MOD;
					F*=comb[N-j-k*i][i];
					F%=MOD;
					F*=gyaku[k+1];
					F%=MOD;
				}
			}
		}
	}
	cout<<DP[B+1][N]<<endl;
	return 0;
}

