    vector<vi> dp(N + 1, vi(N + 1, 0));
    dp[A - 1][0] = 1;
    REPF(i, A, B + 1) {
        REP(j, N + 1) {
            (dp[i][j] += dp[i - 1][j]) %= MOD;  // i人グループは作らない
            REPF(k, C, D + 1) {
                if (j < i * k) break;
                int p = fact[N - (j - i * k)] * fact_inv[N - j] % MOD;
                (dp[i][j] += 
                    dp[i - 1][j - i * k] * p % MOD * bin_pow_mod(bin_pow_mod(fact[i], k), MOD - 2) % MOD * fact_inv[k] % MOD)
                    %= MOD;  // i人グループをj個作る
            }
        }
    }
    cout << dp[B][N] << endl;
    return (0^_^0);
}

