        rep2(j,1,n+1){
            if(j<a) continue;
            rep(k,j/i+1){
                if(d<k) break;
                if((c<=k&k<=d)&(a<=i&i<=b)){
                    ll tmp=fact1[i][k]*fact2[k]%mod;
                    dp[i][j]+=comb[n-j+i*k][i*k]*fact[i*k]%mod*tmp%mod*dp[i-1][j-i*k]%mod;
                    dp[i][j]%=mod;
                }
                else if(k==0){
                    dp[i][j]+=dp[i-1][j];
                    dp[i][j]%=mod;
                }
            }
        }
    }
    printf("%lld\n", dp[n][n]);
}

