		fact[i] = (fact[i - 1] * i) % mod;
		powrev[i] = getpow(i, mod - 2);
		for(int j = 0; j <= i; j++){
			comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % mod;
		}
	}
	cout << solve(n, b) << endl;
}

