    for (int i = c; i <= d; i++) {
        ds.push_back(i);
    }
    for (int i = a; i <= b; i++) {
        for (int j = 0; j <= n; j++) {
            for (int k : ds) {
                if (j - k * i < 0) break;
                dp[i + 1][j - k * i] += dp[i][j] * choose(j, k * i) * arrange(k, i);
            }
        }
    }
    cout << dp[b + 1][0] << endl;
}

