class Combination {
    int powmod(int a, int p) {
        int ans = 1;
        int mul = a;

        for (; p > 0; p >>= 1, mul = (mul * mul) % mod) {
            if ((p & 1) == 1) ans = (ans * mul) % mod;
        }

        return ans;
    }
public:
    int N;
    int mod;
    vector<int> fact;
    vector<int> revFact;

    Combination(int n, int m) : N(n), mod(m), fact(n+1), revFact(n+1) {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i-1] * i;
            fact[i] %= mod;
        }

        // Fermat's little theorem
        revFact[N] = powmod(fact[N], mod - 2);

        for (int i = N-1; i >= 0; i--) {
            revFact[i] = revFact[i+1] * (i+1);
            revFact[i] %= mod;
        }
    }

    int get(int a, int b) {
        if (a < 0 || b < 0) return 0;
        if (b > a) return 0;
        return (((fact[a] * revFact[b]) % mod) * revFact[a-b]) % mod;
    }
};

int powmod(int a, int p, int mod) {
    int ans = 1;
    int mul = a;

    for (; p > 0; p >>= 1, mul = (mul * mul) % mod) {
        if ((p & 1) == 1) ans = (ans * mul) % mod;
    }

    return ans;
}

signed main() {
    int N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;
    int K = B - A + 1;

    int fact[N+1];
    fact[0] = 1;
    for (int i = 1; i <= N; i++) {
        fact[i] = i * fact[i-1];
        fact[i] %= MOD;
    }

    Combination comb = Combination(N, MOD);

    int dp[K+1][N+1];
    fill(dp[0], dp[K+1], 0);
    dp[0][0] = 1;

    for (int i = 0; i < K; i++) {
        int human_n = i + A;

        for (int j = 0; j <= N; j++) {
            dp[i+1][j] = dp[i][j];
            for (int group_num = C; group_num <= D; group_num++) {
                if (j - human_n * group_num < 0) break;
                int added = 0;
                added += dp[i][j - human_n * group_num];
                added %= MOD;

                added *= comb.get(j, human_n * group_num);
                added %= MOD;

                int remain = human_n * group_num;
                while (remain > 0) {
                    added *= comb.get(remain, remain - human_n);
                    added %= MOD;
                    remain -= human_n;
                }

                // 同じ人数同士の区別をなくす
                added = (added * powmod(fact[group_num], MOD - 2, MOD)) % MOD;

                dp[i+1][j] += added;
                dp[i+1][j] %= MOD;
            }
        }
    }

    cout << dp[K][N] << endl;

    return 0;
}

