            cnt[x] = cnt[x - 1] * mod_comb(n - k * (x - 1), k) / x;

        for (int x = 0; x * k <= n; x++) 
            if (x == 0 || (a <= k && k <= b && c <= x && x <= d)) 
                dp[k][n] += cnt[x] * dp[k - 1][n - x * k];
    }
    cout << dp[N][N]<< endl;
