ll modFactInv[MX+1];
void precalc() {
  modFact[0]=1;
  modFactInv[0]=1;
  repeat(i,1,MX+1) {
    modFact[i]=(modFact[i-1]*i)%p;
    modFactInv[i]=modinv(modFact[i],p);
  }
}

ll fastModComb(ll n, ll k, ll p) {
  // call precalc() first.
  ll ret=modFact[n];
  ret=ret*modFactInv[n-k];
  ret%=p;
  ret=ret*modFactInv[k];
  ret%=p;
  return ret;
}

ll f(ll j, ll i, ll k) {
  ll ret=modFact[j];
  ret*=modFactInv[j-i*k];
  ret%=p;
  ret*=modinv(modpow(modFact[i],k,p),p);
  ret%=p;
  ret*=modinv(modFact[k],p);
  ret%=p;
  return ret;
}

ll dp(ll i, ll j) {
