LL f(int n,int k,int x){//n人からk人グループをx個作る
	if( x == 0 ){
		return 1;
	}
	if( x < C || D < x){
		return 0;
	}
	if( n < k*x ){
		return 0;
	}
	LL ret=1;
	ret = (fact[n]*factInv[n-x*k]) % MOD;
	ret = (ret * factInv[x] ) % MOD;
	ret = (ret * powMod(factInv[k],x) ) % MOD;
	return ret;
}
LL dfs(int k,int n){//n人をk人以下のグループに分ける
	/*
	分ける、分けるがここでは
	k人のグループにしか分けない。
	k-1人以降はdfs(k-1,n-?)に任せる
	*/
	if( n == 0 ){
		return 1;//
	}
	if( k < A || n < A){//グループ人数の制約
		return 0;
	}

	if( k == 1 ){//一人のグループは1通り
		//nグループ作られる
		if( C <= n && n <= D ){
			return 1;
		}
		return 0;
	}
	if( dp[k][n] ){
		return dp[k][n];
	}
	LL ans = 0;
	int num = n;
	int K = k;

	int Xmax = min(n/k, D);//作れるグループ数の制限
	for(int x=C;x<=Xmax;++x)
	{
		if( n-K*x < 0 ) break;
		if( K*x > n ) break;
		LL res1,res2;
		res1 = 1;
		res2 = 1;
		if( n-K*x == 0 ){
			res2 = 1;
		}else if( n-K*x < A ){
			res2 = 0;
			continue;
		}else if( n-K*x > 0 ){
			res2 = dfs(K-1,n-K*x);
		}
		if( res2 > 0 ){
			res1 = f(n,K,x);
		}
		ans = (ans + (res1*res2)%MOD )%MOD;
	}
	//1グループも作らない
	ans = (ans + dfs(K-1,n) ) % MOD;

	dp[k][n] = ans;
	return ans;
}
