        finv_pow[i][1]=finv[i];
    }
    for(i=1; i<MAX; i++){
        for(j=2; j<MAX; j++){
            finv_pow[i][j]=(finv_pow[i][j-1]*finv[i])%MOD;
        }
    }
    for(i=0; i<MAX; i++){
        for(j=0; j<MAX; j++){
