    for (ll i = 2; i <= n; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        invfac[i] = invfac[i - 1] * modpow(i, MOD - 2) % MOD;
    }

    // dp[i][j]: i 人以下のグループだけで j 人使う時の分け方
    vvll dp(b + 1, vll(n + 1, 0));
    dp[0][0] = 1;
    // i 人グループを g 個追加
    // 遷移: dp[i][j + i * g] = dp[i - 1][j] * {n-j}_C_{i * g} * (i * g)! / (i!) ^ g / g!
    for (ll i = 1; i <= b; i++) {
