            (dp[i][j] += dp[i - 1][j]) %= MOD;
            for (ll g = c; g <= d; g++) {
                if (j + i * g > n) break;
                ll tmp = dp[i - 1][j] * (fac[n - j] * (invfac[i * g] * invfac[n - j - i * g] % MOD) % MOD) % MOD;
                (tmp *= fac[i * g]) %= MOD;
                (tmp *= modpow(modpow(fac[i], g), MOD - 2)) %= MOD;
                (tmp *= invfac[g]) %= MOD;
                (dp[i][j + i * g] += tmp) %= MOD;
            }
        }
    }
    // for (ll i = 0; i <= b; i++) DEBUG_VLL(dp[i])
    cout << dp[b][n] << '\n';
    return 0;
}

