// Fermatの小定理による逆元計算
// a^n modを計算する
long long modpow(long long a, long long n, long long mod)
{
    long long res = 1;
    while (n > 0)
    {
        if (n & 1)
            res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

// a^{-1}を計算する
long long modinv(long long a, long long mod)
{
    return modpow(a, mod - 2, mod);
}

// 二項係数nCr
const int MAX = 510000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit()
{
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k)
{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;

    COMinit();
    vector<vector<ll>> dp(N + 10, vector<ll>(N + 10));
    dp[A - 1][0] = 1;

    for (int i = A; i <= B; i++)
    {
        for (int j = 0; j <= N; j++)
        {
            // i人グループが0個
            dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD;
            int n = N - j;
            for (int k = C; k <= D && i * k <= N; k++)
            {
                ll numer = COM(n, i * k);
                numer = (numer * fac[i * k]) % MOD;
                ll denom = fac[i];
                denom = modpow(denom, k, MOD);
                denom = (denom * fac[k]) % MOD;
                ll res = numer * modinv(denom, MOD);
                dp[i][j + i * k] = (dp[i][j + i * k] + dp[i - 1][j] * res % MOD) % MOD;
            }
        }
    }
    cout << dp[B][N] << endl;
    return 0;
}

