llong binpow(llong a, int b)
{
	llong res = 1ll;

	for (; b > 0; b >>= 1, a = a * a % inf)
		if (b & 1) res = res * a % inf;

	return res;
}

void solve()
{
	binomial[0][0] = 1;

	for (int i = 1; i <= n; ++i)
	{
		binomial[i][0] = 1;

		for (int j = 1; j <= i; ++j)
		{
			binomial[i][j] = binomial[i - 1][j - 1] + binomial[i - 1][j];

			if (binomial[i][j] >= inf)
				binomial[i][j] -= inf;
		}
	}

	llong f = 1;
	R[0] = binpow(f, inf - 2);

	forn (i, n)
	{
		f *= i + 1;
		f %= inf;
		R[i + 1] = binpow(f, inf - 2);
	}

	forn (i, n + 1)
		dp[0][i] = 1ll;

	for (int i = 1; i <= n; ++i)
	{
		for (int len = a; len <= b; ++len)
		{
			int nn = n - i;
			llong cur = 1ll;

			for (int cnt = 1; cnt < c && nn + len <= n; ++cnt, nn += len)
			{
				cur *= binomial[nn + len][len];
				cur %= inf;
			}

			for (int cnt = c; cnt <= d && i - len * cnt >= 0; ++cnt, nn += len)
			{
				cur *= binomial[nn + len][len];
				cur %= inf;
				dp[i][len] += (cur * dp[i - len * cnt][len - 1] % inf) * R[cnt];
				dp[i][len] %= inf;
			}
		}

		for (int j = 1; j <= n; ++j)
		{
			dp[i][j] += dp[i][j - 1];

			if (dp[i][j] >= inf)
				dp[i][j] -= inf;
		}
	}

	printf("%lld\n", dp[n][n]);
}

