int *dp=NULL;

int calc(int x,int y){
  if(x==0) return 1;
  if(y<a) return 0;
  if(dp[POS(x,y)]>=0) return dp[POS(x,y)];
  int local=calc(x,y-1);
  int k;
  for(k=c;k<=d && k<=x/y;k++){
    int way=(int64)comb(x,k*y)*fact[k*y]%mod*modPow(iFact[y],k)%mod*iFact[k]%mod;
    local=(local+(int64)way*calc(x-k*y,y-1))%mod;
  }
  dp[POS(x,y)]=local;
  return local;
}

