public class Main {
  public static long MOD = (long)Math.pow(10, 9) + 7;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int a = sc.nextInt();
    int b = sc.nextInt();
    int c = sc.nextInt();
    int d = sc.nextInt();
    long[][] dp = new long[b - a + 1][n + 1];
    long[] kai = new long[n + 1];
    kai[0] = 1;
    for(int i = 1; i <= n; i++) {
      kai[i] = (kai[i - 1] * (long)i) % MOD;
    }
    dp[0][0] = 1;
    for(int j = c; j <= Math.min(d, (n / a)); j++) {
      int t = a * j;
      dp[0][t] = (kai[n] * func(kai[n - t], MOD - 2)) % MOD;
    //  dp[0][t] = (dp[0][t] * func(n - t, MOD - 2)) % MOD;
      dp[0][t] = (dp[0][t] * func(kai[a], (long)j * (MOD - 2))) % MOD;
      dp[0][t] = (dp[0][t] * func(kai[j], MOD - 2)) % MOD;  
    }
    /**
    long[] inv = new long[n + 1];
    for(int i = 0; i <= n; i++) {
      inv[i] = func(kai[i], MOD - 2);
    } */
    long[][] inv = new long[n + 1][d + 1];
    for(int i = 0; i <= n; i++) {
      for(int j = 0; j <= d; j++) {
        inv[i][j] = func(kai[i], (long)j * (MOD - 2));
      }
    }
    for(int i = 1; i < (b - a + 1); i++) {
      dp[i][0] = 1;
      for(int j = 1; j <= n; j++) {
        dp[i][j] = dp[i - 1][j];
        for(int k = c; k <= Math.min(d, j / (i + a)); k++) {
          int s = (i + a) * k;
          long t = (dp[i - 1][j - s] * kai[n - j + s]) % MOD;
          t = (t * inv[n - j][1]) % MOD;
          t = (t * inv[i + a][k]) % MOD;
          t = (t * inv[k][1]) % MOD;
          /**
          t = (t * func(kai[n - j], MOD - 2)) % MOD;
          t = (t * func(kai[i + a], (long)k * (MOD - 2))) % MOD;
          t = (t * func(kai[k], MOD - 2)) % MOD;
          */
          dp[i][j] = (dp[i][j] + t) % MOD;
        }
      }
    } 
    System.out.println(dp[b - a][n]);
  }

  public static long func(long a, long x) {
    if(x == 0) return 1;
    if((x % 2) == 0) {
      long t = func(a, x / 2);
      return (t * t) % MOD;
    } else {
      long t = func(a, x - 1);
      return (a * t) % MOD;
    }
  }
}

import java.io.*;
import java.util.*;

class Solver {
  final int n, a, b, c, d;
  final ModCalculator mc;
  final ModCombinationCache mcc;
  long[][] dpcache;

  Solver(int n, int a, int b, int c, int d) {
    this.n = n;
    this.a = a;
    this.b = b;
    this.c = c;
    this.d = d;
    this.mc = new ModCalculator(1_000_000_007L);
    this.mcc = new ModCombinationCache(this.mc);
  }

  private long solve(int restGroupNumber, int restCount) {
    if (restGroupNumber > b) {
      if (restCount == 0) {
        return 1;
      } else {
        return 0;
      }
    }

    if (dpcache[restGroupNumber][restCount] >= 0) {
      return dpcache[restGroupNumber][restCount];
    }
    dpcache[restGroupNumber][restCount] = solve(restGroupNumber + 1, restCount);
    for (int groupCount = c; groupCount <= d; groupCount++) {
      if (restGroupNumber * groupCount > restCount) {
        break;
      }
      long solution = solve(restGroupNumber + 1, restCount - restGroupNumber * groupCount);
      if (solution == 0) {
        continue;
      }
      for (int i = 0; i < groupCount; i++) {
        solution = mc.mul(solution, mcc.getC(restCount - restGroupNumber * i, restGroupNumber));
      }
      solution = mc.div(solution, mcc.getP(groupCount));

      dpcache[restGroupNumber][restCount] = mc.add(dpcache[restGroupNumber][restCount], solution);
    }

//    System.err.printf("%d %d %d\n", restGroupNumber, restCount, dpcache[restGroupNumber][restCount]);
    return dpcache[restGroupNumber][restCount];
  }

  public long solve() {
    dpcache = new long[b + 1][n + 1];
    for (long[] array : dpcache) {
      Arrays.fill(array, -1);
    }
    return solve(a, n);
  }
}

