		int n = in.nextInt();
		int a = in.nextInt();
		int b = in.nextInt();
		int c = in.nextInt();
		int d = in.nextInt();
		long[][] comb = pascalT(2000);
		long[] dp = new long[n+1];
		dp[n] = 1;
		for(int i=0; i<=b-a; i++){
			final int p = i+a;
			for(int j=p; j<=n; j++){
				if(dp[j]==0) continue;
				final int max = Math.min(j/p, d);
				if(max==0 || p*c>j) continue;
				int r = j;
				long s = 1;
				for(int k=1; k<c; k++){
					s = s*comb[r][p]%mod*modinv(k, mod)%mod;
					r -= p;
				}
				for(int k=c; k<=max; k++){
					s = s*comb[r][p]%mod*modinv(k, mod)%mod;
					r -= p;
					dp[j-k*p] = (dp[j-k*p]+dp[j]*s)%mod;
				}
			}
		}
		System.out.println(dp[0]);
	}

	long modinv(long n, long mod){
		return modpow(n, mod-2, mod);
	}

	long modpow(long n, long a, long mod){
		long res = 1;
		while(a > 0){
			if((a&1)==1) res = res*n%mod;
			n = n*n%mod;
			a >>= 1;
		}
		return res;
	}

	final long mod = 1000000007;
	long[][] pascalT(int n){
		long[][] tri = new long[n][];
		for(int i=0; i<n; i++){
			tri[i] = new long[i+1];
			for(int j=0; j<i+1; j++){
				if(j == 0 || j == i){
					tri[i][j] = 1;
				}else{
					tri[i][j] = (tri[i-1][j-1] + tri[i-1][j])%mod;
				}
			}
		}
		return tri;
	}
}

