import java.util.Scanner;

public class Main {
	static int N;
	static int A;
	static int B;
	static int C;
	static int D;
	static long ans = 0L;
	static long MOD = 1000000007L;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		A = sc.nextInt();
		B = sc.nextInt();
		C = sc.nextInt();
		D = sc.nextInt();

		sc.close();

		int[] grp = new int[N + 1];
		ans = 0L;
		rec(grp, N, A);

		System.out.println(ans);
	}

	private static void rec(int[] grp, int rest, int cur) {
		if (cur > B || rest < cur) {
			return;
		}
		int max = Math.min(rest, D * cur);
		grp[cur] = 0;
		rec(grp, rest, cur + 1);
		for (int i = C * cur; i <= max; i += cur) {
			if (rest - i == 0) {
				grp[cur] = i / cur;
				// 計算
				long tmp = 1L;
				long div = 1L;
				long num = N;
				int j = A;
				while (j <= B) {
					if (grp[j] != 0) {
						for (int k = 0; k < grp[j]; k++) {
							tmp = (tmp * comb(num, j)) % MOD;
							num = num - j;
						}
						div = (div * fact(1, grp[j])) % MOD;
					}
					j++;
				}
				tmp = (tmp * pow(div, MOD - 2)) % MOD;
				ans = (ans + tmp) % MOD;
			} else if (rest - i < cur + 1) {
				break;
			} else {
				grp[cur] = i / cur;
				rec(grp, rest - i, cur + 1);
			}
		}
		grp[cur] = 0;
	}

	private static long comb(long n, long r) {
		r = Math.max(r, n - r);
		long ret = fact(r + 1, n);
		ret = (ret * pow(fact(1, n - r), MOD - 2)) % MOD;
		return ret;
	}

	private static long fact(long min, long max) {
		long i = min;
		long ret = 1L;
		while (i <= max) {
			ret = (ret * i) % MOD;
			i++;
		}
		return ret;
	}

	private static long pow(long a, long b) {
		long ret = 1L;
		long x = a;
		while (b > 0) {
			if ((b & 1L) == 1L) {
				ret = (ret * x) % MOD;
			}
			x = (x * x) % MOD;
			b >>= 1;
		}
		return ret;
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        long MOD = TypicalMods.MOD1000000007;
        ModArithmetic ma = new ModArithmetic(MOD);
        int n = sc.nextInt();
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        long[] iv = ma.invMemo(n);
        long[][] cm = new long[n + 1][n + 1];
        cm[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            cm[i][0] = cm[i][i] = 1;
            for (int j = 1; j < i; j++) {
                cm[i][j] = cm[i - 1][j - 1] + cm[i - 1][j];
                if (cm[i][j] >= MOD) cm[i][j] -= MOD;
            }
        }
        long[][] fp = new long[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            fp[i][0] = 1;
            for (int j = 1; j * i <= n; j++) {
                long ml = ma.mul(cm[i * j][i], iv[j]);
                fp[i][j] = ma.mul(fp[i][j - 1], ml);
            }
        }
        long[][] dp = new long[n + 1][n + 1];
        dp[a][0] = 1;
        for (int k = c; k * a <= n && k <= d; k++) {
            dp[a][k * a] = ma.mul(cm[n][k * a], fp[a][k]);
        }
        for (int i = a; i < b; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i + 1][j] += dp[i][j];
                if (dp[i + 1][j] >= MOD) dp[i + 1][j] -= MOD;
                for (int k = c; j + k * (i + 1) <= n && k <= d; k++) {
                    int nj = j + k * (i + 1);
                    long ml = ma.mul(cm[n - j][k * (i + 1)], fp[i + 1][k]);
                    dp[i + 1][nj] += ma.mul(ml, dp[i][j]);
                    if (dp[i + 1][nj] >= MOD) dp[i + 1][nj] -= MOD;
                }
            }
        }
        out.writeln(dp[b][n]);
    }
}


/**
 * @author https://atcoder.jp/users/suisen
 */
class BasicScanner {
    private final InputStream in;
    private final byte[] buf = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public BasicScanner(InputStream in) {this.in = in;}
    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {buflen = in.read(buf);}
        catch (final IOException e) {e.printStackTrace();}
        return buflen > 0;
    }
    private int readByte() {return hasNextByte() ? buf[ptr++] : -1;}
    public boolean hasNext() {
        while (hasNextByte() && !(33 <= buf[ptr] && buf[ptr] <= 126)) ptr++;
        return hasNextByte();
    }
    private StringBuilder nextSequence() {
        if (!hasNext()) throw new NoSuchElementException();
        final StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (33 <= b && b <= 126) {sb.appendCodePoint(b); b = readByte();}
        return sb;
    }
    public char nextChar() {
        return (char) readByte();
    }
    public String next() {
        return nextSequence().toString();
    }
    public String next(int len) {
        return new String(nextChars(len));
    }
    public char[] nextChars() {
        final StringBuilder sb = nextSequence();
        int l = sb.length();
        char[] dst = new char[l];
        sb.getChars(0, l, dst, 0);
        return dst;
    }
    public char[] nextChars(int len) {
        if (!hasNext()) throw new NoSuchElementException();
        char[] s = new char[len];
        int i = 0;
        int b = readByte();
        while (33 <= b && b <= 126 && i < len) {s[i++] = (char) b; b = readByte();}
        if (i != len) throw new NoSuchElementException(String.format("length %d is longer than the sequence.", len));
        return s;
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {minus = true; b = readByte();}
        if (b < '0' || '9' < b) throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') n = n * 10 + b - '0';
            else if (b == -1 || !(33 <= b && b <= 126)) return minus ? -n : n;
            else throw new NumberFormatException();
            b = readByte();
        }
    }
    public int nextInt() {return Math.toIntExact(nextLong());}
    public double nextDouble() {return Double.parseDouble(next());}
}


/**
 * @author https://atcoder.jp/users/suisen
 */
class Out {
    private final OutputStream out;
    private byte[] buf = new byte[1024];
    private int ptr = 0;
    private static final int AUTO_FLUSH_THRETHOLD = 1 << 17;

    public Out(OutputStream out) {
        this.out = out;
    }

    public void flush() {
        try {
            out.write(buf, 0, ptr);
            out.flush();
            ptr = 0;
        } catch (IOException e) {e.printStackTrace();}
    }

    public void close() {
        try {out.close();} catch (IOException e) {e.printStackTrace();}
    }

    public Out writeln() {return write('\n');}
    public Out writeln(Object o) {return write(o).write('\n');}
    public Out writeln(String s) {return write(s).write('\n');}
    public Out writeln(char[] c) {return write(c).write('\n');}
    public Out writeln(char   c) {return write(c).write('\n');}
    public Out writeln(byte   b) {return write(b).write('\n');}
    public Out writeln(int    x) {return write(x).write('\n');}
    public Out writeln(long   x) {return write(x).write('\n');}
    public Out writeln(double d) {return write(d).write('\n');}

    public Out writeSpace() {return write(' ');}

    public Out write(Object o) {
        return write(o.toString());
    }

    public Out write(String s) {
        try {
            Field strValueField = s.getClass().getDeclaredField("value");
            strValueField.setAccessible(true);
            byte[] b = (byte[]) strValueField.get(s);
            int l = s.length();
            if (l > AUTO_FLUSH_THRETHOLD) {
                flush();
                int i = 0;
                while (i + AUTO_FLUSH_THRETHOLD < l) {
                    out.write(b, i, AUTO_FLUSH_THRETHOLD);
                    out.flush();
                    i += AUTO_FLUSH_THRETHOLD;
                }
                ensureCapacity(l - i);
                System.arraycopy(b, i, buf, 0, l - i);
                ptr = l - i;
            } else {
                ensureCapacity(ptr + l);
                System.arraycopy(b, 0, buf, ptr, l);
                ptr += l;
            }
        } catch (Exception e) {e.printStackTrace();}
        return this;
    }

    public Out write(char[] c) {
        int l = c.length;
        if (l > AUTO_FLUSH_THRETHOLD) {
            flush();
            ensureCapacity(AUTO_FLUSH_THRETHOLD);
            int i = 0;
            while (i + AUTO_FLUSH_THRETHOLD < l) {
                for (int j = 0; j < AUTO_FLUSH_THRETHOLD; j++) {
                    buf[ptr++] = (byte) c[i + j];
                }
                flush();
                i += AUTO_FLUSH_THRETHOLD;
            }
            for (; i < l; i++) {
                buf[ptr++] = (byte) c[i];
            }
        } else {
            ensureCapacity(ptr + l);
            for (char ch : c) buf[ptr++] = (byte) ch;
        }
        return this;
    }

    public Out write(char c) {
        ensureCapacity(ptr + 1);
        buf[ptr++] = (byte) c;
        return this;
    }

    public Out write(byte b) {
        ensureCapacity(ptr + 1);
        buf[ptr++] = b;
        return this;
    }

    public Out write(int x) {
        if (x == 0) {
            ensureCapacity(ptr + 1);
            buf[ptr++] = '0';
            return this;
        }
        int d = stringSize(x);
        ensureCapacity(ptr + d);
        if (x < 0) {
            buf[ptr++] = '-';
            x = -x;
            d--;
        }
        int j = ptr + d; 
        while (x > 0) {
            buf[--j] = (byte) ('0' + (x % 10));
            x /= 10;
        }
        ptr += d;
        return this;
    }

    public Out write(long x) {
        if (x == 0) {
            ensureCapacity(ptr + 1);
            buf[ptr++] = '0';
            return this;
        }
        int d = stringSize(x);
        ensureCapacity(ptr + d);
        if (x < 0) {
            buf[ptr++] = '-';
            x = -x;
            d--;
        }
        int j = ptr + d; 
        while (x > 0) {
            buf[--j] = (byte) ('0' + (x % 10));
            x /= 10;
        }
        ptr += d;
        return this;
    }

    public Out write(double d) {
        return write(Double.toString(d));
    }

    private void ensureCapacity(int cap) {
        if (cap > AUTO_FLUSH_THRETHOLD) {
            flush();
        }
        if (cap >= buf.length) {
            int newLength = buf.length;
            while (newLength < cap) newLength <<= 1;
            byte[] newBuf = new byte[newLength];
            System.arraycopy(buf, 0, newBuf, 0, buf.length);
            buf = newBuf;
        }
    }
    private static int stringSize(long x) {
        int d = 1;
        if (x >= 0) {d = 0; x = -x;}
        long p = -10;
        for (int i = 1; i < 19; i++, p *= 10) if (x > p) return i + d;
        return 19 + d;
    }
    private static int stringSize(int x) {
        int d = 1;
        if (x >= 0) {d = 0; x = -x;}
        int p = -10;
        for (int i = 1; i < 10; i++, p *= 10) if (x > p) return i + d;
        return 10 + d;
    }
}


