        dp[i][k] = dp[i - 1][k];

        long y = pow(fif[1][i], c, mod);
        for (int j = c; k + i * j <= n && j <= d; j++) {
          long x = dp[i - 1][k + i * j] * C(k + i * j, i * j, mod, fif) % mod;
          x *= fif[0][i * j];
          x %= mod;
          x *= y;
          x %= mod;
          x *= fif[1][j];
          x %= mod;

          dp[i][k] += x;
          dp[i][k] %= mod;

          y *= fif[1][i];
          y %= mod;
        }
      }
    }

