			for (int i = 0; i < comb.length; i++) {
				fact[i] = i == 0 ? 1 : fact[i-1] * i % mod;
				comb[i][0] = comb[i][i] = 1;
				for (int j = 1; j < i; j++) {
					comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
