	int A, B, C, D;
	long[] fact = new long[1001];
	long[][] comb = new long[1001][1001];
	long[][] memo2 = new long[1001][1001];
	long[][] memo = new long[1001][1001];
	long rec(int n, int m) {
		if (n < 0) return 0;
		if (m == A - 1) return n == 0 ? 1 : 0;
		if (memo[n][m] != -1) return memo[n][m];
		long ans = rec(n, m - 1);
		for (int i = C; i <= D; i++) if (m*i <= n) {
			// ちょうどm人のグループをi個にわける
			ans += comb[n][m*i] * f(m*i, m) % mod *
					powmod(fact[i], mod - 2, mod) % mod *
					rec(n - i * m, m - 1) % mod;
		}
//		dump(n, m, ans);
		return memo[n][m] = ans % mod;
	}

	long f(int x, int m) {
		if (x == m) return 1;
		if (memo2[x][m] != -1) return memo2[x][m];
		return memo2[x][m] = comb[x][m] * f(x - m, m) % mod;
	}
	static long powmod(long n, long r, int m) {
		long res = 1;
		for(; r != 0; r >>>= 1, n = n * n % m) {
			if((r&1) == 1) {
				res = res * n;
				if(res >= m) {
					res %= m;
				}
			}
		}
		return res;
	}

