		long[][] comb = new long[N+1][N+1];
		for(int i=0; i<N+1; i++)
			for(int j=0; j<=i; j++)
				comb[i][j] = (j==0 || j==i) ? 1 : (comb[i-1][j] + comb[i-1][j-1])%MOD;

		long[] fac = new long[N+1];
		fac[0] = fac[1] = 1;
