  public static long MOD = (long)Math.pow(10, 9) + 7;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int a = sc.nextInt();
    int b = sc.nextInt();
    int c = sc.nextInt();
    int d = sc.nextInt();
    long[][] dp = new long[b - a + 1][n + 1];
    long[] kai = new long[n + 1];
    kai[0] = 1;
    for(int i = 1; i <= n; i++) {
      kai[i] = (kai[i - 1] * (long)i) % MOD;
    }
    dp[0][0] = 1;
    for(int j = c; j <= Math.min(d, (n / a)); j++) {
      int t = a * j;
      dp[0][t] = (kai[n] * func(kai[n - t], MOD - 2)) % MOD;
    //  dp[0][t] = (dp[0][t] * func(n - t, MOD - 2)) % MOD;
      dp[0][t] = (dp[0][t] * func(kai[a], (long)j * (MOD - 2))) % MOD;
      dp[0][t] = (dp[0][t] * func(kai[j], MOD - 2)) % MOD;  
    }
    for(int i = 1; i < (b - a + 1); i++) {
      dp[i][0] = 1;
      for(int j = 1; j <= n; j++) {
        dp[i][j] = dp[i - 1][j];
        for(int k = c; k <= Math.min(d, j / (i + a)); k++) {
          int s = (i + a) * k;
          long t = (dp[i - 1][j - s] * kai[n - j + s]) % MOD;
          t = (t * func(kai[n - j], MOD - 2)) % MOD;
          t = (t * func(kai[i + a], (long)k * (MOD - 2))) % MOD;
          t = (t * func(kai[k], MOD - 2)) % MOD;
          dp[i][j] = (dp[i][j] + t) % MOD;
        }
      }
    }
    System.out.println(dp[b - a][n]);
  }

  public static long func(long a, long x) {
    if(x == 0) return 1;
    if((x % 2) == 0) {
      long t = func(a, x / 2);
      return (t * t) % MOD;
    } else {
      return (a * func(a, x - 1)) % MOD;
    }
  }
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int a = ni(), b = ni(), c = ni(), d = ni();
		int mod = 1000000007;
		long[] dp = new long[n+1];
		int[][] fif = enumFIF(3000, mod);
		dp[0] = 1;
		for(int i = a;i <= b;i++){
			long[] ndp = Arrays.copyOf(dp, n+1);
			long pw = pow(fif[1][i], c-1, mod);
			for(int j = c;j <= d;j++){
				pw = pw * fif[1][i] % mod;
				for(int k = 0;k+j*i <= n;k++){
					ndp[k+j*i] += dp[k] * pw % mod * fif[1][j];
					ndp[k+j*i] %= mod;
				}
			}
			dp = ndp;
		}
		out.println(dp[n]*fif[0][n]%mod);
	}

	public static long pow(long a, long n, long mod) {
		//		a %= mod;
		long ret = 1;
		int x = 63 - Long.numberOfLeadingZeros(n);
		for (; x >= 0; x--) {
			ret = ret * ret % mod;
			if (n << 63 - x < 0)
				ret = ret * a % mod;
		}
		return ret;
	}


	public static int[][] enumFIF(int n, int mod) {
		int[] f = new int[n + 1];
		int[] invf = new int[n + 1];
		f[0] = 1;
		for (int i = 1; i <= n; i++) {
			f[i] = (int) ((long) f[i - 1] * i % mod);
		}
		long a = f[n];
		long b = mod;
		long p = 1, q = 0;
		while (b > 0) {
			long c = a / b;
			long d;
			d = a;
			a = b;
			b = d % b;
			d = p;
			p = q;
			q = d - c * q;
		}
		invf[n] = (int) (p < 0 ? p + mod : p);
		for (int i = n - 1; i >= 0; i--) {
			invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
		}
		return new int[][] { f, invf };
	}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.NoSuchElementException;


public class Main {
  private static int N, A, B, C, D;
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    N = sc.nextInt();
    A = sc.nextInt();
    B = sc.nextInt();
    C = sc.nextInt();
    D = sc.nextInt();

    for (long[] v : memo) Arrays.fill(v, -1);
    long ret = dfs(A, N);

    System.out.println(ret);
  }

  private static int mod = 1000000000 + 7;
  private static int[][] fif = enumFIF(1001, mod);
  private static long[][] memo = new long[1011][1011];

  // 残りl人  a人以上のグループで構成
  private static long dfs(int a, int l) {
    long ret = memo[a][l];
    if (ret >= 0) {
      return ret;
    }

    if (l == 0) {
      ret = 1;
    } else {
      ret = 0;
      if (a > B) {
        memo[a][l] = 0;
        return 0;
      }

      ret += dfs(a + 1, l);
      ret %= mod;
      long v = 1;

      int ll = l;
      for (int i = 1; i <= D && a <= ll; i ++) {
        v = v * c(ll, a) % mod;
        ll -= a;

        if (C <= i && i <= D) {
          ret += v * dfs(a + 1, ll) % mod * fif[1][i] % mod;
          ret %= mod;
        }
      }
    }

    memo[a][l] = ret;
    return ret;
  }

  private static long c(int n, int k) {
    if (n < k) return 0;
    return (long)fif[0][n] * fif[1][k] % mod * fif[1][n - k] % mod;
  }

  public static int[][] enumFIF(int n, int mod) {
    int[] f = new int[n + 1];
    int[] invf = new int[n + 1];
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = (int) ((long) f[i - 1] * i % mod);
    }
    long a = f[n];
    long b = mod;
    long p = 1, q = 0;
    while (b > 0) {
        long c = a / b;
        long d;
        d = a;
        a = b;
        b = d % b;
        d = p;
        p = q;
        q = d - c * q;
    }
    invf[n] = (int) (p < 0 ? p + mod : p);
    for (int i = n - 1; i >= 0; i--) {
        invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
    }
    return new int[][] { f, invf };
}
}


class FastScanner {
  public static String debug = null;

  private final InputStream in = System.in;
  private int ptr = 0;
  private int buflen = 0;
  private byte[] buffer = new byte[1024];
  private boolean eos = false;

  private boolean hasNextByte() {
    if (ptr < buflen) {
      return true;
    } else {
      ptr = 0;
      try {
        if (debug != null) {
          buflen = debug.length();
          buffer = debug.getBytes();
          debug = "";
          eos = true;
        } else {
          buflen = in.read(buffer);
        }
      } catch (IOException e) {
        e.printStackTrace();
      }
      if (buflen < 0) {
        eos = true;
        return false;
      } else if (buflen == 0) {
        return false;
      }
    }
    return true;
  }

  private int readByte() {
    if (hasNextByte())
      return buffer[ptr++];
    else
      return -1;
  }

  private static boolean isPrintableChar(int c) {
    return 33 <= c && c <= 126;
  }

  private void skipUnprintable() {
    while (hasNextByte() && !isPrintableChar(buffer[ptr]))
      ptr++;
  }

  public boolean isEOS() {
    return this.eos;
  }

  public boolean hasNext() {
    skipUnprintable();
    return hasNextByte();
  }

  public String next() {
    if (!hasNext())
      throw new NoSuchElementException();
    StringBuilder sb = new StringBuilder();
    int b = readByte();
    while (isPrintableChar(b)) {
      sb.appendCodePoint(b);
      b = readByte();
    }
    return sb.toString();
  }

  public long nextLong() {
    if (!hasNext())
      throw new NoSuchElementException();
    long n = 0;
    boolean minus = false;
    int b = readByte();
    if (b == '-') {
      minus = true;
      b = readByte();
    }
    if (b < '0' || '9' < b) {
      throw new NumberFormatException();
    }
    while (true) {
      if ('0' <= b && b <= '9') {
        n *= 10;
        n += b - '0';
      } else if (b == -1 || !isPrintableChar(b)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
      b = readByte();
    }
  }

  public int nextInt() {
    return (int) nextLong();
  }

  public long[] nextLongList(int n) {
    return nextLongTable(1, n)[0];
  }

  public int[] nextIntList(int n) {
    return nextIntTable(1, n)[0];
  }

  public long[][] nextLongTable(int n, int m) {
    long[][] ret = new long[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ret[i][j] = nextLong();
      }
    }
    return ret;
  }

  public int[][] nextIntTable(int n, int m) {
    int[][] ret = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ret[i][j] = nextInt();
      }
    }
    return ret;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {

	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		MyInput in = new MyInput(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt(), a = in.nextInt(), b = in.nextInt();
			int c = in.nextInt(), d = in.nextInt();

			// i 人未満のグループで j 人作るときの場合の数
			long[][] dp = new long[n+2][n+2];
			dp[a][0] = 1;

			for (int i = a; i <= b; i++) {
				for (int j = 0; j <= n; j++) {
					if (dp[i][j] == 0) continue;
					dp[i+1][j] += dp[i][j];
					dp[i+1][j] %= MOD;

					long product = dp[i][j];
					for (int k = 1; k <= d; k++) {
						if (n - j - i * k < 0) break;

						product *= comb(n - j - i * (k-1), i);
						product %= MOD;

						if (k < c) continue;
						dp[i+1][j+i*k] += product * factInv[k];
						dp[i+1][j+i*k] %= MOD;
					}
				}
			}

			out.println(dp[b+1][n]);

		}
	}

	public static long comb(int n, int r) {
		if (r < 0 || r > n)
			return 0L;
		return fact[n] % MOD * factInv[r] % MOD * factInv[n - r] % MOD;
	}

	public static int MAXN = 200000;

	static long[] fact = factorialArray(MAXN, MOD);
	static long[] factInv = factorialInverseArray(MAXN, MOD,
			inverseArray(MAXN, MOD));

	public static long[] factorialArray(int maxN, long mod) {
		long[] fact = new long[maxN + 1];
		fact[0] = 1 % mod;
		for (int i = 1; i <= maxN; i++) {
			fact[i] = fact[i - 1] * i % mod;
		}
		return fact;
	}

	public static long[] inverseArray(int maxN, long modP) {
		long[] inv = new long[maxN + 1];
		inv[1] = 1;
		for (int i = 2; i <= maxN; i++) {
			inv[i] = modP - (modP / i) * inv[(int) (modP % i)] % modP;
		}
		return inv;
	}

	public static long[] factorialInverseArray(int maxN, long modP,
			long[] inverseArray) {
		long[] factInv = new long[maxN + 1];
		factInv[0] = 1;
		for (int i = 1; i <= maxN; i++) {
			factInv[i] = factInv[i - 1] * inverseArray[i] % modP;
		}
		return factInv;
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
		private static boolean[] isDigit = new boolean[256];
		private static boolean[] isSpace = new boolean[256];
		private static boolean[] isLineSep = new boolean[256];

		static {
			for (int i = 0; i < 10; i++) {
				isDigit['0' + i] = true;
			}
			isDigit['-'] = true;
			isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
			isLineSep['\r'] = isLineSep['\n'] = true;
		}

		public MyInput(InputStream is) {
			in = new BufferedReader(new InputStreamReader(is));
		}

		public int read() {
			if (pos >= readLen) {
				pos = 0;
				try {
					readLen = in.read(buffer);
				} catch (IOException e) {
					throw new RuntimeException();
				}
				if (readLen <= 0) {
					throw new MyInput.EndOfFileRuntimeException();
				}
			}
			return buffer[pos++];
		}

		public int nextInt() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			int ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public long nextLong() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			long ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public char nextChar() {
			while (true) {
				final int c = read();
				if (!isSpace[c]) {
					return (char) c;
				}
			}
		}

		public String nextString() {
			return new String(nextChars());
		}

		public char[] nextChars() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			return Arrays.copyOf(str, len);
		}

		public char[][] next2DChars(int h, int w) {
			char[][] s = new char[h][w];
			for (int i = 0; i < h; i++) {
				s[i] = nextChars();
			}
			return s;
		}

		int reads(int len, boolean[] accept) {
			try {
				while (true) {
					final int c = read();
					if (accept[c]) {
						break;
					}
					if (str.length == len) {
						char[] rep = new char[str.length * 3 / 2];
						System.arraycopy(str, 0, rep, 0, str.length);
						str = rep;
					}
					str[len++] = (char) c;
				}
			} catch (MyInput.EndOfFileRuntimeException e) {
			}
			return len;
		}

		public int[] nextIntArray(final int n) {
			final int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public int[] nextIntArray1Index(final int n) {
			final int[] res = new int[n + 1];
			for (int i = 1; i < n + 1; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public int[] nextIntArrayDec(final int n) {
			final int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt() - 1;
			}
			return res;
		}

		public long[] nextLongArray(final int n) {
			final long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public long[] nextLongArray1Index(final int n) {
			final long[] res = new long[n + 1];
			for (int i = 1; i < n + 1; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public long[] nextLongArrayDec(final int n) {
			final long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong() - 1;
			}
			return res;
		}

		public double nextDouble() {
			return Double.parseDouble(nextString());
		}

		public double[] nextDoubleArray(int n) {
			double[] res = new double[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextDouble();
			}
			return res;
		}

		static class EndOfFileRuntimeException extends RuntimeException {
		}

	}

}

import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        StringBuilder sb = new StringBuilder();
        long MOD = 1000000007;
        ModArithmetic ma = new ModArithmetic(MOD);
        int n = nextInt(sc);
        int a = nextInt(sc);
        int b = nextInt(sc);
        int c = nextInt(sc);
        int d = nextInt(sc);
        long[] f = ma.factorial(n);
        long[][] dp = new long[n + 1][n + 1];
        dp[a][0] = 1;
        for (int k = c; (long) k * a <= n && k <= d; k++) {
            long v = f[n];
            long dv = ma.prod(f[n - k * a], f[k], ma.pow(f[a], k));
            dp[a][k * a] = ma.div(v, dv);
        }
        for (int i = a; i < b; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i + 1][j] += dp[i][j];
                if (dp[i + 1][j] >= MOD) dp[i + 1][j] -= MOD;
                for (int k = c; j + (long) k * (i + 1) <= n && k <= d; k++) {
                    int nj = j + k * (i + 1);
                    long v = ma.mul(f[n - j], dp[i][j]);
                    long dv = ma.prod(f[n - j - k * (i + 1)], f[k], ma.pow(f[i + 1], k));
                    dp[i + 1][nj] += ma.div(v, dv);
                    if (dp[i + 1][nj] >= MOD) dp[i + 1][nj] -= MOD;
                }
            }
        }
        sb.append(dp[b][n]).append('\n');
        pw.write(sb.toString());
        pw.flush();
        pw.close();
    }

    public static int nextInt(Scanner sc) {
        return Integer.parseInt(sc.next());
    }
    public static long nextLong(Scanner sc) {
        return Long.parseLong(sc.next());
    }
}


/**
 * 剰余関連の演算をまとめたクラス．
 * 
 * verified:
 *  -
 *  -
 * 
 * @author https://atcoder.jp/users/suisen
 */
class ModArithmetic {

    /**
     * 剰余の法
     */
    final long MOD;

    /**
     * 剰余の法を指定して，指定された法の下で各種演算を行うインスタンスを生成
     * @param mod 剰余の法
     */
    public ModArithmetic(long mod) {
        this.MOD = mod;
    }

    /************** instance methods ***************/

    /**
     * MOD の getter method
     * @return MOD
     */
    public long getMod() {
        return MOD;
    }

    /**
     * [0, MOD) に含まれない可能性のある整数の剰余を計算する．
     * @param a [0, MOD) に含まれない可能性のある整数
     * @return 剰余
     */
    public long mod(long a) {
        a %= MOD;
        return a < 0 ? a + MOD : a;
    }

    /**
     * a + b の剰余を計算する．
     * {@code 0 <= a < MOD && 0 <= b < MOD && a + b <= Long.MAX_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a < MOD && 0 <= b < MOD && a + b <= Long.MAX_VALUE} なる整数
     * @param b {@code 0 <= a < MOD && 0 <= b < MOD && a + b <= Long.MAX_VALUE} なる整数
     * @return a + b の剰余．条件を満たしていれば結果は 0 以上 MOD 未満となることが保証される．
     */
    public long add(long a, long b) {
        long c = a + b;
        return c >= MOD ? c - MOD : c;
    }

    /**
     * a - b の剰余を計算する．
     * {@code 0 <= a < MOD && 0 <= b < MOD && a - b >= Long.MIN_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a < MOD && 0 <= b < MOD && a - b >= Long.MIN_VALUE} なる整数
     * @param b {@code 0 <= a < MOD && 0 <= b < MOD && a - b >= Long.MIN_VALUE} なる整数
     * @return a - b の剰余．条件を満たしていれば結果は 0 以上 MOD 未満となることが保証される．
     */
    public long sub(long a, long b) {
        long c = a - b;
        return c < 0 ? c + MOD : c;
    }

    /**
     * a * b の剰余を計算する．{@code 0 <= a * b <= Long.MAX_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a * b <= Long.MAX_VALUE} なる整数
     * @param b {@code 0 <= a * b <= Long.MAX_VALUE} なる整数
     * @return a * b の剰余．条件を満たしていれば結果は 0 以上 MOD 未満となることが保証される．
     */
    public long mul(long a, long b) {
        long c = a * b;
        return c % MOD;
    }

    /**
     * a = x * b (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x を計算する (x = a * b^(-1))．
     * {@code b} と {@code MOD} は互いに素でなければならない．
     * また，{@code 0 <= a * b^(-1) <= Long.MAX_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a * b^(-1) <= Long.MAX_VALUE} なる整数
     * @param b {@code 0 <= a * b^(-1) <= Long.MAX_VALUE} かつ MOD と互いに素な整数
     * @return a = x * b (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x．
     */
    public long div(long a, long b) {
        long c = a * inv(b, MOD);
        return c % MOD;
    }

    /**
     * a * x = 1 (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x を計算する (x = a^(-1))．
     * {@code a} と {@code MOD} は互いに素でなければならない．
     * @param a mod MOD での乗法逆元を求めたい整数．MOD とは互いに素である必要がある
     * @return a * x = 1 (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x．
     */
    public long inv(long a) {
        return inv(a, MOD);
    }

    /**
     * a ^ b (累乗) の剰余を計算する．O(log b)．
     * @param a 底
     * @param b 指数 (a と MOD が互いに素な場合は mod (MOD - 1) しておくと定数倍が高速になる)
     * @return a ^ b (累乗) の剰余．0 以上 MOD 未満が保証される．
     */
    public long pow(long a, long b) {
        return pow(a, b, MOD);
    }

    /**
     * add の可変長引数版．3 項以上の加算にはこれを用いると記述が楽．
     * ただし，パフォーマンスは悪くなるので注意．
     * @param vals 総和を取りたい列
     * @return 列の総和の剰余
     */
    public long sum(long... vals) {
        long ret = 0;
        for (long v : vals) {
            ret += v;
            if (ret >= MOD) ret -= MOD;
        }
        return ret;
    }

    /**
     * mul の可変長引数版．3 項以上の乗算にはこれを用いると記述が楽．
     * ただし，パフォーマンスは悪くなるので注意．
     * @param vals 総積を取りたい列
     * @return 列の総積の剰余
     */
    public long prod(long... vals) {
        long ret = 1;
        for (long v : vals) {
            ret = (ret * v) % MOD;
        }
        return ret;
    }

    /**
     * 1, 2, ..., n に対する mod MOD での乗法逆元を計算する．O(n)．
     * 配列の i 番目に i^(-1) の計算結果が入っている．0 番目は使わない．
     * @param n 最大値
     * @return 長さ {@code n + 1} の配列．i 番目に i^(-1) の計算結果が入っている．0 番目は使わない．
     */
    public long[] rangeInv(int n) {
        return rangeInv(n, MOD);
    }

    /**
     * 長さ N の配列 {@code a} の各要素に対する mod MOD での乗法逆元を計算する．O(N)．
     * 配列の i 番目に a[i]^(-1) の計算結果が入っている．但し，{@code a} の各要素は非零でなければならない．
     * @param a 逆元を求めたい配列．各要素は非零．
     * @return {@code a} の各要素に対する mod MOD での乗法逆元を格納した配列
     */
    public long[] arrayInv(long[] a) {
        return arrayInv(a, MOD);
    }

    /**
     * 0!, 1!, ..., n! の剰余を計算する．O(n)．
     * 配列の i 番目に i! の計算結果が入っている．
     * @param n 最大値
     * @return 長さ {@code n + 1} の配列．i 番目に i! の計算結果が入っている．
     */
    public long[] factorial(int n) {
        return factorial(n, MOD);
    }

    /**
     * 0!, 1!, ..., n! に対する mod MOD での乗法逆元を計算する．O(n)．
     * 配列の i 番目に i!^(-1) の計算結果が入っている．
     * @param n 最大値
     * @return 長さ {@code n + 1} の配列．i 番目に i!^(-1) の計算結果が入っている．
     */
    public long[] factorialInv(int n) {
        return factorialInv(n, MOD);
    }

    /**
     * a^0, a^1, ..., a^n に対する mod MOD での乗法逆元を計算する．O(n)．
     * 配列の i 番目に a^i の計算結果が入っている．
     * @param a 底
     * @param n 指数の最大値
     * @return 長さ {@code n + 1} の配列．i 番目に a^i の計算結果が入っている．
     */
    public long[] rangePower(long a, int n) {
        return rangePower(a, n, MOD);
    }

    /*************** static methods ****************/


    /**
     * [0, MOD) に含まれない可能性のある整数の剰余を計算する．
     * @param a [0, MOD) に含まれない可能性のある整数
     * @param mod MOD
     * @return 剰余
     */
    public static long mod(long a, long mod) {
        a %= mod;
        return a < 0 ? a + mod : a;
    }

    /**
     * a + b の剰余を計算する．
     * {@code 0 <= a < MOD && 0 <= b < MOD && a + b <= Long.MAX_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a < MOD && 0 <= b < MOD && a + b <= Long.MAX_VALUE} なる整数
     * @param b {@code 0 <= a < MOD && 0 <= b < MOD && a + b <= Long.MAX_VALUE} なる整数
     * @param mod MOD
     * @return a + b の剰余．条件を満たしていれば結果は 0 以上 MOD 未満となることが保証される．
     */
    public static long add(long a, long b, long mod) {
        long c = a + b;
        return c >= mod ? c - mod : c;
    }

    /**
     * a - b の剰余を計算する．
     * {@code 0 <= a < MOD && 0 <= b < MOD && a - b >= Long.MIN_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a < MOD && 0 <= b < MOD && a - b >= Long.MIN_VALUE} なる整数
     * @param b {@code 0 <= a < MOD && 0 <= b < MOD && a - b >= Long.MIN_VALUE} なる整数
     * @param mod MOD
     * @return a - b の剰余．条件を満たしていれば結果は 0 以上 MOD 未満となることが保証される．
     */
    public static long sub(long a, long b, long mod) {
        long c = a - b;
        return c < 0 ? c + mod : c;
    }

    /**
     * a * b の剰余を計算する．{@code 0 <= a * b <= Long.MAX_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a * b <= Long.MAX_VALUE} なる整数
     * @param b {@code 0 <= a * b <= Long.MAX_VALUE} なる整数
     * @param mod MOD
     * @return a * b の剰余．条件を満たしていれば結果は 0 以上 MOD 未満となることが保証される．
     */
    public static long mul(long a, long b, long mod) {
        long c = a * b;
        return c % mod;
    }

    /**
     * a = x * b (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x を計算する (x = a * b^(-1))．
     * {@code b} と {@code MOD} は互いに素でなければならない．
     * また，{@code 0 <= a * b^(-1) <= Long.MAX_VALUE} を満たさなければならない．
     * @param a {@code 0 <= a * b^(-1) <= Long.MAX_VALUE} なる整数
     * @param b {@code 0 <= a * b^(-1) <= Long.MAX_VALUE} かつ MOD と互いに素な整数
     * @param mod MOD
     * @return a = x * b (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x．
     */
    public static long div(long a, long b, long mod) {
        long c = a * inv(b, mod);
        return c % mod;
    }

    /**
     * a * x = 1 (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x を計算する (x = a^(-1))．
     * {@code a} と {@code MOD} は互いに素でなければならない．
     * @param a mod MOD での乗法逆元を求めたい整数．MOD とは互いに素である必要がある
     * @param mod MOD
     * @return a * x = 1 (mod MOD) && 0 <= x < MOD を満たす唯一の整数 x．
     */
    public static long inv(long a, long mod) {
        long b = mod;
        long u = 1, v = 0;
        while (b >= 1) {
            long t = a / b;
            a -= t * b;
            long tmp;
            tmp = a; a = b; b = tmp;
            u -= t * v;
            tmp = u; u = v; v = tmp;
        }
        u %= mod;
        return u < 0 ? u + mod : u;
    }

    /**
     * a ^ b (累乗) の剰余を計算する．O(log b)．
     * @param a 底
     * @param b 指数 (a と MOD が互いに素な場合は mod (MOD - 1) しておくと定数倍が高速になる)
     * @param mod MOD
     * @return a ^ b (累乗) の剰余．0 以上 MOD 未満が保証される．
     */
    public static long pow(long a, long b, long mod) {
        long pow = 1;
        for (long p = a, c = 1; b > 0;) { // p = a^c
            long lsb = b & -b;
            while (lsb != c) {
                c <<= 1;
                p = (p * p) % mod;
            }
            pow = (pow * p) % mod;
            b ^= lsb;
        }
        return pow;
    }

    /**
     * 1, 2, ..., n に対する mod MOD での乗法逆元を計算する．O(n)．
     * 配列の i 番目に i^(-1) の計算結果が入っている．0 番目は使わない．
     * @param n 最大値
     * @param mod MOD
     * @return 長さ {@code n + 1} の配列．i 番目に i^(-1) の計算結果が入っている．0 番目は使わない．
     */
    public static long[] rangeInv(int n, long mod) {
        long[] invs = new long[n + 1];
        invs[1] = 1;
        for (int i = 2; i <= n; i++) {
            long q = mod - mod / i;
            long r = invs[(int) (mod % i)];
            invs[i] = (q * r) % mod;
        }
        return invs;
    }

    /**
     * 長さ N の配列 {@code a} の各要素に対する mod MOD での乗法逆元を計算する．O(N)．
     * 配列の i 番目に a[i]^(-1) の計算結果が入っている．但し，{@code a} の各要素は非零でなければならない．
     * @param a 逆元を求めたい配列．各要素は非零．
     * @param mod MOD
     * @return {@code a} の各要素に対する mod MOD での乗法逆元を格納した配列
     */
    public static long[] arrayInv(long[] a, long mod) {
        int n = a.length;
        long[] dp = new long[n + 1];
        long[] pd = new long[n + 1];
        dp[0] = pd[n] = 1;
        for (int i = 0; i < n; i++) dp[i + 1] = (dp[i] * a[i    ]) % mod;
        for (int i = n; i > 0; i--) pd[i - 1] = (pd[i] * a[i - 1]) % mod;
        long inv = inv(dp[n], mod);
        long[] invs = new long[n];
        for (int i = 0; i < n; i++) {
            long lr = (dp[i] * pd[i + 1]) % mod;
            invs[i] = (lr * inv) % mod;
        }
        return invs;
    }

    /**
     * 0!, 1!, ..., n! の剰余を計算する．O(n)．
     * 配列の i 番目に i! の計算結果が入っている．
     * @param n 最大値
     * @param mod MOD
     * @return 長さ {@code n + 1} の配列．i 番目に i! の計算結果が入っている．
     */
    public static long[] factorial(int n, long mod) {
        long[] ret = new long[n + 1];
        ret[0] = 1;
        for (int i = 1; i <= n; i++) ret[i] = (ret[i - 1] * i) % mod;
        return ret;
    }

    /**
     * 0!, 1!, ..., n! に対する mod MOD での乗法逆元を計算する．O(n)．
     * 配列の i 番目に i!^(-1) の計算結果が入っている．
     * @param n 最大値
     * @param mod MOD
     * @return 長さ {@code n + 1} の配列．i 番目に i!^(-1) の計算結果が入っている．
     */
    public static long[] factorialInv(int n, long mod) {
        long facN = 1;
        for (int i = 2; i <= n; i++) facN = (facN * i) % mod;
        long[] invs = new long[n + 1];
        invs[n] = inv(facN, mod);
        for (int i = n; i > 0; i--) invs[i - 1] = (invs[i] * i) % mod;
        return invs;
    }

    /**
     * a^0, a^1, ..., a^n に対する mod MOD での乗法逆元を計算する．O(n)．
     * 配列の i 番目に a^i の計算結果が入っている．
     * @param a 底
     * @param n 指数の最大値
     * @param mod MOD
     * @return 長さ {@code n + 1} の配列．i 番目に a^i の計算結果が入っている．
     */
    public static long[] rangePower(long a, int n, long mod) {
        long[] pows = new long[n + 1];
        pows[0] = 1;
        for (int i = 1; i <= n; i++) pows[i] = (pows[i - 1] * a) % mod;
        return pows;
    }

    /******* Usage *******/

    public static void main(String[] args) {
        // using instance methods
        ModArithmetic ma = new ModArithmetic(998244353);
        long inv7 = ma.inv(7);
        System.out.println(ma.mul(7, inv7));
        // using static methods
        long inv7_2 = ModArithmetic.inv(7, 1000000007);
        System.out.println(ModArithmetic.mul(7, inv7_2, 1000000007));
    }
}

