public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "daltao", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            TaskA solver = new TaskA();
            solver.solve(1, in, out);
            out.close();
        }
    }
    static class TaskA {
        int[][] dp;
        int a;
        int b;
        int c;
        int d;
        int n;
        NumberTheory.Modular mod = new NumberTheory.Modular(1e9 + 7);
        NumberTheory.Power pow = new NumberTheory.Power(mod);
        NumberTheory.Factorial fact = new NumberTheory.Factorial(2000, mod);

        public void solve(int testNumber, FastInput in, FastOutput out) {
            n = in.readInt();
            a = in.readInt();
            b = in.readInt();
            c = in.readInt();
            d = in.readInt();

            dp = new int[n + 1][n + 1];
            ArrayUtils.deepFill(dp, -1);

            int ans = dp(a, n);
            out.println(ans);
        }

        public int dp(int i, int j) {
            if (i > b) {
                return j == 0 ? 1 : 0;
            }
            if (dp[i][j] == -1) {
                dp[i][j] = dp(i + 1, j);
                for (int k = c; k <= d; k++) {
                    if (k * i > j) {
                        break;
                    }
                    int contrib = mod.mul(fact.fact(j), fact.invFact(j - k * i));
                    contrib = mod.mul(contrib, pow.pow(fact.invFact(i), k));
                    contrib = mod.mul(contrib, fact.invFact(k));
                    contrib = mod.mul(contrib, dp(i + 1, j - k * i));
                    dp[i][j] = mod.plus(dp[i][j], contrib);
                }
            }
            return dp[i][j];
        }

    }
    static class ArrayUtils {
        public static void deepFill(Object array, int val) {
            if (!array.getClass().isArray()) {
                throw new IllegalArgumentException();
            }
            if (array instanceof int[]) {
                int[] intArray = (int[]) array;
                Arrays.fill(intArray, val);
            } else {
                Object[] objArray = (Object[]) array;
                for (Object obj : objArray) {
                    deepFill(obj, val);
                }
            }
        }

    }
    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(1 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(int c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
    static class NumberTheory {
        public static class Modular {
            int m;

            public Modular(int m) {
                this.m = m;
            }

            public Modular(long m) {
                this.m = (int) m;
                if (this.m != m) {
                    throw new IllegalArgumentException();
                }
            }

            public Modular(double m) {
                this.m = (int) m;
                if (this.m != m) {
                    throw new IllegalArgumentException();
                }
            }

            public int valueOf(int x) {
                x %= m;
                if (x < 0) {
                    x += m;
                }
                return x;
            }

            public int valueOf(long x) {
                x %= m;
                if (x < 0) {
                    x += m;
                }
                return (int) x;
            }

            public int mul(int x, int y) {
                return valueOf((long) x * y);
            }

            public int plus(int x, int y) {
                return valueOf(x + y);
            }

            public String toString() {
                return "mod " + m;
            }

        }

        public static class Power {
            final NumberTheory.Modular modular;

            public Power(NumberTheory.Modular modular) {
                this.modular = modular;
            }

            public int pow(int x, long n) {
                if (n == 0) {
                    return 1;
                }
                long r = pow(x, n >> 1);
                r = modular.valueOf(r * r);
                if ((n & 1) == 1) {
                    r = modular.valueOf(r * x);
                }
                return (int) r;
            }

        }

        public static class InverseNumber {
            int[] inv;

            public InverseNumber(int[] inv, int limit, NumberTheory.Modular modular) {
                this.inv = inv;
                inv[1] = 1;
                int p = modular.m;
                for (int i = 2; i <= limit; i++) {
                    int k = p / i;
                    int r = p % i;
                    inv[i] = modular.mul(-k, inv[r]);
                }
            }

            public InverseNumber(int limit, NumberTheory.Modular modular) {
                this(new int[limit + 1], limit, modular);
            }

        }

        public static class Factorial {
            int[] fact;
            int[] inv;
            NumberTheory.Modular modular;

            public Factorial(int[] fact, int[] inv, NumberTheory.InverseNumber in, int limit,
                            NumberTheory.Modular modular) {
                this.modular = modular;
                this.fact = fact;
                this.inv = inv;
                fact[0] = inv[0] = 1;
                for (int i = 1; i <= limit; i++) {
                    fact[i] = modular.mul(fact[i - 1], i);
                    inv[i] = modular.mul(inv[i - 1], in.inv[i]);
                }
            }

            public Factorial(int limit, NumberTheory.Modular modular) {
                this(new int[limit + 1], new int[limit + 1], new NumberTheory.InverseNumber(limit, modular), limit,
                                modular);
            }

            public int fact(int n) {
                return fact[n];
            }

            public int invFact(int n) {
                return inv[n];
            }

        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        long MOD = TypicalMods.MOD1000000007;
        ModArithmetic ma = new ModArithmetic(MOD);
        int n = sc.nextInt();
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        long[] f = ma.factorialMemo(n);
        long[] iv = ma.invMemo(n);
        long[][] cm = new long[n + 1][n + 1];
        cm[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            cm[i][0] = cm[i][i] = 1;
            for (int j = 1; j < i; j++) {
                cm[i][j] = cm[i - 1][j - 1] + cm[i - 1][j];
                if (cm[i][j] >= MOD) cm[i][j] -= MOD;
            }
        }
        long[][] fp = new long[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            fp[i][0] = 1;
            for (int j = 1; j * i <= n; j++) {
                long ml = ma.mul(cm[i * j][i], iv[j]);
                fp[i][j] = ma.mul(fp[i][j - 1], ml);
            }
        }
        long[][] dp = new long[n + 1][n + 1];
        dp[a][0] = 1;
        for (int k = c; k * a <= n && k <= d; k++) {
            dp[a][k * a] = ma.mul(cm[n][k * a], fp[a][k]);
        }
        for (int i = a; i < b; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i + 1][j] += dp[i][j];
                if (dp[i + 1][j] >= MOD) dp[i + 1][j] -= MOD;
                for (int k = c; j + k * (i + 1) <= n && k <= d; k++) {
                    int nj = j + k * (i + 1);
                    long ml = ma.mul(cm[n - j][k * (i + 1)], fp[i + 1][k]);
                    dp[i + 1][nj] += ma.mul(ml, dp[i][j]);
                    if (dp[i + 1][nj] >= MOD) dp[i + 1][nj] -= MOD;
                }
            }
        }
        out.writeln(dp[b][n]);
    }
}


