        static long[][] dp;
        static long[] fact;
        static long[] invfact;
        static int N, A, B, C, D;
        public static void solve(MyScanner sc, PrintWriter pw) throws IOException {
            N = sc.nextInt();
            A = sc.nextInt();
            B = sc.nextInt();
            C = sc.nextInt();
            D = sc.nextInt();
            precompute();
            dp = new long[2][N + 1];
