            for (int i = A; i <= B; i++) {
                int cutI = i % 2;
                int prevI = (i - 1) % 2;
                for (int j = C; j <= D; j++) {
                    int count = i * j;
                    if (count > N) break;
                    long subChoose = fact[count] * pow(invfact[i], j) % MOD * invfact[j] % MOD;
                    for (int k = count; k <= N; k++) {
                        long choose = fact[k] * invfact[count] % MOD * invfact[k - count] % MOD;
