                        dp[cutI][k] += add;
                        if (dp[cutI][k] >= MOD) dp[cutI][k] -= MOD;
                    }
                }
                for (int j = 0; j <= N; j++) {
                    dp[cutI][j] += dp[prevI][j];
                    if (dp[cutI][j] >= MOD) dp[cutI][j] -= MOD;
                }
                Arrays.fill(dp[prevI], 0);

            }
