        }
        static void Solve()
        {
            int N, A, B, C, D;
            Input(out N, out A, out B, out C, out D);
            int dif = B - A + 1;
            var dp = new ModInt[dif + 1, N + 1];
            dp[0, 0] = 1;

            var MPinv = new ModInt[N + 1, N + 1];
            var NCR = new ModInt[N + 1, N + 1];
            for (var i = 0; i <= N; i++) MPinv[i, 0] = MPinv[0, i] = 1;
            for (var i = 0; i <= N; i++) MPinv[i, 1] = 1 / Fac(i);
            for(var i = 1; i <= N; i++)
            {
                for(var j = 1; j < N; j++)
                {
                    MPinv[i, j + 1] = MPinv[i, j] * MPinv[i, 1];
                }
            }
            for (var i = 0; i <= N; i++) for (var j = 0; j <= i; j++) NCR[i, j] = Fac(i) * MPinv[j, 1] * MPinv[i - j, 1];

            for(var i = 0; i < dif; i++)
            {
                int num = A + i;
                for(var j = 0; j <= N; j++)
                {
                    dp[i + 1, j] += dp[i, j];

                    for(var k = C; k <= D; k++)
                    {
                        if (j + k * num > N) break;
                        dp[i + 1, j + k * num] += dp[i, j] * NCR[N - j, k * num] * Fac(k * num) * MPinv[num, k] * MPinv[k, 1];
                    }
                }
            }
            OutL(dp[dif, N].value);

        }
