public class Kyopuro{

    int n, a, b, c, d;
    int[] fac, inv;
    int[][] invpow;

    public void AtCoder(){
        const int p = 1000000007;
        long tmp = 0;
        string[] s = Console.ReadLine().Split(' ');
        n = int.Parse(s[0]);
        a = int.Parse(s[1]);
        b = int.Parse(s[2]);
        c = int.Parse(s[3]);
        d = int.Parse(s[4]);
        fac = new int[n+1];
        inv = new int[n+1];
        invpow = new int[n+1][];
        for(int i=0; i<=n; i++) invpow[i] = new int[n+1];

        fac[0] = 1;
        for(int i=1; i<=n; i++){
            tmp = fac[i-1];
            tmp *= i;
            tmp %= p;
            fac[i] = (int)tmp;
        }
        for(int i=0; i<=n; i++){
            inv[i] = Mod.Pow(fac[i], p-2);
        }
        for(int i=1; i<=n; i++){
            for(int j=0; j<=n; j++){
                invpow[i][j] = Mod.Pow(inv[i], j);
            }
        }

        int[][] dp = new int[n+1][];
        for(int i=0; i<=n; i++) dp[i] = new int[n+1];
        for(int i=0; i<=n; i++) dp[i][0] = 1;
        for(int i=a; i<=b; i++){
            for(int j=1; j<=n; j++){
                dp[i][j] += dp[i-1][j];
                dp[i][j] %= p;
                for(int k=c; k<=d; k++){
                    if(j-i*k<0) break;
                    tmp = dp[i-1][j-i*k];
                    tmp = tmp * fac[j] % p;
                    tmp = tmp * inv[j-i*k] % p;
                    tmp = tmp * invpow[i][k] % p;
                    tmp = tmp * inv[k] % p;
                    dp[i][j] += (int)tmp;
                    dp[i][j] %= p;
                }
            }
        }
        long ans = 0;
        for(int i=c; i<=d; i++){
            ans += dp[i][n];
            ans %= p;
        }
        Console.WriteLine(dp[b][n]);
    }

    public static void DebugWL(object x){ System.Diagnostics.Debug.WriteLine(x); }
}

