public class Mod{
	const int p = 1000000007;

	public static int Pow(int n, int m){
		if(m==0) return 1;
		if(m==1) return n;
		long a = 1;
		if(m%2 == 0){
			a = Pow(n,m/2);
			a = a * a % p;
		}else{
			a = Pow(n,m/2);
			a = a * a % p;
			a = a * n % p;
		}
		return (int)a;
	}
}

