class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, a, b, c, d;
        sc.Multi(out n, out a, out b, out c, out d);
        var dp = new long[n + 1];
        dp[n] = 1;
        MyMath.setfacts(n + 1);
        var inv = new long[n + 1];
        for (int i = 1; i < n + 1; i++)
        {
            inv[i] = MyMath.inv(i);
        }
        for (int i = a; i <= b && i * c <= n; i++)
        {
            var nex = dp.copy();
            for (int j = i * c; j <= n; j++)
            {
                long cb = 1;
                for (int k = 0; k < c - 1; k++)
                {
                    cb = cb * MyMath.comb(j - i * k, i) % M * inv[k + 1] % M;
                }
                for (int k = c; k <= d && i * k <= j; k++)
                {
                    cb = cb * MyMath.comb(j - i * (k - 1), i) % M * inv[k] % M;
                    nex[j - i * k] = (nex[j - i * k] + dp[j] * cb) % M;
                }
            }
            dp = nex;
        }
        Prt(dp[0]);
    }
}

