using System;

#region ModInt

/// <summary>
/// [0,<see cref="Mod"/>) までの値を取るような数
/// </summary>
public struct ModInt
{
    /// <summary>
    /// 剰余を取る値．
    /// </summary>
    public const long Mod = (int) 1e9 + 7;

    /// <summary>
    /// 実際の数値．
    /// </summary>
    public long num;

    /// <summary>
    /// 値が <paramref name="n"/> であるようなインスタンスを構築します．
    /// </summary>
    /// <param name="n">インスタンスが持つ値</param>
    /// <remarks>パフォーマンスの問題上，コンストラクタ内では剰余を取りません．そのため，<paramref name="n"/> ∈ [0,<see cref="Mod"/>) を満たすような <paramref name="n"/> を渡してください．このコンストラクタは O(1) で実行されます．</remarks>
    public ModInt(long n)
    {
        num = n;
    }

    /// <summary>
    /// このインスタンスの数値を文字列に変換します．
    /// </summary>
    /// <returns>[0,<see cref="Mod"/>) の範囲内の整数を 10 進表記したもの．</returns>
    public override string ToString()
    {
        return num.ToString();
    }

    public static ModInt operator +(ModInt l, ModInt r)
    {
        l.num += r.num;
        if (l.num >= Mod) l.num -= Mod;
        return l;
    }

    public static ModInt operator -(ModInt l, ModInt r)
    {
        l.num -= r.num;
        if (l.num < 0) l.num += Mod;
        return l;
    }

    public static ModInt operator *(ModInt l, ModInt r)
    {
        return new ModInt(l.num * r.num % Mod);
    }

    public static implicit operator ModInt(long n)
    {
        n %= Mod;
        if (n < 0) n += Mod;
        return new ModInt(n);
    }

    /// <summary>
    /// 与えられた 2 つの数値からべき剰余を計算します．
    /// </summary>
    /// <param name="v">べき乗の底</param>
    /// <param name="k">べき指数</param>
    /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
    public static ModInt Pow(ModInt v, long k)
    {
        return Pow(v.num, k);
    }

    /// <summary>
    /// 与えられた 2 つの数値からべき剰余を計算します．
    /// </summary>
    /// <param name="v">べき乗の底</param>
    /// <param name="k">べき指数</param>
    /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
    public static ModInt Pow(long v, long k)
    {
        long ret = 1;
        for (k %= Mod - 1; k > 0; k >>= 1, v = v * v % Mod)
            if ((k & 1) == 1)
                ret = ret * v % Mod;
        return new ModInt(ret);
    }

    /// <summary>
    /// 与えられた数の逆元を計算します．
    /// </summary>
    /// <param name="v">逆元を取る対象となる数</param>
    /// <returns>逆元となるような値</returns>
    /// <remarks>法が素数であることを仮定して，フェルマーの小定理に従って逆元を O(log N) で計算します．</remarks>
    public static ModInt Inverse(ModInt v)
    {
        return Pow(v, Mod - 2);
    }
}

#endregion

public class Program
{
    private int N, A, B, C, D;

    private ModInt?[,] Memo;

    private ModInt[] Fact;
    private ModInt[] InFact;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.NextInt();
        B = sc.NextInt();
        C = sc.NextInt();
        D = sc.NextInt();

        Memo = new ModInt?[N + 1, N + 1];

        Fact = new ModInt[1001];
        InFact = new ModInt[1001];
        Fact[0] = 1;
        InFact[0] = 1;
        for (int i = 1; i <= 1000; i++)
        {
            Fact[i] = Fact[i - 1] * i;
            InFact[i] = ModInt.Inverse(Fact[i]);
        }

        for (int i = 0; i <= N; i++)
        {
            for (int j = 0; j <= N; j++)
            {
                Memo[i, j] = null;
            }
        }

        Console.WriteLine(Calc(N, A));
    }

    // m人以上の組　残りn人
    ModInt Calc(int n, int m)
    {
        if (m > B)
        {
            return n == 0 ? 1 : 0;
        }

        if (Memo[n, m].HasValue)
        {
            return Memo[n, m].Value;
        }

        if (n == 0)
        {
            return 1;
        }

        ModInt result = 0;


        //F m == 0
        result += Calc(n, m + 1);

        int tmpN = n;
        ModInt f = 1;
        for (int i = 1; i < C; i++)
        {
            if (tmpN < m)
            {
                Memo[n, m] = result;
                return result;
            }
            f *= Combination(tmpN, m);
            tmpN -= m;
        }

        for (int fm = C; fm <= D; fm++)
        {
            if (tmpN < m)
            {
                break;
            }

            f *= Combination(tmpN, m);
            tmpN -= m;


            result += Calc(tmpN, m + 1) * f * InFact[fm];
        }

        Memo[n, m] = result;
        return result;
    }

    // n C m
    ModInt Combination(int n, int m)
    {
        return Fact[n] * InFact[m] * InFact[n - m];
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
