    if (n == 0) return 1;
    if (n < g) return 0;
    if (g > B) return 0;
    if (mem[g][n] >= 0) return mem[g][n];

    mem[g][n] = dp(g+1, n);
    foreach (i; C..D+1) {
        if (g * i > n) break;
        auto cnt =
            nck(n, g*i) * f_mod[g*i] % MOD
            * powmod(f_modinv[g], i, MOD) % MOD;
        mem[g][n] = (mem[g][n] + dp(g+1, n-g*i)*cnt%MOD) % MOD;
    }
    return mem[g][n];
}

