ulong diff(ulong x, ulong y){
	return (x - y) % mod;
	}

ulong prod(ulong[] xs ...){
	ulong ans = 1;
	foreach(x; xs){
		ans *= x;
		ans %= mod;
		}
	return ans;
	}

ulong quot(ulong x, ulong y){
	assert(y > 0);
	return x * inv(y) % mod;
	}

ulong inv(ulong x){
	assert(x > 0 && x < nmax);
	static bool inited = false;
	static ulong[nmax] _inv;
	if(!inited){
		_inv[1] = 1;
		foreach(i; 2 .. nmax){
			_inv[i] = (mod - mod / i) * _inv[mod % i] % mod;
			}
		inited = true;
		}
	return _inv[cast(int) x];
	}

ulong frac(ulong x){
