	static bool inited = false;
	static ulong[nmax] _frac;
	if(!inited){
		_frac[0] = 1;
		foreach(i; 1 .. nmax){
			_frac[i] = _frac[0] * i % mod;
			}
		inited = true;
		}
	return _frac[cast(int) x];
	}

ulong invfrac(ulong x){
	assert(x < nmax);
	static bool inited = false;
	static ulong[nmax] _invfrac;
	if(!inited){
		_invfrac[0] = 1;
		foreach(i; 1 .. nmax){
			_invfrac[i] = _invfrac[0] * inv(i) % mod;
			}
		inited = true;
		}
	return _invfrac[cast(int) x];
	}

ulong binom(ulong n, ulong k){
	assert(n < nmax);
	assert(k <= n);
	if(k == 0 || n - k == 0) return 1;
	else return frac(n) * invfrac(k) % mod * invfrac(n - k) % mod;
	}

