            dp[i][j+1] %= MOD;

            // number of group: c to d
            for k in c..d+1 {
                let ti = i + k*j;
                if ti > n {
                    break;
                }

                // choose k*j out of n-i
                // -- k*j to (k, k, ..., k)
                let ways = comb[n-i][k*j] * wo[j][k*j] % MOD * inv[k] % MOD;
                // debug!(ways, n-i, k, k*j);

                dp[ti][j+1] += base * ways % MOD;
                dp[ti][j+1] %= MOD;
            }
        }
    }

    println!("{}", dp[n][b+1]);
}

