                if dp[k] > 0 && (k - m * i >= (i + 1) * c || k - m * i == 0) {
                    let delta = dp[k] * fact[k] % M;
                    let mut inv = fact[k - m * i] * mod_pow(fact[i], m as u64, M) % M;
                    inv = inv * fact[m];
                    next[k - m * i] += delta * mod_inverse(inv, M) % M;
