    let mut stairs = vec![1; n + 1];
    for i in 1..n + 1 {
        stairs[i] = stairs[i-1] * i % m;
    }
    let stairs_i: Vec<usize> = stairs.iter().map(|&x| inv_m(x, m)).collect();
    let mut v: Vec<Vec<usize>> = vec![vec![0; n + 1]; b + 1];
    for i in 0..a {
