            v[i][j] = v[i - 1][j];
            for k in c..std::cmp::min(d, j / i) + 1 {
                v[i][j] += v[i - 1][j - k * i] * stairs[n + i * k - j] % m * stairs_i[n - j] % m * stairs_i[k] % m * pow_m(stairs_i[i], k, m) % m;
            }
            v[i][j] %= m;
        }
    }
    println!("{}", v[b][n]);
}

fn pow_m(n: usize, mut p: usize, d: usize) -> usize {
    let mut r = n;
    let mut ret = 1;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % d;
            p /= 2;
        } else {
            ret = ret * r % d;
            p -= 1;
        }
    }
    ret
}

fn inv_m(n: usize, d: usize) -> usize {
    pow_m(n, d - 2, d)
}

