                }
                if j > n + k * i {
                    break;
                }
                let mut temp = dp[i - 1][j - k * i];
                temp *= fact[n - j + k * i];
                temp %= big_int;
                temp *= inv_fact[n - j];
                temp %= big_int;

                temp *= pow_m(inv_fact[i], k as i64, big_int);
                temp %= big_int;

                temp *= inv_fact[k];
