fn ext_gcd(x: i64, y: i64) -> (i64, i64) {
    let mut r0 = x;
    let mut r1 = y;
    let mut x0 = 1;
    let mut y0 = 0;
    let mut x1 = 0;
    let mut y1 = 1;
    while r1 > 0 {
        let q = r0 / r1;
        r0 = r0 % r1;
        std::mem::swap(&mut r0, &mut r1);
        x0 = x0 - q * x1;
        std::mem::swap(&mut x0, &mut x1);
        y0 = y0 - q * y1;
        std::mem::swap(&mut y0, &mut y1);
    }
    (x0, y0)
}

fn inv_mod(x: i64, modulus: i64) -> i64 {
    let res = ext_gcd(x, modulus).0;
    if res < 0 {
        res % modulus + modulus
    } else {
        res % modulus
    }
}

fn pow_mod(x: i64, n: usize, modulus: i64) -> i64 {
    let mut res = 1;
    let mut x = x;
    let mut n = n;
    while n > 0 {
        if n & 1 != 0 {
            res = res * x % modulus;
        }
        x = x * x % modulus;
        n = n >> 1;
    }
    res
}

