    let fact = ModFactorial::new(n as i64, big_int).fact;
    let inv_fact = fact.iter()
        .map(|&x| mod_inverse(x, big_int))
        .collect::<Vec<_>>();

    let mut dp = vec![vec![0i64; n + 1]; n + 1];
    for i in 0..n + 1 {
        dp[i][0] = 1;
    }

    for i in a..b + 1 {
