            dp[i][j] = dp[i - 1][j]; // k = 0;
            for k in c..d + 1 {
                if j < k * i {
                    continue;
                }
                if j > n + k * i {
                    continue;
                }
                let mut temp = dp[i - 1][j - k * i];
                temp *= fact[n - j + k * i];
                temp %= big_int;
                temp *= inv_fact[n - j];
                temp %= big_int;

                temp *= pow_m(inv_fact[i], k as i64, big_int);
                temp %= big_int;

                temp *= inv_fact[k];
                temp %= big_int;
                dp[i][j] += temp;
                dp[i][j] %= big_int;
            }
        }
